/* 明朝体の用意。docs/kanbun/設計.md 5章「書体」。
   端末に明朝体があれば、それを使う（Mac・iPhone のヒラギノ明朝、Windows の游明朝、Android 9 以降の多くの機種の Noto Serif CJK）。
   無い端末（Android 8 以前や、明朝体を持たない機種）でだけ、同梱の明朝体（Noto Serif JP を漢文で使う字だけに絞ったもの。
   scripts/kanbun-font.py で作る）を字の並びに足す。
   有無は、キャンバスに「永」を「端末の明朝体の並び」と sans-serif で描き比べて調べる。同じ絵なら、ゴシックに落ちている。 */

/** kanbun.css の --kb-font と同じ並び（同梱の明朝体を含まない） */
export const SYSTEM_MINCHO = `"Hiragino Mincho ProN", "Yu Mincho", "YuMincho", "Noto Serif JP", "Noto Serif CJK JP", "Source Han Serif JP", serif`;
/** kanbun.css の @font-face の名前 */
export const BUNDLED_FAMILY = "KB Mincho";

export type Draw = (family: string) => ArrayLike<number> | null;

const same = (a: ArrayLike<number>, b: ArrayLike<number>) => {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
};
const blank = (a: ArrayLike<number>) => {
  for (let i = 0; i < a.length; i++) if (a[i] !== 0) return false;
  return true;
};

/** 端末の明朝体で足りるか。"system"＝端末の明朝体がある、"bundle"＝無い（ゴシックに落ちる）、
    "unknown"＝描けない・描くたびに絵が変わる（指紋よけでキャンバスに乱れを入れるブラウザ）ので判定できない */
export type Verdict = "system" | "bundle" | "unknown";
export function decide(draw: Draw): Verdict {
  const a = draw("sans-serif");
  const b = draw("sans-serif");
  if (!a || !b || blank(a) || !same(a, b)) return "unknown";
  const m = draw(SYSTEM_MINCHO);
  if (!m) return "unknown";
  return same(a, m) ? "bundle" : "system";
}

function canvasDraw(family: string): ArrayLike<number> | null {
  try {
    const c = document.createElement("canvas");
    c.width = 40;
    c.height = 40;
    const g = c.getContext("2d", { willReadFrequently: true });
    if (!g) return null;
    g.font = `32px ${family}`;
    g.textBaseline = "top";
    g.fillStyle = "#000";
    g.fillText("永", 4, 4);
    return g.getImageData(0, 0, 40, 40).data;
  } catch {
    return null;
  }
}

let cached: Verdict | undefined;

function verdict(): Verdict {
  // 書体の API が無い環境（jsdom）では調べず、端末の書体のままにする
  if (cached === undefined) cached = typeof document !== "undefined" && document.fonts ? decide(canvasDraw) : "system";
  return cached;
}

/** 字の並びに同梱の明朝体を足すか。判定できないときも足す。並びでは端末の明朝体の名前が先なので、
    名前で見つかる明朝体がある端末（Mac・iPhone・Windows）では、足しても同梱の書体は読み込まれない */
export function useBundledMincho(): boolean {
  return verdict() !== "system";
}

/** 明朝体が無いと分かった端末では、開いたときに読み込みを始める。読み終えたら done を呼ぶ
    （字の形が変わるので、縦書きの欄の送りを直すため）。判定できないときは、要る字が出たときの読み込みに任せる */
export function preloadMincho(done: () => void): void {
  if (verdict() !== "bundle") return;
  document.fonts.load(`16px "${BUNDLED_FAMILY}"`, "漢文").then(done, () => { /* 読めなければ端末の書体のまま */ });
}
