/* 訓点つきの文を描く。1字ごとに .kb-cell の枠を作り、本字の周りに
   右：読み仮名／右下：送り仮名／左下：返り点／左：再読文字の二度目の送り仮名 を置く（docs/kanbun/設計.md 4章「描画」）。
   縦書き・横書きは同じ部品を使い、並べ方と位置だけを kanbun.css で切り替える。 */
import { LINE_BREAK, parse, stripRuby, type Cell, type Token } from "./markup";

export type Stage = "hakubun" | "kundoku" | "kakikudashi" | "yaku";
export const STAGES: { id: Stage; label: string }[] = [
  { id: "hakubun", label: "白文" },
  { id: "kundoku", label: "訓読文" },
  { id: "kakikudashi", label: "書き下し文" },
  { id: "yaku", label: "現代語訳" },
];

export interface KundokuOptions {
  /** 白文として描く（訓点をすべて伏せる） */
  hakubun?: boolean;
  /** この番号の傍線部だけ白文にする（読み四択・書き下し四択の出題） */
  mask?: string;
  /** mask の範囲でも返り点と竪点は残す（解釈四択の出題。共テの紙面と同じく送り仮名・読み仮名だけを伏せる） */
  maskKeepKaeri?: boolean;
  /** この番号の傍線部を朱で示す（学ぶ画面） */
  highlight?: string;
  /** この番号の傍線部に傍線を引き、番号を添える */
  bosen?: string;
  /** この番号の範囲を空欄（四角）にする。漢詩の押韻・対句の空欄補充の出題 */
  blank?: string;
  /** 漢詩で、この句（1から数える）の句末の字を韻字として丸で囲む */
  rhyme?: number[];
}

export function esc(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

// 右の列（読み仮名・送り仮名）の小さい仮名は本字の半分の大きさ。縦書きの枠の高さはこの字数から決める
const KANA = 0.5;
const CHAR = 1.12;

function cellHTML(t: Cell, opts: KundokuOptions, groupRuby: Map<number, { text: string; size: number; first: number }>, index: number, punct: string, rhyme: boolean, ci: number): string {
  const masked = opts.mask != null && t.mark === opts.mask;
  const plain = opts.hakubun || masked;
  // 返り点・竪点は、白文のときと、返り点も伏せる出題のときだけ消す
  const noKaeri = opts.hakubun || (masked && !opts.maskKeepKaeri);
  const cls = ["kb-cell"];
  if (t.okiji) cls.push("kb-okiji");
  if (opts.highlight != null && t.mark === opts.highlight) cls.push("kb-hl");
  if (rhyme) cls.push("kb-rhyme");
  const bl = opts.bosen != null && t.mark === opts.bosen;
  if (bl) cls.push("kb-bl");

  let ruby = plain ? "" : (t.ruby ?? "");
  let rubySpan = 1;
  const g = t.group != null ? groupRuby.get(t.group) : undefined;
  if (!plain && g && g.first === index) { ruby = g.text; rubySpan = g.size; }
  const okuri = plain ? "" : (t.okuri ?? "");
  const left = plain ? "" : (t.leftOkuri ?? "");
  const kaeri = noKaeri ? "" : (t.kaeri ?? "");

  // 縦書きの枠の高さ：右の列（読み仮名＋送り仮名）が本字より長ければ、そのぶん伸ばす
  const rubyLen = ruby ? (ruby.length * KANA) / rubySpan : 0;
  // 熟語のルビは最初の字の右から、まとまり全体の長さで下へ伸びる。2字目以降の送り仮名は、そのルビの下端より下に置く
  const spill = !plain && g && g.first !== index ? g.text.length * KANA - (index - g.first) * CHAR + 0.06 : 0;
  const okuriTop = ruby ? Math.max(rubyLen, 0) : Math.max(0.56, spill);
  const rightLen = okuriTop + okuri.length * KANA;
  const leftLen = 0.56 + left.length * KANA + (kaeri ? kaeri.length * 0.45 : 0);
  // 句読点はその字の枠の中（本字の下）に置く。句読点だけが次の行の頭へ送られないように
  const body = Math.max(CHAR, rightLen + 0.04, leftLen);
  const h = punct ? body + 0.5 : body;
  const style = `--h:${h.toFixed(2)}em;--ot:${okuriTop.toFixed(2)}em;--ol:${okuri.length}`;

  if (okuri) cls.push("kb-has-ok");
  // 読み仮名は本字の箱の中に置く（縦書きは右、横書きは上に、本字を基準にして並べる）
  const rubyHTML = ruby ? `<span class="kb-ruby" style="--rl:${ruby.length}">${esc(ruby)}</span>` : "";
  const parts = [`<span class="kb-ch">${esc(t.ch)}${rubyHTML}</span>`];
  if (okuri) parts.push(`<span class="kb-ok">${esc(okuri)}</span>`);
  if (left || kaeri) {
    parts.push(`<span class="kb-left">${left ? `<span class="kb-lok">${esc(left)}</span>` : ""}${kaeri ? `<span class="kb-kaeri">${esc(kaeri)}</span>` : ""}</span>`);
  }
  if (t.tate && !noKaeri) parts.push(`<span class="kb-tate" aria-hidden="true"></span>`);
  if (punct) parts.push(`<span class="kb-pc">${esc(punct)}</span>`);
  // data-ci は本文の何字目か（白文の字の並びで0から）。書棚の字引で、押した字の位置を知るのに使う
  return `<span class="${cls.join(" ")}" style="${style}" data-ci="${ci}">${parts.join("")}</span>`;
}

/** 訓読文（または白文）を HTML にする。読み上げ用に白文を aria-label に入れる */
export function kundokuHTML(src: string, opts: KundokuOptions = {}): string {
  const { tokens, groups } = parse(src);
  // 熟語のルビは、まとまりの最初の字の右に、まとまり全体の長さで置く
  const groupRuby = new Map<number, { text: string; size: number; first: number }>();
  tokens.forEach((t, i) => {
    if (t.kind !== "char" || t.group == null) return;
    const g = groups.get(t.group);
    if (!g?.ruby) return;
    const cur = groupRuby.get(t.group);
    if (cur) cur.size += 1; else groupRuby.set(t.group, { text: g.ruby, size: 1, first: i });
  });
  // 漢詩：句末の字（韻字の候補）の位置。rhyme に挙げた句の句末だけを丸で囲む
  const poem = tokens.some((t) => t.kind === "punct" && t.ch === LINE_BREAK);
  const rhymeAt = new Set<number>();
  if (opts.rhyme?.length) {
    let line = 1;
    let last = -1;
    const close = () => { if (last >= 0 && opts.rhyme!.includes(line)) rhymeAt.add(last); };
    tokens.forEach((t, i) => {
      if (t.kind === "punct" && t.ch === LINE_BREAK) { close(); line += 1; last = -1; }
      else if (t.kind === "char") last = i;
    });
    close();
  }
  const out: string[] = poem ? [`<span class="kb-pl">`] : [];
  let prevMark: string | undefined;
  let ci = -1;
  tokens.forEach((t: Token, i) => {
    if (t.kind === "char") ci += 1;
    // 漢詩の句の区切り：句ごとに行（縦書きは列）を改める
    if (t.kind === "punct" && t.ch === LINE_BREAK) { out.push(`</span><span class="kb-pl">`); prevMark = undefined; return; }
    // 空欄：字も訓点も出さず、四角の中に空欄の名前（X など）を添える
    if (opts.blank != null && t.mark === opts.blank) {
      if (t.kind === "char") {
        const first = prevMark !== opts.blank;
        out.push(`<span class="kb-cell kb-blank" style="--h:1.18em"><span class="kb-ch kb-box">${first ? `<span class="kb-boxlabel">${esc(opts.blank)}</span>` : ""}</span></span>`);
      }
      prevMark = t.mark;
      return;
    }
    const inBosen = opts.bosen != null && t.mark === opts.bosen;
    if (inBosen && prevMark !== opts.bosen) out.push(`<span class="kb-label" aria-hidden="true">${esc(labelText(opts.bosen!))}</span>`);
    prevMark = t.mark;
    if (t.kind === "punct") {
      // 直前の字に付けた句読点はそこで描いた。文頭の「 などは1字ぶんの枠で描く
      if (i > 0 && tokens[i - 1].kind === "char" && !isOpening(t.ch)) return;
      out.push(`<span class="kb-cell kb-p${inBosen ? " kb-bl" : ""}"><span class="kb-ch">${esc(t.ch)}</span></span>`);
      return;
    }
    const next = tokens[i + 1];
    const punct = next && next.kind === "punct" && !isOpening(next.ch) && next.ch !== LINE_BREAK ? next.ch : "";
    out.push(cellHTML(t, opts, groupRuby, i, punct, rhymeAt.has(i), ci));
  });
  if (poem) out.push(`</span>`);
  // 読み上げ用の白文。空欄は「空欄X」と読ませ、漢詩の句の区切りは読点にする
  let white = "";
  let prev: string | undefined;
  for (const t of tokens) {
    if (opts.blank != null && t.mark === opts.blank) { if (prev !== opts.blank) white += `（空欄${opts.blank}）`; prev = t.mark; continue; }
    prev = t.mark;
    white += t.ch === LINE_BREAK ? "、" : t.ch;
  }
  return `<span class="kb-kd${poem ? " kb-kd-poem" : ""}" role="img" aria-label="${esc(white)}">${out.join("")}</span>`;
}

function isOpening(ch: string): boolean {
  return "「『（〔".includes(ch);
}

/** 傍線部の番号の表示（数字は (1)、カタカナはそのまま） */
export function labelText(label: string): string {
  return /^\d+$/.test(label) ? `(${label})` : label;
}

/** 書き下し文など、{…} の読み仮名を <ruby> にした文。{…} は直前の1字に、[熟語]{…} は熟語全体に付く */
export function rubyTextHTML(text: string): string {
  const out: string[] = [];
  const re = /\[([^\]]+)\]\{([^}]*)\}|([\u3400-\u9fff々])\{([^}]*)\}/gu;
  let last = 0;
  for (const m of text.matchAll(re)) {
    out.push(esc(text.slice(last, m.index)));
    out.push(`<ruby>${esc(m[1] ?? m[3])}<rt>${esc(m[2] ?? m[4])}</rt></ruby>`);
    last = m.index! + m[0].length;
  }
  out.push(esc(text.slice(last)));
  return out.join("");
}

export function plainText(text: string): string {
  return stripRuby(text);
}
