/* 四の門「試」。門をまたいだ共テ型の総合演習と、共通テストの本文の設問を年度ごとに解く。docs/kanbun/設計.md 5章・7章 Phase 6
   - 総合演習：共テの漢文の並び（語の意味 → 読み → 書き下し → 解釈）で10問。種類ごとに 未解答 → 苦手 → 残り の順に選ぶ
   - 返り点の四択：傍線部の読みに合う返り点を選ぶ（共テの「返り点の付け方と書き下し文の組合せ」の返り点の側）
   - 年度別：共テの本文の設問（共テの設問と、本文から作った設問）を、その年度の問題の順に
   - 本番形式（exam:…）：総合演習と年度別を、1問ずつ答えを選んで最後にまとめて採点する形で。時間を計り、目安を示す */
import type { Ctx } from "../index";
import type { Question } from "../schema";
import { gateOf, type Gate } from "../data";
import { kundokuHTML } from "../render";
import { isWeak, loadMeta, loadProgress, type ExamLog } from "../store";
import { esc, topBar } from "../ui";

/** 総合演習の配分（共テの漢文の設問の並びと割合に寄せる）。漢詩は押韻・対句・形式・句の解釈のどれか1問。
    gate を持つ枠は、その門の設問だけから選ぶ（解釈は句形の、漢詩は漢詩の設問） */
export const MIX_PLAN: Array<{ types: Question["type"][]; name: string; n: number; gate?: Gate }> = [
  { types: ["imi"], name: "語の意味", n: 3 },
  { types: ["yomi"], name: "読み", n: 2 },
  { types: ["kakikudashi"], name: "書き下し", n: 1 },
  { types: ["kaeriten"], name: "返り点", n: 1 },
  { types: ["kaishaku"], name: "解釈", n: 2, gate: "ku" },
  { types: ["oin", "taiku", "keishiki", "kaishaku"], name: "漢詩", n: 1, gate: "shi" },
];
const KAERI_N = 10;

/** 本番形式にできる演習の種類（総合演習と年度別）。本番形式は、この前に "exam:" を付ける */
export function examable(mode: string): boolean {
  return mode === "shi:mix" || /^shi:year:\d{4}$/.test(mode);
}

/** 本番形式の目安の時間（秒）。共テの国語は90分で大問5つ、漢文は本文を読む時間を含めて約20分で7〜8問なので、
    年度別は1問2分30秒（上限20分）。総合演習は短い例文なので1問1分 */
export function examLimitSec(mode: string, n: number): number {
  if (mode === "exam:shi:mix") return n * 60;
  return Math.min(20 * 60, n * 150);
}

/** 秒を「分:秒」に（12:05） */
export function clock(sec: number): string {
  const s = Math.max(0, Math.floor(sec));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

/** 本番形式の前回の結果の短い表示（前回 4/6問・12:05） */
function lastLog(log: ExamLog | undefined): string {
  return log ? `前回 ${log.ok}/${log.n}問・${clock(log.sec)}` : "";
}

/** 返り点の決まり（学ぶ側の短い説明）。例は返り点だけを付けた白文と、読む順 */
const KAERI_RULES: Array<{ name: string; src: string; order: string; text: string }> = [
  { name: "レ点", src: "読^レ書", order: "書→読", text: "すぐ下の一字から、一字だけ上へ返る。" },
  { name: "一・二点", src: "登^二泰山^一", order: "泰→山→登", text: "二字以上離れて上へ返る。一点の字まで読んだら二点へ、さらに上へは三点へ。" },
  { name: "上・下点", src: "有^下備^二其事^一者^上", order: "其→事→備→者→有", text: "一・二点をはさんで、さらに上へ返る。上・中・下の順に返る。" },
  { name: "一レ点・上レ点", src: "為^二人所^一レ制", order: "人→制→所→為", text: "まずレ点で一字返り、返ったその字から一点（上点）として二点（下点）へ返る。" },
];

/** 返り点の四択10問。未解答 → 苦手 → 残り の順（中は順不同） */
export function kaeritenQuestions(c: Ctx): Question[] {
  const progress = loadProgress();
  const all = c.data.questions.filter((q) => q.type === "kaeriten");
  const fresh = all.filter((q) => !progress[q.id]?.seen);
  const weak = all.filter((q) => progress[q.id]?.seen && isWeak(progress[q.id]));
  const rest = all.filter((q) => progress[q.id]?.seen && !isWeak(progress[q.id]));
  return [...shuffle(fresh), ...shuffle(weak), ...shuffle(rest)].slice(0, KAERI_N);
}

function shuffle<T>(a: T[]): T[] {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}

/** 総合演習の10問。種類ごとに、未解答 → 苦手 → 残り の順（それぞれの中は順不同）で選び、種類の順に並べる */
export function mixQuestions(c: Ctx): Question[] {
  const progress = loadProgress();
  return MIX_PLAN.flatMap(({ types, n, gate }) => {
    const all = c.data.questions.filter((q) => types.includes(q.type) && (!gate || gateOf(q) === gate));
    const fresh = all.filter((q) => !progress[q.id]?.seen);
    const weak = all.filter((q) => progress[q.id]?.seen && isWeak(progress[q.id]));
    const rest = all.filter((q) => progress[q.id]?.seen && !isWeak(progress[q.id]));
    return [...shuffle(fresh), ...shuffle(weak), ...shuffle(rest)].slice(0, n);
  });
}

/** 例文の出典の年度（共テの本文でなければ null） */
function examYear(c: Ctx, q: Question): number | null {
  const e = c.data.examples.get(q.exampleId);
  if (e?.source.kind !== "exam") return null;
  const m = /^(\d{4})年度/.exec(e.source.label ?? "");
  return m ? Number(m[1]) : null;
}

/** 設問の並び。共テの設問は問の番号（同じ問の中はIDの順）、本文から作った設問はその年度の最後 */
function examOrder(q: Question): number {
  const m = q.source.kind === "exam" ? /問(\d+)/.exec(q.source.label ?? "") : null;
  return m ? Number(m[1]) : 99;
}

/** 共テの本文の設問。year を渡すとその年度だけ。新しい年度から、問の順に並べる */
export function examQuestions(c: Ctx, year?: number): Question[] {
  return c.data.questions
    .map((q) => ({ q, y: examYear(c, q) }))
    .filter((x): x is { q: Question; y: number } => x.y != null && (year == null || x.y === year))
    .sort((a, b) => b.y - a.y || examOrder(a.q) - examOrder(b.q) || a.q.id.localeCompare(b.q.id))
    .map((x) => x.q);
}

/** 収録している共テの年度（新しい順）と、その大問の見出し */
export function examYears(c: Ctx): Array<{ year: number; title: string; work: string; n: number }> {
  const out = new Map<number, { year: number; title: string; work: string; n: number }>();
  for (const q of examQuestions(c)) {
    const y = examYear(c, q)!;
    const e = c.data.examples.get(q.exampleId)!;
    const row = out.get(y) ?? { year: y, title: (e.source.label ?? "").replace(/^\d+年度 大学入学共通テスト /, ""), work: e.work, n: 0 };
    row.n += 1;
    out.set(y, row);
  }
  return [...out.values()];
}

/** 書斎の四の門のタイルに出す数（共テの本文の設問のうち、解いたもの） */
export function examProgress(c: Ctx): { done: number; total: number } {
  const progress = loadProgress();
  const qs = examQuestions(c);
  return { done: qs.filter((q) => (progress[q.id]?.seen ?? 0) > 0).length, total: qs.length };
}

export function shiScreen(c: Ctx): string {
  const progress = loadProgress();
  const logs = loadMeta().examLog;
  const doneOf = (qs: Question[]) => qs.filter((q) => (progress[q.id]?.seen ?? 0) > 0).length;
  const allExam = examQuestions(c);
  const years = examYears(c).map((y) => {
    const qs = examQuestions(c, y.year);
    const mode = `exam:shi:year:${y.year}`;
    const last = lastLog(logs[mode]);
    return `<div class="kb-yearrow">
      <button type="button" class="kb-group" data-kb-go="quiz" data-kb-arg="shi:year:${y.year}">
        <span class="kb-group-title">${y.year}年度</span>
        <span class="kb-group-chars">${esc(y.title)}</span>
        <span class="kb-group-meta">${qs.length}問 ・ 解いた ${doneOf(qs)}/${qs.length}</span>
      </button>
      <button type="button" class="kb-btn kb-yearexam" data-kb-go="quiz" data-kb-arg="${mode}">本番形式<small>目安 ${examLimitSec(mode, qs.length) / 60}分${last ? `・${esc(last)}` : ""}</small></button>
    </div>`;
  }).join("");
  const mixLast = lastLog(logs["exam:shi:mix"]);
  const mixTotal = MIX_PLAN.reduce((a, p) => a + p.n, 0);
  const plan = MIX_PLAN.map((p) => `${p.name}${p.n}`).join("・");
  const poems = c.data.kanshi.size;
  const kaeri = c.data.questions.filter((q) => q.type === "kaeriten");
  const rules = KAERI_RULES.map((r) => `<div class="kb-kaerirule">
      <span class="kb-kaerirule-name">${esc(r.name)}</span>
      <span class="kb-text kb-h kb-kaeritext">${kundokuHTML(r.src)}</span>
      <span class="kb-kaerirule-order">${esc(r.order)}</span>
      <span class="kb-kaerirule-text">${esc(r.text)}</span>
    </div>`).join("");

  return `${topBar({ title: "四の門「試」", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">四の門</span><h2>試<small>共通テスト型の総合演習</small></h2></header>
    <section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="shi:mix"><b>総合演習10問</b><small>語・字・句の門と漢詩をまたいで、共テの並び（${plan}）で出します。まだ解いていない問題と、間違えた問題から先に</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="exam:shi:mix"><b>本番形式で総合演習</b><small>総合演習${mixTotal}問を、1問ずつ答えを選んで最後にまとめて採点します。時間を計ります（目安 ${examLimitSec("exam:shi:mix", mixTotal) / 60}分）${mixLast ? `。${esc(mixLast)}` : ""}</small></button>
      ${poems ? `<button type="button" class="kb-start" data-kb-go="shi-kanshi"><b>漢詩</b><small>形式・押韻・対句の決まりと、名詩${poems}首。押韻の空欄・対句の空欄・形式と押韻の問題</small></button>` : ""}
      ${kaeri.length ? `<button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="shi:kaeriten"><b>返り点の四択</b><small>傍線部の読みに合う返り点を選ぶ（共テの「返り点の付け方」の形）。${KAERI_N}問ずつ、まだ解いていない問題から（全${kaeri.length}問・解いた ${doneOf(kaeri)}）</small></button>` : ""}
      ${allExam.length ? `<button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="shi:exam"><b>共通テストの設問をまとめて</b><small>収録した年度の本文の設問を、新しい年度から問の順に（${allExam.length}問・解いた ${doneOf(allExam)}）</small></button>` : ""}
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">返り点の決まり<small>返り点の付いた字は後回しにし、下を読んでから返る。置き字は読まない。</small></h3>
      <div class="kb-kaerirules">${rules}</div></section>
    ${years ? `<section class="kb-sec"><h3 class="kb-sec-title">年度ごとに解く<small>共通テスト本試験の漢文の本文で、その年度の設問を問1から順に。本文から作った設問はその年度の最後に出します。「本番形式」は、答えをまとめて採点し、時間を計ります。</small></h3>
      <div class="kb-groups kb-yeargroups">${years}</div></section>` : ""}
    <p class="kb-foot">共通テストの本文と設問は大学入試センターの問題冊子により、正解は同センターの公表によります。返り点の組合せを問う設問は、書き下し文を選ぶ形にしています。返り点の四択は、例文の返り点をもとに本アプリで作成しました。</p>`;
}
