/* 書棚の字引（docs/kanbun/設計.md 7章 Phase 7 その1）。
   - 字引の画面（jibiki）：入力欄に字・熟語・読みを入れて引く。arg は引いた語。空のときは索引（同訓異字の読み・多訓字の字）
   - 字引の札（sheetHTML）：本文の字を押したとき、画面の下に開く。index.ts が .kb-app に差し込み、札の外を押すと閉じる */
import type { Ctx } from "../index";
import { atCell, HIT_KINDS, searchJibiki, type Hit } from "../jibiki";
import { rubyTextHTML } from "../render";
import { esc, topBar } from "../ui";

/** 札で1つの種類に出す数（残りは「字引で引く」から） */
const SHEET_N = 5;

/** 結果の1行。押すと学ぶ画面のカードへ（束は束の画面へ） */
function hitHTML(h: Hit): string {
  const target = h.kind === "group" ? `data-kb-go="ji-group" data-kb-arg="${esc(h.id)}"` : `data-kb-jump="${esc(h.id)}"`;
  const yomi = h.kind === "kukei" ? rubyTextHTML(h.yomi) : esc(h.yomi);
  return `<li><button type="button" class="kb-hit" ${target}>
    <span class="kb-hit-head">${esc(h.head)}</span>
    <span class="kb-hit-yomi">${yomi}</span>
    <span class="kb-hit-gloss">${esc(h.gloss)}</span>
  </button></li>`;
}

function groupedHTML(hits: Hit[], limit?: number, more?: string): string {
  return HIT_KINDS.map(({ kind, label }) => {
    const xs = hits.filter((h) => h.kind === kind);
    if (!xs.length) return "";
    const shown = limit ? xs.slice(0, limit) : xs;
    const rest = xs.length - shown.length;
    return `<section class="kb-hits" data-kb-kind="${kind}">
      <h4 class="kb-hits-title">${label}<small>${xs.length}</small></h4>
      <ul class="kb-hitlist">${shown.map(hitHTML).join("")}</ul>
      ${rest > 0 && more ? `<button type="button" class="kb-btn kb-ghost kb-hits-more" data-kb-go="jibiki" data-kb-arg="${esc(more)}">ほか ${rest} 件を字引で見る</button>` : ""}
    </section>`;
  }).join("");
}

/** 字引の結果の部分（入力のたびに index.ts がここだけを描き直す） */
export function jibikiResultsHTML(c: Ctx, query: string): string {
  const r = searchJibiki(c.data, query);
  if (r.mode === "empty") return indexHTML(c);
  if (!r.hits.length) return `<p class="kb-empty">「${esc(r.query)}」は見つかりませんでした。字は1字ずつ、読みは「すなはち」「すなわち」のどちらでも引けます。</p>`;
  const counts = HIT_KINDS.map(({ kind, label }) => ({ label, n: r.hits.filter((h) => h.kind === kind).length })).filter((x) => x.n);
  return `<p class="kb-hint">「${esc(r.query)}」を${r.mode === "kana" ? "読み" : "字"}で引きました：${counts.map((x) => `${x.label.replace(/（.*）/, "")} ${x.n}`).join("・")}</p>${groupedHTML(r.hits)}`;
}

/** 空のときの索引：同訓異字は読みで、多訓字は字で並べる。押すとその語で引く */
function indexHTML(c: Ctx): string {
  const chip = (q: string, label = q) => `<button type="button" class="kb-chip" data-kb-q="${esc(q)}">${esc(label)}</button>`;
  const doukun = c.data.groups.filter((g) => g.kind === "doukun");
  const takun = c.data.groups.filter((g) => g.kind === "takun");
  return `<section class="kb-sec"><h3 class="kb-sec-title">同訓異字の読みから<small>読みが同じ別の字。押すと、その読みで引きます。</small></h3>
      <div class="kb-chips">${doukun.map((g) => chip(g.title.split("・")[0], g.title)).join("")}</div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">多訓字から<small>読み方の多い字。</small></h3>
      <div class="kb-chips kb-chips-kanji">${takun.map((g) => chip(g.title)).join("")}</div></section>`;
}

export function jibikiScreen(c: Ctx): string {
  const q = c.arg ?? "";
  return `${topBar({ title: "字引", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">書棚</span><h2>字引<small>字・熟語・読みから引く</small></h2></header>
    <form class="kb-search" role="search" data-kb-searchform>
      <input type="search" class="kb-search-input" data-kb-search value="${esc(q)}" placeholder="字・熟語・読み（例：則・すなわち）" aria-label="字引で引く語" autocomplete="off" enterkeyhint="search">
    </form>
    <p class="kb-hint">${c.meta.lookup ? "学ぶ画面や解説の本文の字を押しても、その字を引けます。" : "本文の字を押して引く設定は、書斎の「表示の設定」で「する」にできます。"}</p>
    <div class="kb-results" data-kb-results aria-live="polite">${jibikiResultsHTML(c, q)}</div>`;
}

/** 本文の字を押したときの札。見つからなければ空 */
export function sheetHTML(c: Ctx, exampleId: string, ci: number): string {
  const r = atCell(c.data, exampleId, ci);
  if (!r) return "";
  const block = (label: string, hits: Hit[]) => (hits.length
    ? `<section class="kb-hits"><h4 class="kb-hits-title">${label}</h4><ul class="kb-hitlist">${hits.map(hitHTML).join("")}</ul></section>`
    : "");
  // 字で引いた結果から、上の2つに出したものは除く
  const shown = new Set([...r.here, ...r.words].map((h) => h.id));
  const rest = r.hits.filter((h) => !shown.has(h.id));
  return `<aside class="kb-sheet" role="dialog" aria-modal="false" aria-label="字引「${esc(r.ch)}」">
    <header class="kb-sheet-head">
      <span class="kb-sheet-ch">${esc(r.ch)}</span>
      <span class="kb-sheet-label">字引</span>
      <button type="button" class="kb-btn kb-ghost kb-sheet-open" data-kb-go="jibiki" data-kb-arg="${esc(r.ch)}">字引で引く</button>
      <button type="button" class="kb-btn kb-ghost kb-sheet-close" data-kb-act="sheet-close" aria-label="閉じる">×</button>
    </header>
    <div class="kb-sheet-body">
      ${block("この本文で学ぶ項目", r.here)}
      ${block("この位置の語", r.words)}
      ${rest.length ? groupedHTML(rest, SHEET_N, r.ch) : `<p class="kb-empty">「${esc(r.ch)}」を見出しに持つ項目は、ほかにありません。</p>`}
    </div>
  </aside>`;
}
