/* 三の門「句」。学ぶ＝分類ごとの句形カード（型・書き下し・意味・要点・紛らわしい句形）と例文の4段、
   解く＝書き下し四択・解釈四択。docs/kanbun/設計.md 5章 */
import type { Ctx } from "../index";
import type { Kukei, KukeiCat, Question } from "../schema";
import { KUKEI_CATS } from "../schema";
import { gateOf } from "../data";
import { kundokuHTML, rubyTextHTML } from "../render";
import { isWeak, loadProgress } from "../store";
import { esc, exampleCard, topBar, type ExampleView } from "../ui";
import { dueItems, REVIEW_N } from "./review";

interface CatInfo { title: string; lead: string }

/** 15分類の見出しと説明（docs/kanbun/網羅表.md 2章の並び）。句形が1つも無い分類は「準備中」と出す */
export const KU_CATS: Record<KukeiCat, CatInfo> = {
  saidoku: { title: "再読文字", lead: "一字を二度読む字。一度目は返り点を無視して副詞として読み、下から返って二度目を助動詞・動詞として読む。" },
  hitei: { title: "否定の基本", lead: "何を打ち消すかで字が変わる。不（ず）・非（あらず）・無（なし）・莫（なし）と、不能・不可。" },
  nijuu: { title: "二重否定", lead: "否定を二つ重ねて強い肯定にする。「〜しないものはない」「〜しなければならない」と訳す。" },
  bubun: { title: "部分否定と全部否定", lead: "否定の字と副詞の語順で意味が変わる。不＋副詞は部分否定、副詞＋不は全部否定。" },
  kinshi: { title: "禁止", lead: "勿・毋・無・莫を「なかれ」と読んで「〜してはならない」。不可（べからず）も戒めの文では禁止になる。" },
  gimon: { title: "疑問", lead: "何・安・孰・誰・乎 などで問う。文末が連体形（〜する・〜か）なら疑問。何如（どうか）と如何（どうしようか）の区別も要点。" },
  hango: { title: "反語", lead: "「どうして〜しようか、いや〜しない」。文末を推量の「ん（や）」で結ぶ。豈・安・何・誰・孰・寧・敢不 など。" },
  shieki: { title: "使役", lead: "使・令・教・遣を「しむ」と読み、「ＡをしてＢせしむ（ＡにＢさせる）」。書き下しでは「しむ」をひらがなにする。" },
  ukemi: { title: "受身", lead: "見・被（る・らる）、為Ａ所Ｂ（ＡのＢする所と為る）、動詞＋於＋人（人に〜せらる）で「〜される」を表す。" },
  hikaku: { title: "比較・選択", lead: "Ａ於Ｂ（ＢよりもＡ）・不如（しかず）・莫如（しくはなし）で比べ、寧・与其で二つのうち一方を選ぶ。" },
  katei: { title: "仮定", lead: "如・若（もし）・苟（いやしくも）・縦（たとひ）・雖（いへども）・微（なかりせば）など。下を「〜ば」「〜とも」で受ける。" },
  gentei: { title: "限定・累加", lead: "唯・独（ただ・ひとり）、耳・而已（のみ）で限定し、非唯・豈唯（ただに〜のみならず）で「〜だけではない」と加える。" },
  yokuyou: { title: "抑揚", lead: "「ＡすらかつＢ、況んやＣをや」。軽いものを先に挙げて抑え、重いものを「まして」と持ち上げる。" },
  eitan: { title: "詠嘆", lead: "嗚呼（ああ）、哉・夫（かな）、何〜也・不亦〜乎・豈不〜哉（なんと〜ではないか）で感動を表す。" },
  ganbou: { title: "願望", lead: "願・請（ねがはくは・こふ）と欲（ほつす）。文末が命令形なら相手への願い、「〜ん」なら自分の願い。" },
};
export const KU_CAT_LABEL: Record<string, string> = Object.fromEntries(KUKEI_CATS.map((k) => [k, KU_CATS[k].title]));

/** 表に出す句形の名前。読み（括弧の中）は書き下しの欄にあるので省く */
function shortName(k: Kukei): string {
  return k.name.replace(/（[^）]*）/g, "");
}

/** 分類のカードに並べる句形の字。読み（括弧の中）は省き、同じ字は1回だけ並べる（何（なんぞ）・何（なにをか）→ 何） */
function catChars(ks: Kukei[]): string {
  return [...new Set(ks.flatMap((k) => shortName(k).split("・")))].join("・");
}

export function kukeiOfCat(c: Ctx, cat: string): Kukei[] {
  return [...c.data.kukei.values()].filter((k) => k.cat === cat);
}

/** 分類につながる設問（分類のどれかの句形を refs に持つもの） */
export function questionsOfCat(c: Ctx, cat: string): Question[] {
  const ids = new Set(kukeiOfCat(c, cat).map((k) => k.id));
  return c.data.questions.filter((q) => q.refs.some((r) => ids.has(r)));
}

export function kuScreen(c: Ctx): string {
  const tab = c.arg === "solve" ? "solve" : "learn";
  const progress = loadProgress();
  const tabs = `<div class="kb-tabs" role="tablist">
    <button type="button" role="tab" class="kb-tab${tab === "learn" ? " is-on" : ""}" aria-selected="${tab === "learn"}" data-kb-go="ku" data-kb-arg="learn" data-kb-replace="1"><b>学ぶ</b><small>句形と例文</small></button>
    <button type="button" role="tab" class="kb-tab${tab === "solve" ? " is-on" : ""}" aria-selected="${tab === "solve"}" data-kb-go="ku" data-kb-arg="solve" data-kb-replace="1"><b>解く</b><small>書き下し・解釈の四択</small></button>
  </div>`;

  const catCard = (cat: KukeiCat, solve: boolean) => {
    const ks = kukeiOfCat(c, cat);
    const info = KU_CATS[cat];
    if (!ks.length) {
      return `<div class="kb-group is-soon" aria-disabled="true"><span class="kb-group-title">${esc(info.title)}</span><span class="kb-group-meta">準備中</span></div>`;
    }
    const done = ks.filter((k) => (progress[k.id]?.seen ?? 0) > 0).length;
    const qs = questionsOfCat(c, cat);
    const target = solve ? `data-kb-go="quiz" data-kb-arg="cat:${cat}"` : `data-kb-go="ku-cat" data-kb-arg="${cat}"`;
    return `<button type="button" class="kb-group" ${target}>
      <span class="kb-group-title">${esc(info.title)}</span>
      <span class="kb-group-chars">${esc(catChars(ks))}</span>
      <span class="kb-group-meta">${solve ? `${qs.length}問` : `${ks.length}型`} ・ 学習済 ${done}/${ks.length}</span>
    </button>`;
  };
  const opened = KUKEI_CATS.filter((k) => kukeiOfCat(c, k).length);
  const soon = KUKEI_CATS.filter((k) => !kukeiOfCat(c, k).length);

  let body: string;
  if (tab === "learn") {
    body = `<section class="kb-sec"><h3 class="kb-sec-title">句形<small>分類を選ぶと、型・書き下し・意味と例文が並ぶ。</small></h3>
      <div class="kb-groups">${opened.map((k) => catCard(k, false)).join("")}</div></section>
      ${soon.length ? `<section class="kb-sec"><h3 class="kb-sec-title">これから開く分類<small>疑問・反語・使役・受身などは順に足していく。</small></h3>
      <div class="kb-groups kb-soon-list">${soon.map((k) => catCard(k, false)).join("")}</div></section>` : ""}`;
  } else {
    const all = c.data.questions.filter((q) => gateOf(q) === "ku");
    const weak = all.filter((q) => isWeak(progress[q.id])).length;
    const due = dueItems("ku").length;
    const fresh = all.filter((q) => !(progress[q.id]?.seen)).length;
    const nType = (t: string) => all.filter((q) => q.type === t).length;
    const nExam = all.filter((q) => c.data.examples.get(q.exampleId)?.source.kind === "exam").length;
    body = `<section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="ku:random"><b>おまかせ10問</b><small>まだ解いていない問題と、間違えた問題から先に出します（未解答 ${fresh}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:kakikudashi"><b>書き下し四択</b><small>傍線部を白文にして、正しい書き下し文を選ぶ（${nType("kakikudashi")}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:kaishaku"><b>解釈四択</b><small>返り点だけを残した傍線部の意味を選ぶ（${nType("kaishaku")}問）</small></button>
      ${nExam ? `<button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:exam"><b>共通テストの本文で解く</b><small>共テの本文（長文）で句形を問う。共テの設問と、本文から作った設問（${nExam}問）</small></button>` : ""}
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:review" ${due ? "" : "disabled"}><b>今日の復習</b><small>${due ? `忘れかけた ${due} 型（1回に ${REVIEW_N} 問まで）` : "今日の分はありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:weak" ${weak ? "" : "disabled"}><b>苦手だけ</b><small>${weak ? `間違えたままの ${weak}問` : "まだありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ku:all"><b>全問</b><small>${all.length}問を順不同で</small></button>
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">分類ごとに解く</h3><div class="kb-groups">${opened.map((k) => catCard(k, true)).join("")}</div></section>`;
  }
  return `${topBar({ title: "三の門「句」", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">三の門</span><h2>句<small>句形と実例</small></h2></header>
    ${tabs}${body}`;
}

/** 分類の画面の例文カード。段の切り替えのたびに引き直す */
export function catViews(c: Ctx): Map<string, ExampleView> {
  const out = new Map<string, ExampleView>();
  for (const k of kukeiOfCat(c, c.arg ?? "")) {
    for (const eid of k.exampleIds) {
      const e = c.data.examples.get(eid);
      if (!e) continue;
      const key = `${k.id}/${eid}`;
      out.set(key, { key, example: e, stage: c.stages.get(key) ?? "kundoku", highlight: "1" });
    }
  }
  return out;
}

/** 型（未ダ^レＡセ など）。短いので縦書きの設定でも横に並べる */
function formHTML(form: string): string {
  return `<div class="kb-text kb-h kb-formtext">${kundokuHTML(form)}</div>`;
}

export function catScreen(c: Ctx): string {
  const cat = c.arg as KukeiCat | undefined;
  const info = cat ? KU_CATS[cat] : undefined;
  const ks = cat ? kukeiOfCat(c, cat) : [];
  if (!info || !ks.length) return `${topBar({ title: "三の門「句」", back: { label: "句" } }, c.meta)}<p class="kb-empty">この分類は見つかりませんでした。</p>`;
  const views = catViews(c);

  const table = `<table class="kb-table">
    <thead><tr><th scope="col">句形</th><th scope="col">書き下し</th><th scope="col">意味</th></tr></thead>
    <tbody>${ks.map((k) => `<tr><th scope="row" class="kb-table-kanji"><button type="button" class="kb-jump" data-kb-jump="${esc(k.id)}">${esc(shortName(k))}</button></th><td class="kb-table-yomi">${rubyTextHTML(k.kakikudashi)}</td><td>${esc(k.meaning)}</td></tr>`).join("")}</tbody>
  </table>`;

  const cards = ks.map((k) => {
    const exs = k.exampleIds.map((eid) => views.get(`${k.id}/${eid}`)).filter((v): v is ExampleView => !!v);
    const contrast = k.contrast
      ? `<div class="kb-contrast">
          <div class="kb-contrast-col"><span class="kb-contrast-label">部分否定</span>${formHTML(k.form)}<p class="kb-kukei-kk">${rubyTextHTML(k.kakikudashi)}</p><p class="kb-contrast-mean">${esc(k.meaning)}</p></div>
          <div class="kb-contrast-col"><span class="kb-contrast-label">${esc(k.contrast.label)}</span>${formHTML(k.contrast.form)}<p class="kb-kukei-kk">${rubyTextHTML(k.contrast.kakikudashi)}</p><p class="kb-contrast-mean">${esc(k.contrast.meaning)}</p></div>
        </div>`
      : `<div class="kb-kukei-form">${formHTML(k.form)}<div><p class="kb-kukei-kk">${rubyTextHTML(k.kakikudashi)}</p><p class="kb-usage-gloss">${esc(k.meaning)}</p></div></div>`;
    const conf = k.confusables.length
      ? `<div class="kb-confusables"><h4>紛らわしい句形</h4><ul>${k.confusables.map((x) => {
          const ref = x.ref ? c.data.kukei.get(x.ref) : undefined;
          const chip = ref ? `<button type="button" class="kb-jump kb-chip" data-kb-jump="${esc(ref.id)}">${esc(ref.name)}</button>` : "";
          return `<li>${chip}${esc(x.text)}</li>`;
        }).join("")}</ul></div>`
      : "";
    return `<article class="kb-usage kb-kukei" id="${esc(k.id)}">
      <header class="kb-usage-head"><span class="kb-usage-kanji">${esc(k.name)}</span><span class="kb-rank" title="頻出度">${k.rank}</span></header>
      ${contrast}
      ${k.points.length ? `<ul class="kb-points">${k.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}
      ${conf}
      ${exs.map((v) => exampleCard(v, c.meta)).join("")}
    </article>`;
  }).join("");

  const qs = questionsOfCat(c, cat!);
  return `${topBar({ title: `句形「${info.title}」`, back: { label: "句" } }, c.meta)}
    <header class="kb-grouphead">
      <span class="kb-grouphead-kind">三の門　句形</span>
      <h2>${esc(info.title)}</h2>
      <p class="kb-grouphead-chars">${esc(catChars(ks))}</p>
      <p class="kb-grouphead-lead">${esc(info.lead)}</p>
    </header>
    ${table}
    <p class="kb-hint">型の中の「Ａ」「Ｂ」には語が入ります。例文の<span class="kb-hint-hl">朱の部分</span>が、その句形を使った所です。段のボタンで 白文 → 訓読文 → 書き下し文 → 現代語訳 を切り替えられます。</p>
    ${cards}
    <div class="kb-actions"><button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="cat:${esc(cat!)}">この分類を解く（${qs.length}問）</button></div>`;
}
