/* 書棚の字引（docs/kanbun/設計.md 7章 Phase 7 その1）。
   - searchJibiki：字・熟語・読みから、用法・束・語・句形・漢詩・常識を引く。
     読みは歴史的仮名遣いでも現代仮名遣いでも引けるように、両方を looseKana で同じ形にそろえて比べる（すなわち＝すなはち、いう＝いふ）。
   - atCell：本文の字を押したとき、その字と位置から引く（この本文で学ぶ項目・この位置にかかる語・その字の項目）。 */
import type { KanbunData } from "./data";
import { parse } from "./markup";

export type HitKind = "usage" | "group" | "vocab" | "kukei" | "kanshi" | "joshiki";

export interface Hit {
  kind: HitKind;
  id: string;
  /** 見出し（字・語・句形の名・詩の題・人物や書物の名） */
  head: string;
  /** 読み（句形は書き下しの型、漢詩は作者と形式、常識は読み） */
  yomi: string;
  /** 意味・説明の短い一行 */
  gloss: string;
}

/** 結果の並びと見出し */
export const HIT_KINDS: { kind: HitKind; label: string }[] = [
  { kind: "usage", label: "字の用法" },
  { kind: "group", label: "束（同訓異字・多訓字）" },
  { kind: "vocab", label: "語" },
  { kind: "kukei", label: "句形" },
  { kind: "kanshi", label: "漢詩" },
  { kind: "joshiki", label: "常識" },
];

const CJK = /[㐀-鿿豈-﫿々]/u;
const HIRA_A = "あかさたなはまやらわがざだばぱ";
const HIRA_O = "おこそとのほもよろおごぞどぼぽ";
const HIRA_E = "えけせてねへめれげぜでべぺ";
const HIRA_I = "いきしちにひみりぎじぢびぴ";

/** カタカナをひらがなに */
export function toHiragana(s: string): string {
  return s.replace(/[ァ-ヶ]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0x60));
}

/** 読みを比べるための形。歴史的仮名遣いと現代仮名遣いの違いを、おおまかにそろえる。
    ゐ→い・ゑ→え・を→お・ぢ→じ・づ→ず・くわ→か、語頭以外のは行→わ行（すなはち→すなわち・いふ→いう）、
    「あ段＋う」→「お段＋う」（やう→よう・かう→こう）、「え段＋う」→「い段＋よう」（せう→しよう・えう→よう）、
    「い段＋う」→「い段＋ゆう」（きう→きゆう）、小さい ゃゅょ は大きい字に（現代仮名遣いの側も同じ形になる）。
    かな以外（漢字・記号・空白）は落とす */
export function looseKana(s: string): string {
  let t = toHiragana(s).replace(/[^ぁ-ゖー]/g, "");
  t = t.replace(/[ゃゅょ]/g, (c) => ({ "ゃ": "や", "ゅ": "ゆ", "ょ": "よ" })[c]!);
  t = t.replace(/ゐ/g, "い").replace(/ゑ/g, "え").replace(/を/g, "お").replace(/ぢ/g, "じ").replace(/づ/g, "ず").replace(/くわ/g, "か").replace(/ぐわ/g, "が");
  t = t.replace(/(?<=.)[はひふへほ]/g, (c) => ({ "は": "わ", "ひ": "い", "ふ": "う", "へ": "え", "ほ": "お" })[c]!);
  t = t.replace(/([^う])う/g, (m, c: string) => {
    const a = HIRA_A.indexOf(c);
    if (a >= 0) return `${HIRA_O[a]}う`;
    if (c === "え") return "よう";
    const e = HIRA_E.indexOf(c);
    if (e >= 0) return `${HIRA_I[e]}よう`;
    if (HIRA_I.includes(c)) return `${c}ゆう`;
    return m;
  });
  return t;
}

/** 句形の書き下しの型から、読みだけを取り出す（未{いま}だＡせず → いまだせず） */
function kukeiReading(kk: string): string {
  return kk.replace(/\[[^\]]*\]\{([^}]*)\}/g, "$1").replace(/[㐀-鿿々]\{([^}]*)\}/gu, "$1");
}

/** 見出しの括弧（女（汝）・何（なんぞ））を外した形と、括弧の中の別の字 */
function heads(word: string): string[] {
  const core = word.replace(/（[^）]*）/g, "");
  const inner = [...word.matchAll(/（([^）]*)）/g)].map((m) => m[1]).filter((x) => CJK.test(x));
  return [core, ...inner].filter(Boolean);
}

function stripKukeiName(name: string): string {
  return name.replace(/（[^）]*）/g, "").replace(/[Ａ-Ｚ]/g, "");
}

/** すべての項目を、引くための形にしておく（教材は変わらないので1回だけ作る）。kana は looseKana でそろえた読み */
interface Entry { hit: Hit; kanji: string[]; kana: string[] }
let entries: Entry[] | null = null;

function build(d: KanbunData): Entry[] {
  if (entries) return entries;
  const out: Entry[] = [];
  for (const u of d.usages.values()) {
    out.push({ hit: { kind: "usage", id: u.id, head: u.kanji, yomi: u.yomi, gloss: u.gloss }, kanji: [u.kanji], kana: [u.yomi] });
  }
  for (const g of d.groups) {
    const kind = g.kind === "doukun" ? "同訓異字" : "多訓字";
    out.push({ hit: { kind: "group", id: g.id, head: g.title, yomi: kind, gloss: g.chars }, kanji: [g.chars, g.title], kana: [g.title] });
  }
  for (const v of d.vocab.values()) {
    out.push({ hit: { kind: "vocab", id: v.id, head: v.word, yomi: v.yomi, gloss: v.meanings[0] }, kanji: heads(v.word), kana: [v.yomi] });
  }
  for (const k of d.kukei.values()) {
    out.push({ hit: { kind: "kukei", id: k.id, head: k.name, yomi: k.kakikudashi, gloss: k.meaning }, kanji: [stripKukeiName(k.name)], kana: [kukeiReading(k.kakikudashi)] });
  }
  for (const s of d.kanshi.values()) {
    out.push({ hit: { kind: "kanshi", id: s.id, head: s.title, yomi: s.poet, gloss: `${s.era}・${s.poet}` }, kanji: [s.title, s.poet], kana: [] });
  }
  for (const j of d.joshiki.values()) {
    out.push({ hit: { kind: "joshiki", id: j.id, head: j.name, yomi: j.yomi, gloss: j.summary }, kanji: [j.name, ...j.keywords], kana: [j.yomi] });
  }
  for (const e of out) e.kana = e.kana.map(looseKana).filter(Boolean);
  entries = out;
  return out;
}

export interface JibikiResult {
  query: string;
  /** 引き方：字（漢字を含む）・読み（かなだけ）・空 */
  mode: "kanji" | "kana" | "empty";
  hits: Hit[];
}

/** 字・熟語・読みで引く。漢字を含めば見出しに含むものを、かなだけなら読みに含むものを出す。
    並びは HIT_KINDS の順で、その中は見出し（読み）がちょうど一致するもの → 前方一致 → そのほか（教材の順） */
export function searchJibiki(d: KanbunData, query: string): JibikiResult {
  const q = query.trim();
  const list = build(d);
  if (!q) return { query: q, mode: "empty", hits: [] };
  const kanjiQ = [...q].filter((c) => CJK.test(c)).join("");
  let scored: { hit: Hit; score: number }[];
  let mode: JibikiResult["mode"];
  if (kanjiQ) {
    mode = "kanji";
    scored = list.flatMap((e) => {
      const best = Math.min(...e.kanji.map((k) => (k === kanjiQ ? 0 : k.startsWith(kanjiQ) ? 1 : k.includes(kanjiQ) ? 2 : 9)));
      return best < 9 ? [{ hit: e.hit, score: best }] : [];
    });
  } else {
    mode = "kana";
    const lq = looseKana(q);
    if (!lq) return { query: q, mode: "empty", hits: [] };
    scored = list.flatMap((e) => {
      const best = Math.min(9, ...e.kana.map((lk) => (lk === lq ? 0 : lk.startsWith(lq) ? 1 : lk.includes(lq) ? 2 : 9)));
      return best < 9 ? [{ hit: e.hit, score: best }] : [];
    });
  }
  const order = new Map(HIT_KINDS.map((k, i) => [k.kind, i]));
  const hits = scored
    .map((x, i) => ({ ...x, i }))
    .sort((a, b) => order.get(a.hit.kind)! - order.get(b.hit.kind)! || a.score - b.score || a.i - b.i)
    .map((x) => x.hit);
  return { query: q, mode, hits };
}

export interface CellLookup {
  ch: string;
  /** この本文で学ぶ項目（その例文を持つ語・用法・句形・漢詩・常識） */
  here: Hit[];
  /** この位置にかかる2字以上の語・用法（大丈夫・所以 など） */
  words: Hit[];
  /** その字で引いた結果 */
  hits: Hit[];
}

/** 本文の ci 字目（白文の字の並びで0から）を押したときの字引 */
export function atCell(d: KanbunData, exampleId: string, ci: number): CellLookup | null {
  const e = d.examples.get(exampleId);
  if (!e) return null;
  const chars = parse(e.kundoku).tokens.filter((t) => t.kind === "char").map((t) => t.ch);
  const ch = chars[ci];
  if (!ch) return null;
  const text = chars.join("");
  const list = build(d);
  const byId = new Map(list.map((x) => [x.hit.id, x.hit]));

  const hereIds = [
    ...[...d.vocab.values()].filter((v) => v.exampleIds.includes(e.id)).map((v) => v.id),
    ...[...d.usages.values()].filter((u) => u.exampleIds.includes(e.id)).map((u) => u.id),
    ...[...d.kukei.values()].filter((k) => k.exampleIds.includes(e.id)).map((k) => k.id),
    ...[...d.kanshi.values()].filter((k) => k.exampleId === e.id).map((k) => k.id),
    ...[...d.joshiki.values()].filter((j) => j.exampleIds.includes(e.id)).map((j) => j.id),
  ];
  const here = hereIds.map((id) => byId.get(id)!).filter(Boolean);

  // この位置にかかる語：見出しが本文に出て、その範囲に押した字が入るもの
  const covers = (w: string) => {
    if (w.length < 2) return false;
    for (let at = text.indexOf(w); at >= 0; at = text.indexOf(w, at + 1)) if (at <= ci && ci < at + w.length) return true;
    return false;
  };
  const words = list.filter((x) => (x.hit.kind === "vocab" || x.hit.kind === "usage") && x.kanji.some(covers)).map((x) => x.hit);

  return { ch, here, words, hits: searchJibiki(d, ch).hits };
}
