/* 書斎（漢文のホーム）。縦書きの題字と朱印、四つの門、書棚（字引・常識）、温習・苦手帳の帯、表示の設定。 */
import type { Ctx } from "../index";
import { learningItemIds, type Gate } from "../data";
import { isWeak, loadProgress } from "../store";
import { esc, topBar } from "../ui";
import { dueItems, gateProgress, nextDue, stackMeter } from "./review";
import { examProgress } from "./shi";

interface GateTile { no: string; name: string; desc: string; screen?: Gate | "shi"; unit?: string }
const GATES: GateTile[] = [
  { no: "一", name: "語", desc: "重要語。大丈夫＝立派な男子、故人＝旧友、走＝逃げる…の現代語とずれる語と、人物・副詞の語　意味の四択と暗記カード", screen: "go", unit: "語" },
  { no: "二", name: "字", desc: "読みと用法。すなはち・たまたま・つひに…の同訓異字と、之・其・而・為・与…の多訓字　傍線部の読み四択", screen: "ji", unit: "用法" },
  { no: "三", name: "句", desc: "句形。再読文字・否定・疑問・反語・使役・受身・比較・仮定・抑揚…　書き下しと解釈の四択", screen: "ku", unit: "型" },
  { no: "四", name: "試", desc: "共通テスト型の総合演習と、漢詩（形式・押韻・対句）。返り点の四択と、共テ本試験の本文の設問を年度ごとに", screen: "shi", unit: "首" },
];

export function homeScreen(c: Ctx): string {
  const progress = loadProgress();
  const seen = (ids: string[]) => ids.filter((id) => (progress[id]?.seen ?? 0) > 0).length;
  const items = learningItemIds();
  const learned = seen(items);
  const weak = c.data.questions.filter((q) => isWeak(progress[q.id])).length;
  const due = dueItems().length;
  const next = nextDue();
  const streak = c.meta.streakDays;

  const gates = GATES.map((g) => {
    const open = !!g.screen;
    let meter = `<span class="kb-gate-soon">準備中</span>`;
    if (g.screen === "shi") {
      // 四の門の学習項目は漢詩。帯は漢詩の進み具合、下の行に共テの設問の数
      const e = examProgress(c);
      const p = gateProgress(c, "shi");
      meter = `<span class="kb-gate-meter">${stackMeter(p)}<span>漢詩 ${p.mastered + p.learning} / ${p.total} ${g.unit}</span></span>
      <span class="kb-gate-sub"><span>共テの設問 ${e.done} / ${e.total} 問</span>${p.due ? `<span class="kb-gate-due">復習 ${p.due}</span>` : ""}</span>`;
    } else if (g.screen) {
      // 帯は 定着（濃い朱）・学習中（淡い朱）。数は「解いた項目 / 全体」と、定着・今日の復習
      const p = gateProgress(c, g.screen);
      meter = `<span class="kb-gate-meter">${stackMeter(p)}<span>${p.mastered + p.learning} / ${p.total} ${g.unit}</span></span>
      <span class="kb-gate-sub"><span>定着 ${p.mastered}</span>${p.due ? `<span class="kb-gate-due">復習 ${p.due}</span>` : ""}</span>`;
    }
    return `<button type="button" class="kb-gate${open ? "" : " is-soon"}" ${open ? `data-kb-go="${g.screen}"` : "disabled aria-disabled=\"true\""}>
      <span class="kb-gate-no">${g.no}の門</span>
      <span class="kb-gate-name">${g.name}</span>
      <span class="kb-gate-desc">${esc(g.desc)}</span>
      ${meter}
    </button>`;
  }).join("");

  const sizeBtn = (v: string, label: string) =>
    `<button type="button" class="kb-seg${c.meta.fontSize === v ? " is-on" : ""}" data-kb-set="size:${v}" aria-pressed="${c.meta.fontSize === v}">${label}</button>`;
  const furiBtn = (v: "on" | "off", label: string) => {
    const on = (v === "on") === c.meta.furigana;
    return `<button type="button" class="kb-seg${on ? " is-on" : ""}" data-kb-set="furi:${v}" aria-pressed="${on}">${label}</button>`;
  };
  const lookBtn = (v: "on" | "off", label: string) => {
    const on = (v === "on") === c.meta.lookup;
    return `<button type="button" class="kb-seg${on ? " is-on" : ""}" data-kb-set="look:${v}" aria-pressed="${on}">${label}</button>`;
  };

  // 書棚：字引と常識（Phase 7）。常識は学習項目を持つので、門と同じ帯を出す
  const jo = gateProgress(c, "jo");
  const shelf = `<section class="kb-shelf" aria-label="書棚">
    <h3 class="kb-shelf-title">書棚</h3>
    <div class="kb-shelf-row">
      <button type="button" class="kb-shelf-item" data-kb-go="jibiki">
        <span class="kb-shelf-name">字引</span>
        <span class="kb-shelf-desc">字・熟語・読みから、用法・語・句形・常識を引く。${c.meta.lookup ? "本文の字を押しても引ける" : ""}</span>
      </button>
      <button type="button" class="kb-shelf-item" data-kb-go="jo">
        <span class="kb-shelf-name">常識</span>
        <span class="kb-shelf-desc">文学史と思想。諸子百家・史書・唐宋八大家・詩人</span>
        <span class="kb-gate-meter">${stackMeter(jo)}<span>${jo.mastered + jo.learning} / ${jo.total} 項目</span></span>
        ${jo.due ? `<span class="kb-gate-sub"><span class="kb-gate-due">復習 ${jo.due}</span></span>` : ""}
      </button>
    </div>
  </section>`;

  return `${topBar({ title: "書斎" }, c.meta)}
  <section class="kb-hero">
    <h2 class="kb-daiji"><span class="kb-daiji-text">漢文</span><span class="kb-seal" aria-hidden="true">學</span></h2>
    <div class="kb-hero-copy">
      <p class="kb-hero-lead">白文を訓読し、書き下し、意味をつかむ。</p>
      <p class="kb-hero-sub">共通テスト・センター試験の漢文を、語・字・句の三本柱と、試（総合演習・漢詩）で。書棚には字引と常識（文学史・思想）。</p>
      <p class="kb-hero-stats"><span><b>${learned}</b> / ${items.length} 項目を学習</span>${streak > 0 ? `<span>連続 <b>${streak}</b> 日</span>` : ""}</p>
    </div>
  </section>
  <nav class="kb-gates" aria-label="四つの門">${gates}</nav>
  ${shelf}
  <section class="kb-bands" aria-label="復習">
    <button type="button" class="kb-band${due ? " is-due" : ""}" data-kb-go="onshu">
      <span class="kb-band-name">温習<small>今日の復習</small></span>
      <span class="kb-band-sub">${due ? `忘れかけた <b>${due}</b> 項目を復習する` : next ? `今日の分は済みました。次は${next.label}に ${next.n} 項目` : "問題を解くと、ここに復習の予定が入ります"}</span>
    </button>
    <button type="button" class="kb-band" data-kb-go="nigate">
      <span class="kb-band-name">苦手帳</span>
      <span class="kb-band-sub">${weak ? `間違えたままの問題 <b>${weak}</b> 問` : "間違えた問題はここにたまります"}</span>
    </button>
  </section>
  <section class="kb-settings" aria-label="表示の設定">
    <div class="kb-setrow"><span>文字の大きさ</span><span class="kb-segs">${sizeBtn("s", "小")}${sizeBtn("m", "中")}${sizeBtn("l", "大")}</span></div>
    <div class="kb-setrow"><span>読み仮名（ルビ）</span><span class="kb-segs">${furiBtn("on", "出す")}${furiBtn("off", "隠す")}</span></div>
    <div class="kb-setrow"><span>本文の字を押して字引を開く</span><span class="kb-segs">${lookBtn("on", "する")}${lookBtn("off", "しない")}</span></div>
    <div class="kb-setrow"><span>本文の向き</span><span class="kb-segs"><button type="button" class="kb-seg${c.meta.vertical ? " is-on" : ""}" ${c.meta.vertical ? "" : 'data-kb-act="dir"'}>縦書き</button><button type="button" class="kb-seg${c.meta.vertical ? "" : " is-on"}" ${c.meta.vertical ? 'data-kb-act="dir"' : ""}>横書き</button></span></div>
  </section>
  <p class="kb-foot">例文の原文は、論語・史記などの公有の古典。訓点・書き下し文・現代語訳・解説は、このアプリで作成しました。原文は維基文庫などのオンライン資料と照合しています。共通テストの本文と設問は大学入試センターの問題冊子により、正解は同センターの公表によります。</p>
  <p class="kb-foot">書体は端末の明朝体を使います。明朝体の無い端末では Noto Serif JP（<a href="licenses/NotoSerifJP-OFL.txt" target="_blank" rel="noopener">SIL Open Font License 1.1</a>）を、漢文で使う字だけに絞って読み込みます。</p>`;
}
