/* 温習（今日の復習）と苦手帳。docs/kanbun/設計.md 5章「書斎」の帯と 7章 Phase 4。
   - 温習：復習の予定（srs.ts の FSRS）が今日以前の学習項目を、忘れかけたもの（想起確率の低いもの）から出す。
     1つの項目につき、その項目を refs に持つ設問を1問（しばらく解いていないものを優先）。1回は REVIEW_N 問まで。
   - 苦手帳：間違えたままの設問（store.ts の isWeak）の一覧。門ごとに並べ、学ぶ画面のカードへ飛べる。 */
import type { Ctx } from "../index";
import type { Question } from "../schema";
import { gateOf, learningItemIds, type Gate } from "../data";
import { isMastered, localDate, retrievability } from "../srs";
import { dueDays, isWeak, loadProgress, srsOf, type ItemRecord } from "../store";
import { answerText, esc, targetText, topBar } from "../ui";

export const REVIEW_N = 20;

/** 門の名。label は見出しに出す形（書棚の常識は門ではないので「書棚「常識」」） */
const GATE_NAME: Record<Gate, { name: string; label: string; unit: string }> = {
  go: { name: "語", label: "一の門「語」", unit: "語" },
  ji: { name: "字", label: "二の門「字」", unit: "用法" },
  ku: { name: "句", label: "三の門「句」", unit: "型" },
  shi: { name: "試", label: "四の門「試」", unit: "首" },
  jo: { name: "常識", label: "書棚「常識」", unit: "項目" },
};
const GATES: Gate[] = ["go", "ji", "ku", "shi", "jo"];

function today(now = new Date()): string {
  return localDate(now);
}

/** 今日の復習の項目（予定の日が今日以前）。忘れかけたものから並べる */
export function dueItems(gate?: Gate, now = new Date()): string[] {
  const progress = loadProgress();
  const t = today(now);
  const due = [...dueDays(learningItemIds(gate), progress)].filter(([, d]) => d <= t).map(([id]) => id);
  const r = new Map(due.map((id) => [id, retrievability(srsOf(progress[id])!, now)]));
  return due.sort((a, b) => r.get(a)! - r.get(b)!);
}

/** 温習の設問。項目ごとに1問を選び、ほかの項目もまとめて問える設問ならその項目は済みにする */
export function reviewQuestions(c: Ctx, gate?: Gate, now = new Date()): Question[] {
  const progress = loadProgress();
  const items = dueItems(gate, now);
  const due = new Set(items);
  const covered = new Set<string>();
  const out: Question[] = [];
  const lastAt = (q: Question) => progress[q.id]?.lastAt ?? "";
  for (const id of items) {
    if (out.length >= REVIEW_N) break;
    if (covered.has(id)) continue;
    const cands = c.data.questions.filter((q) => q.refs.includes(id) && (!gate || gateOf(q) === gate));
    if (!cands.length) continue;
    // しばらく解いていない設問（まだ解いていないものが先）。同じなら順不同
    const min = cands.reduce((m, q) => (lastAt(q) < m ? lastAt(q) : m), lastAt(cands[0]));
    const pool = cands.filter((q) => lastAt(q) === min);
    const q = pool[Math.floor(Math.random() * pool.length)];
    out.push(q);
    for (const r of q.refs) if (due.has(r)) covered.add(r);
  }
  return out;
}

export interface GateProgress { total: number; mastered: number; learning: number; fresh: number; due: number; weak: number }

/** 門ごとの進み具合。定着＝復習の間があく（安定度が MASTERED_STABILITY 日以上）項目、学習中＝解いたがまだ定着していない項目 */
export function gateProgress(c: Ctx, gate: Gate, now = new Date()): GateProgress {
  const progress = loadProgress();
  const ids = learningItemIds(gate);
  let mastered = 0, learning = 0;
  for (const id of ids) {
    const s = srsOf(progress[id]);
    if (!s) continue;
    if (isMastered(s)) mastered += 1;
    else learning += 1;
  }
  const weak = c.data.questions.filter((q) => gateOf(q) === gate && isWeak(progress[q.id])).length;
  return { total: ids.length, mastered, learning, fresh: ids.length - mastered - learning, due: dueItems(gate, now).length, weak };
}

/** 定着・学習中・未学習の帯 */
export function stackMeter(p: GateProgress): string {
  const pct = (n: number) => (p.total ? (n / p.total) * 100 : 0).toFixed(1);
  return `<span class="kb-stack" role="img" aria-label="定着 ${p.mastered}・学習中 ${p.learning}・未学習 ${p.fresh}"><i class="is-mastered" style="width:${pct(p.mastered)}%"></i><i class="is-learning" style="width:${pct(p.learning)}%"></i></span>`;
}

/** これから7日の予定（今日の分には、過ぎた日の分も入れる） */
function forecast(now = new Date()): { label: string; n: number }[] {
  const days = [...dueDays(learningItemIds()).values()];
  const t = today(now);
  const out: { label: string; n: number }[] = [];
  for (let i = 0; i < 7; i += 1) {
    const d = new Date(now); d.setDate(d.getDate() + i);
    const key = localDate(d);
    const n = days.filter((x) => (i === 0 ? x <= t : x === key)).length;
    const label = i === 0 ? "今日" : i === 1 ? "明日" : `${d.getMonth() + 1}/${d.getDate()}`;
    out.push({ label, n });
  }
  return out;
}

/** 次の復習の日（今日の分が無いとき、書斎と温習で「次は◯日」と出す） */
export function nextDue(now = new Date()): { label: string; n: number } | null {
  const t = today(now);
  const days = [...dueDays(learningItemIds()).values()].filter((d) => d > t).sort();
  if (!days.length) return null;
  const first = days[0];
  const [, m, d] = first.split("-").map(Number);
  const tomorrow = new Date(now); tomorrow.setDate(tomorrow.getDate() + 1);
  return { label: first === localDate(tomorrow) ? "明日" : `${m}月${d}日`, n: days.filter((x) => x === first).length };
}

export function onshuScreen(c: Ctx): string {
  const total = dueItems().length;
  const n = Math.min(total, REVIEW_N);
  const next = nextDue();
  const lead = total
    ? `<p class="kb-review-num"><b>${total}</b><small> 項目</small></p>
       <p class="kb-review-sub">忘れかけた項目から出します。${total > REVIEW_N ? `1回に ${REVIEW_N} 問ずつ。` : ""}</p>
       <button type="button" class="kb-btn kb-primary kb-review-go" data-kb-go="quiz" data-kb-arg="review">温習をはじめる（${n}問）</button>`
    : `<p class="kb-review-num"><b>0</b><small> 項目</small></p>
       <p class="kb-review-sub">${next ? `今日の復習は済んでいます。次は${next.label}に ${next.n} 項目。` : "まだ復習する項目がありません。門で問題を解くと、ここに復習の予定が入ります。"}</p>`;

  const rows = GATES.map((g) => {
    const p = gateProgress(c, g);
    const info = GATE_NAME[g];
    return `<div class="kb-gprog">
      <div class="kb-gprog-head"><span class="kb-gprog-name">${info.label}</span>
        <button type="button" class="kb-btn kb-gprog-go" data-kb-go="quiz" data-kb-arg="${g}:review" ${p.due ? "" : "disabled"}>${p.due ? `この門だけ（${Math.min(p.due, REVIEW_N)}問）` : "今日の分なし"}</button></div>
      ${stackMeter(p)}
      <p class="kb-gprog-nums"><span><i class="kb-dot is-mastered"></i>定着 <b>${p.mastered}</b></span><span><i class="kb-dot is-learning"></i>学習中 <b>${p.learning}</b></span><span><i class="kb-dot"></i>未学習 <b>${p.fresh}</b></span><span>／ ${p.total} ${info.unit}</span></p>
      <p class="kb-gprog-nums"><span>今日の復習 <b>${p.due}</b></span><span>苦手 <b>${p.weak}</b> 問</span></p>
    </div>`;
  }).join("");

  const fc = forecast();
  const max = Math.max(1, ...fc.map((f) => f.n));
  const bars = fc.map((f) => `<li><span class="kb-fc-n">${f.n}</span><span class="kb-fc-bar"><i style="height:${Math.round((f.n / max) * 100)}%"></i></span><span class="kb-fc-day">${f.label}</span></li>`).join("");

  return `${topBar({ title: "温習", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">今日の復習</span><h2>温習<small>温故知新</small></h2></header>
    <section class="kb-review">${lead}</section>
    <section class="kb-sec"><h3 class="kb-sec-title">門ごとの進み具合<small>定着＝次の復習まで1週間以上あいた項目。正解すると次の復習までの間が延び、間違えると縮みます。</small></h3>${rows}</section>
    <section class="kb-sec"><h3 class="kb-sec-title">これから7日の復習<small>その日に復習の予定が来る項目の数。</small></h3><ol class="kb-forecast" aria-label="これから7日の復習の数">${bars}</ol></section>`;
}

interface WeakRow { q: Question; r: ItemRecord }

const TYPE_LABEL: Record<Question["type"], string> = {
  yomi: "読み", kakikudashi: "書き下し", kaishaku: "解釈", imi: "意味", kaeriten: "返り点", oin: "押韻", taiku: "対句", keishiki: "形式", joshiki: "常識",
};

function monthDay(iso: string | null): string {
  if (!iso) return "";
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "" : `${d.getMonth() + 1}/${d.getDate()}`;
}

export function nigateScreen(c: Ctx): string {
  const progress = loadProgress();
  const rows: WeakRow[] = c.data.questions
    .filter((q) => isWeak(progress[q.id]))
    .map((q) => ({ q, r: progress[q.id]! }))
    .sort((a, b) => (b.r.lastWrong ?? "").localeCompare(a.r.lastWrong ?? ""));
  const head = `${topBar({ title: "苦手帳", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">間違えたままの問題</span><h2>苦手帳</h2></header>`;
  if (!rows.length) {
    return `${head}<p class="kb-empty">苦手帳は空です。間違えた問題はここにたまり、2回続けて正解すると外れます。</p>`;
  }
  const byGate = (g: Gate) => rows.filter((x) => gateOf(x.q) === g);
  const starts = `<div class="kb-starts">
    <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="weak"><b>まとめて解き直す</b><small>門をまたいで ${rows.length} 問。2回続けて正解すると苦手帳から外れます</small></button>
    ${GATES.map((g) => {
      const n = byGate(g).length;
      return n ? `<button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="${g}:weak"><b>${g === "shi" ? "漢詩" : GATE_NAME[g].name}の苦手だけ</b><small>${n} 問</small></button>` : "";
    }).join("")}
  </div>`;

  const list = GATES.map((g) => {
    const xs = byGate(g);
    if (!xs.length) return "";
    const items = xs.map(({ q, r }) => {
      const e = c.data.examples.get(q.exampleId);
      const target = targetText(q, e);
      const ref = q.refs[0];
      return `<li class="kb-weak">
        <div class="kb-weak-main">
          <span class="kb-weak-target">${esc(target)}</span>
          <span class="kb-weak-answer">${esc(answerText(q))}</span>
          <span class="kb-weak-meta">${esc(e?.work ?? "")}　${TYPE_LABEL[q.type]}　×${r.wrong}${r.lastWrong ? `（${monthDay(r.lastWrong)}）` : ""}${r.streak ? `　あと${2 - r.streak}回正解で外れる` : ""}</span>
        </div>
        ${ref ? `<button type="button" class="kb-btn kb-ghost kb-weak-learn" data-kb-jump="${esc(ref)}">学ぶ</button>` : ""}
      </li>`;
    }).join("");
    return `<section class="kb-sec"><h3 class="kb-sec-title">${GATE_NAME[g].label}<small>${xs.length} 問（新しく間違えた順）</small></h3><ol class="kb-weaklist">${items}</ol></section>`;
  }).join("");

  return `${head}<p class="kb-hint">間違えたままの問題です。「学ぶ」で、その語・用法・句形・常識のカードや漢詩を開けます。</p>${starts}${list}`;
}
