/* 漢文（アプリの中の別アプリ）の入口。docs/kanbun/設計.md 1章・2章。
   index.html は window.STUDY_CORE.kanbun.{open, route, close, busy} だけを呼ぶ。
   中の画面切り替えはここの小さなルーターが受け持ち、履歴は既存の仕組みに相乗りする
   （history.state = {studyScreen:"kanbunApp", kanbunScreen, kanbunArg}。popstate の受け口は index.html の1つだけ）。 */
import "./kanbun.css";
import { kanbunData, learningItemIds } from "./data";
import { preloadMincho, useBundledMincho } from "./font";
import { loadMeta, saveMeta, writeStats, type FontSize, type Meta } from "./store";
import { STAGES, type Stage } from "./render";
import { exampleCard, stageBody } from "./ui";
import { homeScreen } from "./screens/home";
import { groupScreen, groupViews, jiScreen } from "./screens/ji";
import { catScreen, catViews, kuScreen } from "./screens/ku";
import { cards, cardScreen, goCatScreen, goScreen, vocabViews } from "./screens/go";
import { homeOf, kaisetsuScreen, quizScreen, resultScreen, quiz } from "./screens/quiz";
import { nigateScreen, onshuScreen } from "./screens/review";
import { clock, shiScreen } from "./screens/shi";
import { kanshiScreen, poemScreen, poemViews } from "./screens/kanshi";
import { joCatScreen, joScreen, joshikiViews } from "./screens/jo";
import { jibikiResultsHTML, jibikiScreen, sheetHTML } from "./screens/jibiki";

export type Screen = "home" | "go" | "go-cat" | "go-card" | "ji" | "ji-group" | "ku" | "ku-cat" | "shi" | "shi-kanshi" | "shi-poem" | "jo" | "jo-cat" | "jibiki" | "onshu" | "nigate" | "quiz" | "result" | "kaisetsu";
const SCREENS: Screen[] = ["home", "go", "go-cat", "go-card", "ji", "ji-group", "ku", "ku-cat", "shi", "shi-kanshi", "shi-poem", "jo", "jo-cat", "jibiki", "onshu", "nigate", "quiz", "result", "kaisetsu"];

/** 戻るボタンで、履歴が無いとき（再読み込みの直後など）に行く先。演習と結果は、その演習の門へ */
function parentOf(screen: Screen): [Screen, string?] | null {
  if (screen === "home") return null;
  if (screen === "go" || screen === "ji" || screen === "ku" || screen === "shi" || screen === "jo" || screen === "jibiki" || screen === "onshu" || screen === "nigate") return ["home"];
  if (screen === "jo-cat") return ["jo", "learn"];
  if (screen === "go-cat" || screen === "go-card") return ["go", "learn"];
  if (screen === "ji-group") return ["ji", "learn"];
  if (screen === "ku-cat") return ["ku", "learn"];
  if (screen === "shi-kanshi") return ["shi"];
  if (screen === "shi-poem") return ["shi-kanshi"];
  if (screen === "kaisetsu") return ["result"];
  const g = homeOf(quiz.session);
  return [g.screen, g.arg];
}

export interface Ctx {
  meta: Meta;
  data: ReturnType<typeof kanbunData>;
  screen: Screen;
  arg: string | undefined;
  /** 例文カードごとの表示中の段 */
  stages: Map<string, Stage>;
}

let root: HTMLElement | null = null;
let ctx: Ctx | null = null;
/** この画面の中で積んだ履歴の数。0 なら戻るボタンは親の画面へ置きかえる */
let depth = 0;
/** 本番形式の時計（1秒ごとに経過時間を書きかえる） */
let timer: ReturnType<typeof setInterval> | null = null;

function shell() {
  return window.STUDY_SHELL;
}

function pushState(screen: Screen, arg: string | undefined, replace: boolean): void {
  try {
    const state = { studyScreen: "kanbunApp", kanbunScreen: screen, kanbunArg: arg ?? null };
    if (replace) history.replaceState(state, "");
    else history.pushState(state, "");
  } catch { /* 履歴が使えない環境ではそのまま */ }
}

function render(): void {
  if (!root || !ctx) return;
  const c = ctx;
  let html = "";
  if (c.screen === "home") html = homeScreen(c);
  else if (c.screen === "go") html = goScreen(c);
  else if (c.screen === "go-cat") html = goCatScreen(c);
  else if (c.screen === "go-card") html = cardScreen(c);
  else if (c.screen === "ji") html = jiScreen(c);
  else if (c.screen === "ji-group") html = groupScreen(c);
  else if (c.screen === "ku") html = kuScreen(c);
  else if (c.screen === "ku-cat") html = catScreen(c);
  else if (c.screen === "shi") html = shiScreen(c);
  else if (c.screen === "shi-kanshi") html = kanshiScreen(c);
  else if (c.screen === "shi-poem") html = poemScreen(c);
  else if (c.screen === "jo") html = joScreen(c);
  else if (c.screen === "jo-cat") html = joCatScreen(c);
  else if (c.screen === "jibiki") html = jibikiScreen(c);
  else if (c.screen === "onshu") html = onshuScreen(c);
  else if (c.screen === "nigate") html = nigateScreen(c);
  else if (c.screen === "quiz") html = quizScreen(c);
  else if (c.screen === "kaisetsu") html = kaisetsuScreen(c);
  else html = resultScreen(c);
  root.innerHTML = `<div class="kb-app kb-size-${c.meta.fontSize}${useBundledMincho() ? " kb-font-bundled" : ""}">${html}</div>`;
  revealMarks(root);
  runTimer();
  saveMeta({ lastScreen: c.screen });
}

/** 本番形式の出題中だけ、経過時間を1秒ごとに書きかえる。目安を超えたら朱にする */
function runTimer(): void {
  if (timer) { clearInterval(timer); timer = null; }
  const x = quiz.session?.exam;
  if (!root || ctx?.screen !== "quiz" || !x || quiz.session?.finished) return;
  timer = setInterval(() => {
    const el = root?.querySelector<HTMLElement>("[data-kb-timer]");
    if (!el) return;
    const sec = quiz.elapsedSec();
    el.textContent = clock(sec);
    el.classList.toggle("is-over", sec > x.limitSec);
  }, 1000);
}

/** 縦書きの本文が欄に収まらないとき（長文など）、傍線部・朱の範囲が見えるところまで横に送る。
    縦書きは右から始まるので、長い本文では傍線部が欄の外（左）に隠れてしまうため */
function revealMarks(scope: ParentNode): void {
  scope.querySelectorAll<HTMLElement>(".kb-text.kb-v").forEach((box) => {
    if (box.scrollWidth <= box.clientWidth) return;
    const cells = [...box.querySelectorAll<HTMLElement>(".kb-bl, .kb-hl, .kb-blank")];
    if (!cells.length) return;
    const rects = cells.map((el) => el.getBoundingClientRect());
    const left = Math.min(...rects.map((r) => r.left));
    const right = Math.max(...rects.map((r) => r.right));
    const b = box.getBoundingClientRect();
    // 傍線部が欄より長ければ、その書き出し（右端）を欄の右寄りに合わせる。短ければ欄の中央に置く
    const delta = right - left > b.width - 24 ? right - (b.right - 12) : (left + right) / 2 - (b.left + b.width / 2);
    box.scrollLeft += delta;
  });
}

function show(screen: Screen, arg: string | undefined): void {
  if (!ctx) return;
  // 解き終わった演習へ履歴で戻ってきたら結果を、演習が無ければ新しく始める
  if (screen === "quiz") {
    if (quiz.session && quiz.session.finished) { screen = "result"; pushState("result", undefined, true); }
    else if (!quiz.session || (arg && quiz.session.mode !== arg)) quiz.start(ctx, arg ?? "random");
  }
  if (screen === "result" && !quiz.session) { screen = "home"; arg = undefined; pushState(screen, arg, true); }
  // 本番形式の解説は、採点した演習があるときだけ
  if (screen === "kaisetsu" && !quiz.session?.finished) { screen = "home"; arg = undefined; pushState(screen, arg, true); }
  // 暗記カードは、履歴で戻ってきたときに山が無い（別の分類の山）なら新しく作る
  if (screen === "go-card" && (!cards.deck || cards.deck.key !== (arg ?? "all"))) cards.start(ctx, arg ?? "all");
  ctx.screen = screen;
  ctx.arg = arg;
  render();
  try { window.scrollTo(0, 0); } catch { /* jsdom など */ }
}

export interface GoOptions {
  /** 履歴を積まずに今の画面を置きかえる */
  replace?: boolean;
  /** 演習を始め直さずに続ける */
  keep?: boolean;
}

/** 中の画面へ進む（履歴を積む） */
export function go(screen: Screen, arg?: string, opts: GoOptions = {}): void {
  // 演習の画面へ進むときは新しく始める。次の問題へ進むとき（keep）は続ける
  if (screen === "quiz" && !opts.keep) quiz.start(ctx!, arg ?? "random");
  if (screen === "go-card") cards.start(ctx!, arg ?? "all");
  pushState(screen, arg, !!opts.replace);
  if (!opts.replace) depth += 1;
  show(screen, arg);
}

function back(): void {
  if (!ctx) return;
  if (depth > 0) { history.back(); return; }
  const parent = parentOf(ctx.screen);
  if (!parent) { shell()?.openSubjectPicker(); return; }
  pushState(parent[0], parent[1], true);
  show(parent[0], parent[1]);
}

function rerenderCard(key: string): void {
  if (!root || !ctx) return;
  const card = root.querySelector<HTMLElement>(`[data-kb-card="${CSS.escape(key)}"]`);
  const view = ctx.screen === "quiz" || ctx.screen === "kaisetsu" ? quiz.viewFor(ctx, key) : currentViews().get(key);
  if (!card || !view) return;
  view.stage = ctx.stages.get(key) ?? view.stage;
  const body = card.querySelector<HTMLElement>(".kb-stagebody");
  if (body) { body.innerHTML = stageBody(view, ctx.meta); revealMarks(body); }
  card.querySelectorAll<HTMLElement>("[data-kb-stage]").forEach((b) => {
    const on = b.dataset.kbStage === `${key}:${view.stage}`;
    b.classList.toggle("is-on", on);
    b.setAttribute("aria-selected", String(on));
  });
}

/** 学ぶ画面の例文カード（段の切り替えで描き直すために、今の画面のカードを引けるようにしておく） */
function currentViews() {
  if (ctx?.screen === "ji-group") return groupViews(ctx);
  if (ctx?.screen === "ku-cat") return catViews(ctx);
  if (ctx?.screen === "go-cat") return vocabViews(ctx);
  if (ctx?.screen === "shi-poem") return poemViews(ctx);
  if (ctx?.screen === "jo-cat") return joshikiViews(ctx);
  return new Map();
}

/** 学習項目のカードへ飛ぶ。語・句形・常識は分類の画面、用法は束の画面を開いて（今の画面でなければ）、そのカードまで送る。
    漢詩はその詩の画面を開く。語・句形の表・「紛らわしい句形」・年表と、苦手帳の「学ぶ」・字引から使う */
function jump(id: string): void {
  if (!ctx || !root) return;
  if (ctx.data.kanshi.has(id)) { if (ctx.screen !== "shi-poem" || ctx.arg !== id) go("shi-poem", id); return; }
  const v = ctx.data.vocab.get(id);
  const k = ctx.data.kukei.get(id);
  const j = ctx.data.joshiki.get(id);
  const g = ctx.data.usages.has(id) ? ctx.data.groups.find((x) => x.members.includes(id)) : undefined;
  const [screen, arg] = v ? ["go-cat" as const, v.cat] : k ? ["ku-cat" as const, k.cat] : j ? ["jo-cat" as const, j.cat] : g ? ["ji-group" as const, g.id] : [null, null];
  if (!screen) return;
  if (ctx.screen !== screen || ctx.arg !== arg) go(screen, arg);
  const el = root.querySelector<HTMLElement>(`#${CSS.escape(id)}`);
  el?.scrollIntoView?.({ block: "start" });
}

/** 字引の札（本文の字を押したとき、画面の下に開く）。描き直すと消える */
function closeSheet(): void {
  root?.querySelectorAll(".kb-sheet").forEach((el) => el.remove());
  root?.querySelectorAll(".kb-cell.is-looked").forEach((el) => el.classList.remove("is-looked"));
}

function openSheet(cell: HTMLElement, exampleId: string): void {
  if (!ctx || !root) return;
  const ci = Number(cell.dataset.ci);
  const html = sheetHTML(ctx, exampleId, ci);
  closeSheet();
  if (!html) return;
  cell.classList.add("is-looked");
  root.querySelector(".kb-app")?.insertAdjacentHTML("beforeend", html);
  root.querySelector<HTMLElement>(".kb-sheet-close")?.focus?.({ preventScroll: true });
}

/** 字引の画面の入力：結果の部分だけを描き直し（入力欄は描き直さないので、変換中の字が消えない）、履歴の arg を置きかえる */
function onInput(e: Event): void {
  const input = e.target as HTMLInputElement;
  if (!ctx || !root || ctx.screen !== "jibiki" || !input.matches("[data-kb-search]")) return;
  setQuery(input.value, false);
}

function setQuery(q: string, fillInput: boolean): void {
  if (!ctx || !root) return;
  ctx.arg = q || undefined;
  if (fillInput) { const input = root.querySelector<HTMLInputElement>("[data-kb-search]"); if (input) input.value = q; }
  const box = root.querySelector<HTMLElement>("[data-kb-results]");
  if (box) box.innerHTML = jibikiResultsHTML(ctx, q);
  pushState("jibiki", ctx.arg, true);
}

function onSubmit(e: Event): void {
  if ((e.target as HTMLElement).matches?.("[data-kb-searchform]")) {
    e.preventDefault();
    root?.querySelector<HTMLInputElement>("[data-kb-search]")?.blur();
  }
}

function onClick(e: Event): void {
  if (!ctx) return;
  const t = (e.target as HTMLElement).closest<HTMLElement>("[data-kb-act],[data-kb-go],[data-kb-stage],[data-kb-flip],[data-kb-choice],[data-kb-set],[data-kb-jump],[data-kb-exam-go],[data-kb-q]");
  if (!t) {
    // 本文の字を押したら字引の札を開く（出題中のカードには data-kb-ex が付かない）
    const cell = (e.target as HTMLElement).closest<HTMLElement>(".kb-cell[data-ci]");
    const card = cell?.closest<HTMLElement>("[data-kb-ex]");
    if (cell && card?.dataset.kbEx) openSheet(cell, card.dataset.kbEx);
    else if (!(e.target as HTMLElement).closest(".kb-sheet")) closeSheet();   // 札の外を押したら閉じる
    return;
  }
  if ((t as HTMLButtonElement).disabled) return;
  const d = t.dataset;
  if (d.kbAct === "sheet-close") { closeSheet(); return; }
  closeSheet();
  if (d.kbQ != null) { setQuery(d.kbQ, true); return; }
  if (d.kbAct === "back") back();
  else if (d.kbAct === "picker") shell()?.openSubjectPicker();
  else if (d.kbAct === "theme") shell()?.toggleTheme();
  else if (d.kbAct === "dir") { ctx.meta = saveMeta({ vertical: !ctx.meta.vertical }); render(); }
  else if (d.kbAct === "next") quiz.next(ctx, go);
  else if (d.kbAct === "prev") quiz.move(ctx, go, (quiz.session?.index ?? 0) - 1);
  else if (d.kbAct === "grade" || d.kbAct === "grade-force") {
    // 未解答があれば確かめの案内を出す（採点したら結果の画面へ進む）
    if (!quiz.grade(ctx, go, d.kbAct === "grade-force")) { render(); root?.querySelector<HTMLElement>(".kb-examconfirm")?.scrollIntoView?.({ block: "nearest" }); }
  } else if (d.kbExamGo != null) quiz.move(ctx, go, Number(d.kbExamGo));
  else if (d.kbAct?.startsWith("card-")) { cards.act(d.kbAct.slice(5)); render(); }
  else if (d.kbJump) jump(d.kbJump);
  else if (d.kbSet) {
    const [k, v] = d.kbSet.split(":");
    if (k === "size") ctx.meta = saveMeta({ fontSize: v as FontSize });
    if (k === "furi") ctx.meta = saveMeta({ furigana: v === "on" });
    if (k === "look") ctx.meta = saveMeta({ lookup: v === "on" });
    render();
  } else if (d.kbGo) {
    go(d.kbGo as Screen, d.kbArg || undefined, { replace: d.kbReplace === "1" });
  } else if (d.kbStage) {
    const i = d.kbStage.lastIndexOf(":");
    ctx.stages.set(d.kbStage.slice(0, i), d.kbStage.slice(i + 1) as Stage);
    rerenderCard(d.kbStage.slice(0, i));
  } else if (d.kbFlip) {
    const key = d.kbFlip;
    const cur = ctx.stages.get(key) ?? "kundoku";
    const idx = STAGES.findIndex((s) => s.id === cur);
    ctx.stages.set(key, STAGES[(idx + 1) % STAGES.length].id);
    rerenderCard(key);
  } else if (d.kbChoice != null) {
    quiz.answer(ctx, Number(d.kbChoice));
    render();
    // 答えたら判定へ、本番形式は「次の問題」へ送る
    root?.querySelector<HTMLElement>(".kb-judge, .kb-examnav")?.scrollIntoView?.({ block: "nearest" });
  }
}

function onKey(e: KeyboardEvent): void {
  if (!ctx || e.altKey || e.ctrlKey || e.metaKey) return;
  if (e.key === "Escape" && root?.querySelector(".kb-sheet")) { e.preventDefault(); closeSheet(); return; }
  const target = e.target as HTMLElement | null;
  if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return;
  // 暗記カード：空白・Enter でめくる。めくったあとは → か 1 で「覚えた」、← か 2 で「もう一度」
  if (ctx.screen === "go-card" && cards.deck) {
    const flipped = cards.deck.flipped;
    const action = e.key === " " || e.key === "Enter" ? (flipped ? "ok" : "flip")
      : flipped && (e.key === "ArrowRight" || e.key === "1") ? "ok"
      : flipped && (e.key === "ArrowLeft" || e.key === "2") ? "again" : null;
    if (action) { e.preventDefault(); cards.act(action); render(); }
    return;
  }
  if (ctx.screen !== "quiz") return;
  const s = quiz.session;
  if (!s) return;
  // 本番形式：数字で選び（選び直せる）、Enter で次の問題へ
  if (s.exam && !s.finished) {
    if (/^[1-6]$/.test(e.key)) {
      const btn = root?.querySelector<HTMLButtonElement>(`[data-kb-choice="${Number(e.key) - 1}"]`);
      if (btn) { e.preventDefault(); btn.click(); }
    } else if (e.key === "Enter" && s.index + 1 < s.ids.length) {
      e.preventDefault();
      quiz.next(ctx, go);
    }
    return;
  }
  if (!quiz.answered() && /^[1-6]$/.test(e.key)) {
    const n = Number(e.key) - 1;
    const btn = root?.querySelector<HTMLButtonElement>(`[data-kb-choice="${n}"]`);
    if (btn) { e.preventDefault(); btn.click(); }
  } else if (quiz.answered() && (e.key === "Enter" || e.key === " ")) {
    e.preventDefault();
    quiz.next(ctx, go);
  }
}

/** 漢文を開く。el は index.html の #kanbunApp。screen を渡すと、その画面から始める（履歴で戻ってきたとき） */
export function open(el: HTMLElement, screen?: string, arg?: string | null): void {
  if (root !== el) {
    root?.removeEventListener("click", onClick);
    root?.removeEventListener("input", onInput);
    root?.removeEventListener("submit", onSubmit);
    root = el;
    root.addEventListener("click", onClick);
    root.addEventListener("input", onInput);
    root.addEventListener("submit", onSubmit);
    document.addEventListener("keydown", onKey);
  }
  const data = kanbunData();
  writeStats(learningItemIds());
  ctx = { meta: loadMeta(), data, screen: "home", arg: undefined, stages: new Map() };
  depth = 0;
  const s = SCREENS.includes(screen as Screen) ? (screen as Screen) : "home";
  pushState(s, arg ?? undefined, true);
  show(s, arg ?? undefined);
  preloadMincho(() => { if (root) revealMarks(root); });
}

/** index.html の popstate から呼ばれる */
export function route(screen?: string, arg?: string | null): void {
  if (!ctx) return;
  if (depth > 0) depth -= 1;
  const s = SCREENS.includes(screen as Screen) ? (screen as Screen) : "home";
  show(s, arg ?? undefined);
}

/** 科目えらびへ戻るとき。記録はその場で保存済みなので、画面と演習を片付けるだけ */
export function close(): void {
  writeStats(learningItemIds());
  if (timer) { clearInterval(timer); timer = null; }
  quiz.reset();
  cards.reset();
  document.removeEventListener("keydown", onKey);
  root?.removeEventListener("click", onClick);
  root?.removeEventListener("input", onInput);
  root?.removeEventListener("submit", onSubmit);
  if (root) root.innerHTML = "";
  root = null;
  ctx = null;
  depth = 0;
}

/** 演習の途中かどうか（自動更新の再読み込みを待たせる）。本番形式は、始めたら採点するまで */
export function busy(): boolean {
  const s = quiz.session;
  return ctx?.screen === "quiz" && !!s && !s.finished && (!!s.exam || s.answers.length > 0);
}

export { exampleCard };
