/* 漢文の教材を読み込む。JSON は漢文の分割ファイルに同梱されるので、
   Service Worker の事前キャッシュに乗り、オフラインでも開ける。 */
import examplesJson from "../../content/kanbun/examples.json";
import kanjiJson from "../../content/kanbun/kanji.json";
import groupsJson from "../../content/kanbun/groups.json";
import kukeiJson from "../../content/kanbun/kukei.json";
import questionsJson from "../../content/kanbun/questions.json";
import vocabJson from "../../content/kanbun/vocab.json";
import kanshiJson from "../../content/kanbun/kanshi.json";
import joshikiJson from "../../content/kanbun/joshiki.json";
import type { Example, Group, Joshiki, KanjiUsage, Kanshi, Kukei, Question, Vocab } from "./schema";

export interface KanbunData {
  examples: Map<string, Example>;
  usages: Map<string, KanjiUsage>;
  groups: Group[];
  /** 三の門「句」の句形。並びは教材の順（分類の中の並びもこの順） */
  kukei: Map<string, Kukei>;
  /** 一の門「語」の重要語。並びは教材の順（分類の中の並びもこの順） */
  vocab: Map<string, Vocab>;
  /** 四の門「試」の漢詩。並びは教材の順（形式ごとの並びもこの順） */
  kanshi: Map<string, Kanshi>;
  /** 書棚「常識」の人物・書物。並びは教材の順（分類の中の並びもこの順） */
  joshiki: Map<string, Joshiki>;
  questions: Question[];
}

let cache: KanbunData | null = null;

/** 画面で使う形にまとめる。検査は tests/kanbun-content.test.ts で済ませてあるので、ここでは型だけ付ける */
export function kanbunData(): KanbunData {
  if (cache) return cache;
  cache = {
    examples: new Map((examplesJson as Example[]).map((e) => [e.id, e])),
    usages: new Map((kanjiJson as KanjiUsage[]).map((u) => [u.id, u])),
    groups: (groupsJson as Group[]).map((g) => ({ ...g, points: g.points ?? [] })),
    kukei: new Map((kukeiJson as Kukei[]).map((k) => [k.id, { ...k, points: k.points ?? [], confusables: k.confusables ?? [] }])),
    vocab: new Map((vocabJson as Vocab[]).map((v) => [v.id, { ...v, points: v.points ?? [] }])),
    kanshi: new Map((kanshiJson as Kanshi[]).map((k) => [k.id, { ...k, taiku: k.taiku ?? [], points: k.points ?? [] }])),
    joshiki: new Map((joshikiJson as Joshiki[]).map((j) => [j.id, { ...j, keywords: j.keywords ?? [], points: j.points ?? [] }])),
    questions: questionsJson as Question[],
  };
  return cache;
}

/** 門。一の門「語」は重要語（kb-v-）、二の門「字」は用法（kb-k-）、三の門「句」は句形（kb-p-）、
    四の門「試」は漢詩（kb-s-）を学習項目にする（返り点の四択・総合演習は、ほかの門の項目につながる）。
    jo は書棚の「常識」（文学史・思想、kb-j-）。四つの門の外だが、温習・苦手帳・進み具合は門と同じに扱う */
export type Gate = "go" | "ji" | "ku" | "shi" | "jo";

/** 設問がどの門のものか（refs の学習項目で決める） */
export function gateOf(q: Question): Gate {
  if (q.refs.some((r) => r.startsWith("kb-v-"))) return "go";
  if (q.refs.some((r) => r.startsWith("kb-s-"))) return "shi";
  if (q.refs.some((r) => r.startsWith("kb-j-"))) return "jo";
  return q.refs.some((r) => r.startsWith("kb-p-")) ? "ku" : "ji";
}

/** 学習項目（タイルの「◯項目」に数えるもの）。一の門の語、二の門の用法、三の門の句形、四の門の漢詩、書棚の常識 */
export function learningItemIds(gate?: Gate): string[] {
  const d = kanbunData();
  if (gate === "go") return [...d.vocab.keys()];
  if (gate === "ji") return [...d.usages.keys()];
  if (gate === "ku") return [...d.kukei.keys()];
  if (gate === "shi") return [...d.kanshi.keys()];
  if (gate === "jo") return [...d.joshiki.keys()];
  return [...d.vocab.keys(), ...d.usages.keys(), ...d.kukei.keys(), ...d.kanshi.keys(), ...d.joshiki.keys()];
}
