/* 漢文の教材（content/kanbun/*.json）の形。docs/kanbun/設計.md 4章。
   検査は tests/kanbun-content.test.ts（zod・IDの重複・参照切れ・返り点・書き下しとの一致）。 */
import { z } from "zod";

/** 出典。pdf は発行元と資料名を label に、original は本アプリで作成したもの */
export const SourceSchema = z.object({
  kind: z.enum(["original", "pdf", "exam"]),
  label: z.string().optional(),
  url: z.string().url().optional(),
});

export const ExampleSchema = z.object({
  id: z.string().regex(/^kb-e-[a-z0-9-]+$/),
  /** 原文の出どころ（論語・為政 など）。公有の古典 */
  work: z.string().min(1),
  kundoku: z.string().min(1),
  kakikudashi: z.string().min(1),
  yaku: z.string().min(1),
  source: SourceSchema,
  sourceNote: z.string().optional(),
  /** 原文を維基文庫などのオンライン資料と照合した（共通テストの本文は問題冊子と照合した） */
  reviewed: z.boolean(),
  /** 長文（白文が44字を超える。共通テストの本文など）。縦書きの欄を高くし、傍線部まで横に送って見せる */
  long: z.boolean().optional(),
});

export const KanjiUsageSchema = z.object({
  id: z.string().regex(/^kb-k-[a-z0-9-]+$/),
  kanji: z.string().min(1),
  yomi: z.string().min(1),
  gloss: z.string().min(1),
  usage: z.string().min(1),
  exampleIds: z.array(z.string()).min(1),
  rank: z.enum(["A", "B", "C"]),
});

export const GroupSchema = z.object({
  id: z.string().regex(/^kb-g-[a-z0-9-]+$/),
  /** doukun＝同訓異字（読みが同じ別の字）／takun＝多訓字（1字に読みが多い） */
  kind: z.enum(["doukun", "takun"]),
  title: z.string().min(1),
  chars: z.string().min(1),
  lead: z.string().min(1),
  members: z.array(z.string()).min(2),
  points: z.array(z.string()).default([]),
});

/** 三の門「句」の分類（docs/kanbun/網羅表.md 2章の15分類）。画面の並びと見出しは screens/ku.ts */
export const KUKEI_CATS = [
  "saidoku", "hitei", "nijuu", "bubun", "kinshi", "gimon", "hango", "shieki",
  "ukemi", "hikaku", "katei", "gentei", "yokuyou", "eitan", "ganbou",
] as const;
export type KukeiCat = (typeof KUKEI_CATS)[number];

/** 句形（再読文字・否定…）。form は訓点の記法で書いた型で、語が入る所は全角の Ａ・Ｂ（docs/kanbun/記法.md） */
export const KukeiSchema = z.object({
  id: z.string().regex(/^kb-p-[a-z0-9-]+$/),
  cat: z.enum(KUKEI_CATS),
  /** 見出しの字（未・不可不・無Ａ不Ｂ など） */
  name: z.string().min(1),
  form: z.string().min(1),
  kakikudashi: z.string().min(1),
  meaning: z.string().min(1),
  points: z.array(z.string().min(1)).default([]),
  /** 紛らわしい句形。ref は比べる相手の句形のID */
  confusables: z.array(z.object({ ref: z.string().optional(), text: z.string().min(1) })).default([]),
  /** 部分否定に対する全部否定のように、語順だけが違う対の形 */
  contrast: z.object({
    label: z.string().min(1),
    form: z.string().min(1),
    kakikudashi: z.string().min(1),
    meaning: z.string().min(1),
  }).optional(),
  exampleIds: z.array(z.string()).min(1),
  rank: z.enum(["A", "B", "C"]),
});

/** 一の門「語」の分類（docs/kanbun/網羅表.md 3章）。画面の並びと見出しは screens/go.ts */
export const VOCAB_CATS = ["jinbutsu", "zure", "fukushi", "sonota"] as const;
export type VocabCat = (typeof VOCAB_CATS)[number];

/** 重要語。yomi は歴史的仮名遣い。modernTrap は現代語とのずれ（大丈夫≠平気 など） */
export const VocabSchema = z.object({
  id: z.string().regex(/^kb-v-[a-z0-9-]+$/),
  /** 見出しの語。同じ意味の別の字は括弧に添える（女（汝）） */
  word: z.string().min(1),
  yomi: z.string().min(1),
  meanings: z.array(z.string().min(1)).min(1),
  modernTrap: z.string().min(1).optional(),
  cat: z.enum(VOCAB_CATS),
  rank: z.enum(["A", "B", "C"]),
  exampleIds: z.array(z.string()).min(1),
  points: z.array(z.string().min(1)).default([]),
});

/** 漢詩の形式。近体詩（絶句・律詩）と古体詩（古詩）。docs/kanbun/設計.md 7章 Phase 6 その4・その7 */
export const KANSHI_FORMS = ["gozetsu", "shichizetsu", "goritsu", "shichiritsu", "goko", "shichiko"] as const;
export type KanshiForm = (typeof KANSHI_FORMS)[number];
export const KANSHI_FORM_NAME: Record<KanshiForm, string> = {
  gozetsu: "五言絶句", shichizetsu: "七言絶句", goritsu: "五言律詩", shichiritsu: "七言律詩", goko: "五言古詩", shichiko: "七言古詩",
};

/** 漢詩（四の門「試」の学習項目）。本文は examples.json の例文（句を ／ で区切る）。
    ends は各句の句末の字の音読み（現代仮名遣いのカタカナ。漢音で韻が合う字は「ジョウ（セイ）」のように括弧で添える）。
    長い詩（長恨歌など）は一節を採り、excerpt にもとの詩での句の範囲を持つ（句の番号は一節の中で1から数える） */
export const KanshiSchema = z.object({
  id: z.string().regex(/^kb-s-[a-z0-9-]+$/),
  title: z.string().min(1),
  poet: z.string().min(1),
  /** 時代（唐・宋・東晋） */
  era: z.string().min(1),
  form: z.enum(KANSHI_FORMS),
  exampleId: z.string(),
  ends: z.array(z.string().min(1)).min(4),
  rhyme: z.object({
    /** 押韻する句（1から数える） */
    lines: z.array(z.number().int().min(1)).min(2),
    /** 韻の響き（音読みの頭の子音を除いた部分。例：イン・アイ） */
    sound: z.string().min(1),
    note: z.string().optional(),
    /** 換韻（途中で韻を換える古詩）。韻ごとの押韻する句と響き。lines は上の lines を分けたもの */
    groups: z.array(z.object({ lines: z.array(z.number().int().min(1)).min(2), sound: z.string().min(1) })).min(2).optional(),
  }),
  /** 長い詩の一節。from〜to はもとの詩での句の番号、total はもとの詩の句数 */
  excerpt: z.object({ from: z.number().int().min(1), to: z.number().int().min(1), total: z.number().int().min(1) }).optional(),
  /** 対句。lines は並んだ2句、pairs は向き合う語（「感時—恨別・花—鳥」） */
  taiku: z.array(z.object({ lines: z.tuple([z.number().int(), z.number().int()]), pairs: z.string().min(1) })).default([]),
  /** 構成・鑑賞の要点 */
  points: z.array(z.string().min(1)).default([]),
  rank: z.enum(["A", "B", "C"]),
});

/** 書棚「常識」（文学史・思想）の分類。画面の並びと見出しは screens/jo.ts。docs/kanbun/設計.md 7章 Phase 7 */
export const JOSHIKI_CATS = ["shiso", "shisho", "bunsho", "shijin"] as const;
export type JoshikiCat = (typeof JOSHIKI_CATS)[number];

/** 常識の年表の時代（古い順）。唐は詩の時代区分に合わせて盛唐・中唐・晩唐に分ける */
export const ERAS = ["春秋", "戦国", "前漢", "後漢", "三国", "西晋", "東晋", "南朝", "盛唐", "中唐", "晩唐", "北宋", "南宋", "元"] as const;
export type Era = (typeof ERAS)[number];

/** 常識の学習項目（人物・書物）。exampleIds はその人物・書物の一節（照合済みの例文）。
    era が無いもの（唐宋八大家のように時代をまたぐもの・成立の時代がはっきりしないもの）は年表に並べない */
export const JoshikiSchema = z.object({
  id: z.string().regex(/^kb-j-[a-z0-9-]+$/),
  cat: z.enum(JOSHIKI_CATS),
  /** 見出し（孟子・司馬遷と『史記』・唐宋八大家 など） */
  name: z.string().min(1),
  /** 見出しの読み（現代仮名遣い。人名・書名の読みなので） */
  yomi: z.string().min(1),
  era: z.enum(ERAS).optional(),
  summary: z.string().min(1),
  keywords: z.array(z.string().min(1)).default([]),
  points: z.array(z.string().min(1)).default([]),
  exampleIds: z.array(z.string()).min(1),
  rank: z.enum(["A", "B", "C"]),
});

/** 設問の種類。yomi＝傍線部の読み（二の門）、kakikudashi＝書き下し文・kaishaku＝解釈（三の門）、
    imi＝語の意味（一の門。共通テストの「ここでの意味」の設問は二の門の用法につながるものもある）、
    kaeriten＝返り点の付け方（四の門「試」。傍線部の読み reading に合う返り点を、返り点だけを付けた白文の選択肢から選ぶ）、
    oin＝押韻の空欄補充・taiku＝対句の空欄補充・keishiki＝詩の形式と押韻（四の門「試」の漢詩。target は空欄の範囲、keishiki は空）。
    漢詩の句の解釈は kaishaku で、refs が漢詩（kb-s-）になる（Phase 6 その7）。
    joshiki＝常識の四択（書棚「常識」。本文はその人物・書物の一節で、傍線部は無い。target は空。Phase 7） */
export const QUESTION_TYPES = ["yomi", "kakikudashi", "kaishaku", "imi", "kaeriten", "oin", "taiku", "keishiki", "joshiki"] as const;

export const QuestionSchema = z.object({
  id: z.string().regex(/^kb-q-[a-z0-9-]+$/),
  type: z.enum(QUESTION_TYPES),
  exampleId: z.string(),
  /** 例文の中の傍線部の番号 */
  target: z.string(),
  prompt: z.string().optional(),
  /** 返り点の四択（kaeriten）で、傍線部をどう読むか（書き下し文） */
  reading: z.string().optional(),
  /** 返り点の四択では、選択肢は返り点だけを付けた記法（例：不^レ患^レ無^レ位） */
  choices: z.array(z.string().min(1)).min(4).max(6),
  answer: z.number().int().min(0),
  choiceNotes: z.array(z.string().min(1)),
  explanation: z.string().min(1),
  refs: z.array(z.string()).min(1),
  source: SourceSchema,
  /** 出題中は本文の出典（作品名）を伏せる（常識の「この文の出典・作者」を問う設問） */
  hideWork: z.boolean().optional(),
}).refine((q) => q.answer < q.choices.length, { message: "answer が選択肢の範囲外です" })
  .refine((q) => q.choiceNotes.length === q.choices.length, { message: "choiceNotes の件数が選択肢と一致しません" })
  .refine((q) => new Set(q.choices).size === q.choices.length, { message: "選択肢が重複しています" })
  .refine((q) => q.type !== "kaeriten" || !!q.reading, { message: "返り点の四択には reading（傍線部の読み）が要ります" });

export type Source = z.infer<typeof SourceSchema>;
export type Example = z.infer<typeof ExampleSchema>;
export type KanjiUsage = z.infer<typeof KanjiUsageSchema>;
export type Group = z.infer<typeof GroupSchema>;
export type Question = z.infer<typeof QuestionSchema>;
export type Kukei = z.infer<typeof KukeiSchema>;
export type Vocab = z.infer<typeof VocabSchema>;
export type Kanshi = z.infer<typeof KanshiSchema>;
export type Joshiki = z.infer<typeof JoshikiSchema>;
