/* 二の門「字」。学ぶ＝同訓異字・多訓字の比べ表と例文、解く＝傍線部の読み四択。docs/kanbun/設計.md 5章 */
import type { Ctx } from "../index";
import type { Group, Question } from "../schema";
import { gateOf } from "../data";
import { isWeak, loadProgress } from "../store";
import { esc, exampleCard, topBar, type ExampleView } from "../ui";
import { dueItems, REVIEW_N } from "./review";

const KIND_LABEL = { doukun: "同訓異字", takun: "多訓字" } as const;

/** 束につながる設問（束のどれかの用法を refs に持つもの） */
export function questionsOfGroup(c: Ctx, g: Group): Question[] {
  const members = new Set(g.members);
  return c.data.questions.filter((q) => q.refs.some((r) => members.has(r)));
}

/** 束のカードの2行目。同訓異字は字の並び、多訓字（題も字も1字）は読みの並び（之 → の・これ・ゆく） */
function groupChars(c: Ctx, g: Group): string {
  if (g.kind !== "takun" || g.chars !== g.title) return g.chars;
  const yomi = g.members.map((id) => c.data.usages.get(id)?.yomi ?? "").filter(Boolean);
  return [...new Set(yomi)].join("・");
}

export function jiScreen(c: Ctx): string {
  const tab = c.arg === "solve" ? "solve" : "learn";
  const progress = loadProgress();
  const tabs = `<div class="kb-tabs" role="tablist">
    <button type="button" role="tab" class="kb-tab${tab === "learn" ? " is-on" : ""}" aria-selected="${tab === "learn"}" data-kb-go="ji" data-kb-arg="learn" data-kb-replace="1"><b>学ぶ</b><small>読みと用法を比べる</small></button>
    <button type="button" role="tab" class="kb-tab${tab === "solve" ? " is-on" : ""}" aria-selected="${tab === "solve"}" data-kb-go="ji" data-kb-arg="solve" data-kb-replace="1"><b>解く</b><small>傍線部の読み四択</small></button>
  </div>`;

  const groupCard = (g: Group, solve: boolean) => {
    const qs = questionsOfGroup(c, g);
    const done = g.members.filter((id) => (progress[id]?.seen ?? 0) > 0).length;
    const target = solve ? `data-kb-go="quiz" data-kb-arg="group:${esc(g.id)}"` : `data-kb-go="ji-group" data-kb-arg="${esc(g.id)}"`;
    return `<button type="button" class="kb-group" ${target}>
      <span class="kb-group-title">${esc(g.title)}</span>
      <span class="kb-group-chars">${esc(groupChars(c, g))}</span>
      <span class="kb-group-meta">${solve ? `${qs.length}問` : `${g.members.length}用法`} ・ 学習済 ${done}/${g.members.length}</span>
    </button>`;
  };
  const section = (kind: "doukun" | "takun", solve: boolean) => {
    const gs = c.data.groups.filter((g) => g.kind === kind);
    const lead = kind === "doukun" ? "同じ読みで意味の違う字。字を見て意味を言い分ける。" : "一字に読みが多い字。文中の位置と返り点で読みを決める。";
    return `<section class="kb-sec"><h3 class="kb-sec-title">${KIND_LABEL[kind]}<small>${lead}</small></h3><div class="kb-groups">${gs.map((g) => groupCard(g, solve)).join("")}</div></section>`;
  };

  let body: string;
  if (tab === "learn") {
    body = section("doukun", false) + section("takun", false);
  } else {
    const qs = c.data.questions.filter((q) => gateOf(q) === "ji");
    const all = qs.length;
    const weak = qs.filter((q) => isWeak(progress[q.id])).length;
    const due = dueItems("ji").length;
    const fresh = qs.filter((q) => !(progress[q.id]?.seen)).length;
    body = `<section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="random"><b>おまかせ10問</b><small>まだ解いていない問題と、間違えた問題から先に出します（未解答 ${fresh}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ji:review" ${due ? "" : "disabled"}><b>今日の復習</b><small>${due ? `忘れかけた ${due} 用法（1回に ${REVIEW_N} 問まで）` : "今日の分はありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="ji:weak" ${weak ? "" : "disabled"}><b>苦手だけ</b><small>${weak ? `間違えたままの ${weak}問` : "まだありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="all"><b>全問</b><small>${all}問を順不同で</small></button>
    </div></section>
    ${section("doukun", true)}${section("takun", true)}`;
  }
  return `${topBar({ title: "二の門「字」", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">二の門</span><h2>字<small>読みと用法</small></h2></header>
    ${tabs}${body}`;
}

/** 束の画面の例文カード。段の切り替えのたびに引き直す */
export function groupViews(c: Ctx): Map<string, ExampleView> {
  const out = new Map<string, ExampleView>();
  const g = c.data.groups.find((x) => x.id === c.arg);
  if (!g) return out;
  for (const uid of g.members) {
    const u = c.data.usages.get(uid);
    if (!u) continue;
    for (const eid of u.exampleIds) {
      const e = c.data.examples.get(eid);
      if (!e) continue;
      const key = `${uid}/${eid}`;
      out.set(key, { key, example: e, stage: c.stages.get(key) ?? "kundoku", highlight: "1" });
    }
  }
  return out;
}

export function groupScreen(c: Ctx): string {
  const g = c.data.groups.find((x) => x.id === c.arg);
  if (!g) return `${topBar({ title: "二の門「字」", back: { label: "字" } }, c.meta)}<p class="kb-empty">この束は見つかりませんでした。</p>`;
  const views = groupViews(c);
  const usages = g.members.map((id) => c.data.usages.get(id)!).filter(Boolean);

  const table = `<table class="kb-table">
    <thead><tr><th scope="col">字</th><th scope="col">読み</th><th scope="col">意味</th></tr></thead>
    <tbody>${usages.map((u) => `<tr><th scope="row" class="kb-table-kanji">${esc(u.kanji)}</th><td class="kb-table-yomi">${esc(u.yomi)}</td><td>${esc(u.gloss)}</td></tr>`).join("")}</tbody>
  </table>`;

  const cards = usages.map((u) => {
    const exs = u.exampleIds.map((eid) => views.get(`${u.id}/${eid}`)).filter((v): v is ExampleView => !!v);
    return `<article class="kb-usage" id="${esc(u.id)}">
      <header class="kb-usage-head"><span class="kb-usage-kanji">${esc(u.kanji)}</span><span class="kb-usage-yomi">${esc(u.yomi)}</span><span class="kb-rank" title="頻出度">${u.rank}</span></header>
      <p class="kb-usage-gloss">${esc(u.gloss)}</p>
      <p class="kb-usage-note">${esc(u.usage)}</p>
      ${exs.map((v) => exampleCard(v, c.meta)).join("")}
    </article>`;
  }).join("");

  const qs = questionsOfGroup(c, g);
  return `${topBar({ title: `${KIND_LABEL[g.kind]}「${g.title}」`, back: { label: "字" } }, c.meta)}
    <header class="kb-grouphead">
      <span class="kb-grouphead-kind">${KIND_LABEL[g.kind]}</span>
      <h2>${esc(g.title)}</h2>
      <p class="kb-grouphead-chars">${esc(g.chars)}</p>
      <p class="kb-grouphead-lead">${esc(g.lead)}</p>
    </header>
    ${table}
    ${g.points.length ? `<ul class="kb-points">${g.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}
    <p class="kb-hint">例文の<span class="kb-hint-hl">朱の字</span>が、その用法の字です。段のボタンで 白文 → 訓読文 → 書き下し文 → 現代語訳 を切り替えられます。</p>
    ${cards}
    <div class="kb-actions"><button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="group:${esc(g.id)}">この束を解く（${qs.length}問）</button></div>`;
}
