/* 漢文の画面で共通に使う部品（上の帯・例文の4段表示）。 */
import { esc, kundokuHTML, rubyTextHTML, STAGES, type Stage } from "./render";
import { isPoemText, markText, poemLines } from "./markup";
import type { Example, Question } from "./schema";
import type { Meta } from "./store";
import { kanbunData } from "./data";

export { esc };

export interface TopBarOptions {
  title: string;
  /** 左上の戻るボタン。無ければ「科目えらびへ」 */
  back?: { label: string };
}

/** 上の帯：戻る／題／縦横の切り替え／明暗。data-kb-act で index.ts が受ける */
export function topBar(o: TopBarOptions, meta: Meta): string {
  const back = o.back
    ? `<button type="button" class="kb-btn kb-ghost kb-back" data-kb-act="back">← ${esc(o.back.label)}</button>`
    : `<button type="button" class="kb-btn kb-ghost kb-back" data-kb-act="picker">← 科目えらびへ</button>`;
  return `<div class="kb-top">
    ${back}
    <span class="kb-top-title">${esc(o.title)}</span>
    <span class="kb-top-tools">
      <button type="button" class="kb-btn kb-ghost kb-dir" data-kb-act="dir" aria-label="${meta.vertical ? "横書きにする" : "縦書きにする"}" title="縦書き／横書き">${meta.vertical ? "縦" : "横"}</button>
      <button type="button" class="kb-btn kb-ghost kb-theme" data-kb-act="theme" aria-label="明るさの切り替え" title="明るさの切り替え">◐</button>
    </span>
  </div>`;
}

export interface ExampleView {
  /** 画面の中で一意な名前（段の切り替えで本文だけを描き直すのに使う） */
  key: string;
  example: Example;
  stage: Stage;
  /** 傍線部を朱で示す */
  highlight?: string;
  /** 傍線を引く */
  bosen?: string;
  /** 傍線部を白文で伏せる（出題中） */
  mask?: string;
  /** 伏せるときに返り点は残す（解釈四択） */
  maskKeepKaeri?: boolean;
  /** 空欄にする範囲（漢詩の押韻・対句の空欄補充） */
  blank?: string;
  /** 漢詩で、韻字を丸で囲む句（1から数える） */
  rhyme?: number[];
  /** 出典（作品名）を伏せる（常識の「この文の出典・作者」を問う設問の出題中） */
  hideWork?: boolean;
  /** 本文の字を押して字引を開ける（出題中は開けない） */
  lookup?: boolean;
}

export function stageBody(v: ExampleView, meta: Meta): string {
  const dir = meta.vertical ? "kb-v" : "kb-h";
  const e = v.example;
  // 漢詩は句ごとに行（縦書きは列）を改める。書き下し文と訳も句ごとに分けて並べる
  const poem = isPoemText(e.kundoku);
  if (v.stage === "hakubun" || v.stage === "kundoku") {
    const html = kundokuHTML(e.kundoku, {
      hakubun: v.stage === "hakubun",
      highlight: v.highlight,
      bosen: v.bosen,
      mask: v.mask,
      maskKeepKaeri: v.maskKeepKaeri,
      blank: v.blank,
      rhyme: v.rhyme,
    });
    return `<div class="kb-text ${dir}${poem ? " kb-poemtext" : ""}${meta.furigana ? "" : " kb-nofuri"}">${html}</div>`;
  }
  if (v.stage === "kakikudashi") {
    const lines = poemLines(e.kakikudashi);
    return `<div class="kb-plain ${dir}${poem ? " kb-poemplain" : ""}">${lines.map((l) => `<p>${rubyTextHTML(l)}</p>`).join("")}</div>`;
  }
  return `<div class="kb-yaku${poem ? " kb-poemyaku" : ""}">${poemLines(e.yaku).map((l) => `<p>${esc(l)}</p>`).join("")}</div>`;
}

/** 例文のカード。段付きのボタン（白文 → 訓読文 → 書き下し文 → 現代語訳）と「一段ずつめくる」 */
export function exampleCard(v: ExampleView, meta: Meta, opts: { stages?: boolean } = {}): string {
  const stages = opts.stages !== false;
  const tabs = stages
    ? `<div class="kb-stages" role="tablist" aria-label="表示する段">
        ${STAGES.map((s, i) => `<button type="button" role="tab" class="kb-stage${s.id === v.stage ? " is-on" : ""}" aria-selected="${s.id === v.stage}" data-kb-stage="${esc(v.key)}:${s.id}"><span class="kb-stage-no">${"一二三四"[i]}</span>${s.label}</button>`).join("")}
        <button type="button" class="kb-stage kb-flip" data-kb-flip="${esc(v.key)}" title="一段ずつめくる">めくる ▸</button>
      </div>`
    : "";
  // 長文（共通テストの本文など）は縦書きの欄を高くし、傍線部まで横に送って見せる（index.ts の revealMarks）
  const poem = isPoemText(v.example.kundoku);
  const long = (v.example.long ? " kb-long" : "") + (poem ? " kb-poem" : "");
  // 縦書きで欄に収まらない本文（長文と、句の多い漢詩＝390px幅で五句より多いもの）には、左へ送る案内を添える
  const wide = v.example.long || (poem && poemLines(v.example.kundoku).length > 5);
  const hint = wide && meta.vertical ? `<span class="kb-scrollhint">本文は左へ送って続きを読む</span>` : "";
  // 字引：本文の字を押すと、その字と位置を引く（index.ts の onClick が data-kb-ex と data-ci から引く）
  const look = v.lookup !== false && meta.lookup ? ` data-kb-ex="${esc(v.example.id)}"` : "";
  const work = v.hideWork ? `<span class="kb-work-hidden">出典は答えたあとに示します</span>` : esc(v.example.work);
  return `<figure class="kb-example${long}${look ? " kb-lookup" : ""}" data-kb-card="${esc(v.key)}"${look}>
    ${tabs}
    <div class="kb-stagebody">${stageBody(v, meta)}</div>
    <figcaption class="kb-work">${hint}${work}</figcaption>
  </figure>`;
}

/** 選択肢の番号（①〜⑥。共通テストの漢詩の形式と押韻の設問は6択） */
export function circled(i: number): string {
  return "①②③④⑤⑥"[i] ?? String(i + 1);
}

export function sourceNote(e: Example): string {
  const made = "訓点・書き下し文・現代語訳・解説は本アプリで作成";
  if (e.source.kind === "pdf") return `出典：${esc(e.source.label ?? "")}${e.sourceNote ? `（${esc(e.sourceNote)}）` : ""}`;
  if (e.source.kind === "exam") return `出典：${esc(e.source.label ?? "")}（${esc(e.work)}）。${e.sourceNote ? `${esc(e.sourceNote)}。` : ""}書き下し文・現代語訳・解説は本アプリで作成。`;
  const note = e.sourceNote ? `${esc(e.sourceNote)}。` : "";
  return `原文：${esc(e.work)}${e.reviewed ? "（原文をオンライン資料と照合済み）" : ""}。${note}${made}。`;
}

/** 結果や苦手帳の一覧に出す正答。返り点の四択は、選択肢（記法）の代わりに読み（書き下し文）を出す */
export function answerText(q: Question): string {
  return q.type === "kaeriten" ? (q.reading ?? "") : q.choices[q.answer];
}

/** 漢詩の設問（押韻・対句の空欄、形式と押韻） */
export const KANSHI_TYPES: ReadonlyArray<Question["type"]> = ["oin", "taiku", "keishiki"];

/** 結果や苦手帳の一覧に出す、問うた所。ふつうは傍線部の白文。漢詩の設問は詩の題と空欄の句 */
export function targetText(q: Question, e: Example | undefined): string {
  if (!e) return "";
  // 常識の設問は、問うた人物・書物の名
  if (q.type === "joshiki") return `${kanbunData().joshiki.get(q.refs[0])?.name ?? e.work}（常識）`;
  if (!KANSHI_TYPES.includes(q.type)) return markText(e.kundoku, q.target);
  if (q.type === "keishiki") return `${e.work}の形式と押韻`;
  const n = poemLines(e.kundoku).findIndex((l) => l.includes(`[[${q.target}|`));
  return `${e.work} 第${"一二三四五六七八九十"[n] ?? n + 1}句の空欄`;
}
