/* 訓点の記法を読み取り、白文・読む順番・書き下し文との一致を計算する。
   記法の決まりは docs/kanbun/記法.md が正本。ここを直したら記法.md も直すこと。 */

export type Kaeri =
  | "レ" | "一" | "二" | "三" | "四" | "上" | "中" | "下"
  | "甲" | "乙" | "丙" | "丁" | "一レ" | "上レ" | "甲レ";

export interface Cell {
  kind: "char";
  ch: string;
  /** 右のルビ（読み仮名）。熟語のルビは group 側に持つ */
  ruby?: string;
  /** 右下の送り仮名（カタカナ） */
  okuri?: string;
  /** 左の送り仮名（再読文字の二度目） */
  leftOkuri?: string;
  kaeri?: Kaeri;
  saidoku?: boolean;
  okiji?: boolean;
  /** 次の字と竪点でつながる */
  tate?: boolean;
  /** 傍線部の番号（範囲の中の字すべてに付く） */
  mark?: string;
  /** 熟語ルビ・竪点のまとまりの番号（同じ番号の字がひとまとまり） */
  group?: number;
}

export interface Punct {
  kind: "punct";
  ch: string;
  mark?: string;
}

export type Token = Cell | Punct;

export interface Group {
  id: number;
  ruby?: string;
}

export interface Parsed {
  tokens: Token[];
  groups: Map<number, Group>;
  marks: string[];
}

const KATAKANA = /[ァ-ヺーヽヾ]/;
const PUNCT = /[、。，．「」『』？！・：；（）〔〕／]/;
/** 漢詩の句の区切り。句読点と同じく1つの記号として読み、画面では句ごとに行（縦書きは列）を改める */
export const LINE_BREAK = "／";
const HAN = /[㐀-䶿一-鿿豈-﫿々〇]/u;
/** 句形の型（未ダ^レＡセ など）で語が入る場所を示す全角の英大文字。漢字と同じく1字として扱う */
const SLOT = /[Ａ-Ｚ]/;
const KAERI_LIST: Kaeri[] = ["一レ", "上レ", "甲レ", "レ", "一", "二", "三", "四", "上", "中", "下", "甲", "乙", "丙", "丁"];

export class MarkupError extends Error {}

/** 訓点つきの訓読文を字の並びに分解する。 */
export function parse(src: string): Parsed {
  const tokens: Token[] = [];
  const groups = new Map<number, Group>();
  const marks: string[] = [];
  let i = 0;
  let markStack: string[] = [];
  let groupSeq = 0;
  let openGroup: number | null = null;       // [ … ] の中
  let pendingTate = false;

  const lastCell = (): Cell | undefined => {
    for (let k = tokens.length - 1; k >= 0; k -= 1) {
      const t = tokens[k];
      if (t.kind === "char") return t;
    }
    return undefined;
  };
  const fail = (msg: string): never => { throw new MarkupError(`${msg}（${i}文字目付近: 「${src.slice(Math.max(0, i - 6), i + 6)}」）`); };
  const readUntil = (close: string): string => {
    const end = src.indexOf(close, i);
    if (end < 0) fail(`「${close}」で閉じていません`);
    const text = src.slice(i, end);
    i = end + close.length;
    return text;
  };

  /** 字の直後の注記（* {…} カタカナ <…> ^…）を読む。target は注記を受ける字 */
  const readAnnotations = (target: Cell, rubyTarget: "cell" | number) => {
    for (;;) {
      const c = src[i];
      if (c === "*") { target.saidoku = true; i += 1; continue; }
      if (c === "{") {
        i += 1;
        const ruby = readUntil("}");
        if (rubyTarget === "cell") target.ruby = ruby;
        else groups.get(rubyTarget)!.ruby = ruby;
        continue;
      }
      if (c === "<") { i += 1; target.leftOkuri = (target.leftOkuri ?? "") + readUntil(">"); continue; }
      if (c !== undefined && KATAKANA.test(c)) {
        let run = "";
        while (i < src.length && KATAKANA.test(src[i])) { run += src[i]; i += 1; }
        target.okuri = (target.okuri ?? "") + run;
        continue;
      }
      if (c === "^") {
        i += 1;
        const k = KAERI_LIST.find((x) => src.startsWith(x, i));
        if (!k) fail("返り点が読めません");
        if (target.kaeri) fail("1字に返り点が2つあります");
        target.kaeri = k;
        i += k!.length;
        continue;
      }
      break;
    }
  };

  const pushChar = (ch: string, okiji: boolean): Cell => {
    const cell: Cell = { kind: "char", ch };
    if (okiji) cell.okiji = true;
    if (markStack.length) cell.mark = markStack[markStack.length - 1];
    if (openGroup != null) cell.group = openGroup;
    if (pendingTate) {
      const prev = lastCell();
      if (prev) prev.tate = true;
      // 竪点でつないだ2字は、ひとまとまり（group）として読む
      if (prev && cell.group == null) {
        if (prev.group == null) { groupSeq += 1; prev.group = groupSeq; groups.set(groupSeq, { id: groupSeq }); }
        cell.group = prev.group;
      }
      pendingTate = false;
    }
    tokens.push(cell);
    return cell;
  };

  while (i < src.length) {
    const c = src[i];
    if (c === " " || c === "　" || c === "\n") { i += 1; continue; }
    if (src.startsWith("[[", i)) {
      i += 2;
      const bar = src.indexOf("|", i);
      if (bar < 0) fail("傍線部の番号の後に「|」がありません");
      const label = src.slice(i, bar).trim();
      if (!label) fail("傍線部の番号が空です");
      if (marks.includes(label)) fail(`傍線部の番号 ${label} が重複しています`);
      marks.push(label);
      markStack.push(label);
      i = bar + 1;
      continue;
    }
    if (src.startsWith("]]", i)) {
      if (!markStack.length) fail("対応する「[[」がありません");
      markStack.pop();
      i += 2;
      continue;
    }
    if (c === "[") {
      if (openGroup != null) fail("熟語の [ ] が入れ子になっています");
      groupSeq += 1;
      openGroup = groupSeq;
      groups.set(groupSeq, { id: groupSeq });
      i += 1;
      continue;
    }
    if (c === "]") {
      if (openGroup == null) fail("対応する「[」がありません");
      const gid = openGroup as number;
      openGroup = null;
      i += 1;
      // 熟語全体の注記はまとまりの最後の字が受ける（ルビだけはまとまり全体）
      const cell = lastCell();
      if (!cell || cell.group !== gid) fail("[ ] の中に字がありません");
      readAnnotations(cell!, gid);
      continue;
    }
    if (c === "-") { pendingTate = true; i += 1; continue; }
    if (c === "_") {
      i += 1;
      const ch = src[i];
      if (!ch || !HAN.test(ch)) fail("「_」の後に置き字がありません");
      i += 1;
      const cell = pushChar(ch, true);
      readAnnotations(cell, "cell");
      continue;
    }
    if (PUNCT.test(c)) {
      const p: Punct = { kind: "punct", ch: c };
      if (markStack.length) p.mark = markStack[markStack.length - 1];
      tokens.push(p);
      i += 1;
      continue;
    }
    if (HAN.test(c) || SLOT.test(c)) {
      i += c.length;
      const cell = pushChar(c, false);
      readAnnotations(cell, "cell");
      continue;
    }
    // 返り点・送り仮名が閉じ括弧の後に来た場合（例：[[1|為]]^レ）は直前の字に付ける
    if (c === "^" || c === "*" || c === "<" || KATAKANA.test(c) || c === "{") {
      const cell = lastCell();
      if (!cell) fail("注記を付ける字がありません");
      readAnnotations(cell!, "cell");
      continue;
    }
    fail(`読めない文字「${c}」があります`);
  }
  if (markStack.length) fail("傍線部の「]]」が閉じていません");
  if (openGroup != null) fail("熟語の「]」が閉じていません");
  if (pendingTate) fail("竪点「-」の後に字がありません");
  return { tokens, groups, marks };
}

/** 白文（訓点を取り除き、句読点だけを残したもの） */
export function hakubun(src: string): string {
  return parse(src).tokens.map((t) => t.ch).join("");
}

/** 漢詩の句（／で区切った訓読文・書き下し文・訳）。区切りが無ければ1句 */
export function poemLines(src: string): string[] {
  return src.split(LINE_BREAK);
}

/** 漢詩（句を ／ で区切った本文）かどうか */
export function isPoemText(src: string): boolean {
  return src.includes(LINE_BREAK);
}

/** 傍線部の白文 */
export function markText(src: string, label: string): string {
  return parse(src).tokens.filter((t) => t.mark === label).map((t) => t.ch).join("");
}

/* ---------- 読む順番 ---------- */

export interface ReadStep {
  /** tokens の中の位置 */
  index: number;
  ch: string;
  /** 再読文字の2度目 */
  second?: boolean;
}

type Klass = "re" | "num" | "ud" | "kou";
const RANK: Record<string, [Klass, number]> = {
  一: ["num", 1], 二: ["num", 2], 三: ["num", 3], 四: ["num", 4],
  上: ["ud", 1], 中: ["ud", 2], 下: ["ud", 3],
  甲: ["kou", 1], 乙: ["kou", 2], 丙: ["kou", 3], 丁: ["kou", 4],
};

interface Unit {
  /** まとまりを構成する字（tokens の位置） */
  cells: number[];
  kaeri?: Kaeri;
}

/** 竪点・熟語でつないだ字をまとまりにする。返り点はまとまりの最後の字に書く決まり。置き字は除く */
function units(tokens: Token[]): Unit[] {
  const out: Unit[] = [];
  let cur: Unit | null = null;
  let curGroup: number | undefined;
  tokens.forEach((t, idx) => {
    if (t.kind !== "char" || t.okiji) { cur = null; curGroup = undefined; return; }
    if (cur && t.group != null && t.group === curGroup) {
      cur.cells.push(idx);
    } else {
      cur = { cells: [idx] };
      curGroup = t.group;
      out.push(cur);
    }
    if (t.kaeri) cur.kaeri = t.kaeri;
  });
  return out;
}

export interface OrderResult {
  steps: ReadStep[];
  errors: string[];
}

/** 返り点から読む順番を計算する（docs/kanbun/記法.md 3章） */
export function readingOrder(tokens: Token[]): OrderResult {
  const us = units(tokens);
  const steps: ReadStep[] = [];
  const errors: string[] = [];
  const stack: { unit: Unit; klass: Klass; rank: number; re: boolean }[] = [];

  // 再読文字は1度目をその位置で出してあるので、返ってきたときに出す分が2度目になる（最後にまとめて印を付ける）
  const emit = (u: Unit) => {
    for (const idx of u.cells) steps.push({ index: idx, ch: tokens[idx].ch });
  };

  /** まとまりを「今」読む。そのあと、返る先があれば返る */
  const read = (u: Unit) => {
    emit(u);
    const k = u.kaeri;
    // 一レ・上レ・甲レは、レ点として返ってきた後で一・上・甲として働く
    const numMark = k === "一レ" ? "一" : k === "上レ" ? "上" : k === "甲レ" ? "甲" : k;
    // 1. 直前にレ点で後回しにした字へ返る
    while (stack.length && stack[stack.length - 1].re) {
      const top = stack.pop()!;
      read(top.unit);
    }
    // 2. 一点（上点・甲点）を読んだら、二点（中・下／乙…）へ返る
    if (numMark && RANK[numMark]) {
      const [klass, rank] = RANK[numMark];
      const top = stack[stack.length - 1];
      if (top && !top.re && top.klass === klass && top.rank > rank) {
        stack.pop();
        read(top.unit);
      } else if (rank === 1) {
        errors.push(`${numMark}点の「${u.cells.map((c) => tokens[c].ch).join("")}」から返る先（${klass === "num" ? "二" : klass === "ud" ? "下" : "乙"}点）がありません`);
      }
    }
  };

  us.forEach((u, n) => {
    const k = u.kaeri;
    const first = tokens[u.cells[0]] as Cell;
    const isRe = k === "レ" || k === "一レ" || k === "上レ" || k === "甲レ";
    const deferred = k && !isRe && RANK[k] && RANK[k][1] > 1;
    if (isRe || deferred) {
      if (n === us.length - 1) errors.push(`最後の字「${first.ch}」に返り点があり、返る先がありません`);
      // 再読文字は、その位置で1度目を読む
      if (first.saidoku) for (const idx of u.cells) steps.push({ index: idx, ch: tokens[idx].ch });
      if (isRe) stack.push({ unit: u, klass: "re", rank: 0, re: true });
      else { const [klass, rank] = RANK[k!]; stack.push({ unit: u, klass, rank, re: false }); }
      return;
    }
    read(u);
  });
  if (stack.length) {
    errors.push(`返らないまま残った字があります：${stack.map((s) => s.unit.cells.map((c) => tokens[c].ch).join("")).join("・")}`);
  }
  // 同じ字が2度出ていれば、2度目が再読文字の二度目の読み
  const seen = new Set<number>();
  for (const s of steps) {
    if (seen.has(s.index)) s.second = true; else { seen.add(s.index); delete s.second; }
  }
  return { steps, errors };
}

/** 返り点の組み合わせを検査する。問題が無ければ空配列 */
export function validateKaeriten(src: string): string[] {
  let parsed: Parsed;
  try { parsed = parse(src); } catch (e) { return [(e as Error).message]; }
  const errors = [...readingOrder(parsed.tokens).errors];
  for (const t of parsed.tokens) {
    if (t.kind === "char" && t.okiji && t.kaeri) errors.push(`置き字「${t.ch}」に返り点があります`);
  }
  return errors;
}

/* ---------- 書き下し文との一致 ---------- */

/** 書き下し文でひらがなに開いてよい字（助詞・助動詞に当たる字など）。docs/kanbun/記法.md 4章 */
export const OPEN_CHARS = new Set(
  "不弗也可使令教遣見被為之与如若乎哉耶邪歟矣焉耳已爾而於于者自従由毋勿莫無非所以蓋盍夫".split(""),
);

/** 書き下し文から読み仮名 {…} を取り除く */
export function stripRuby(text: string): string {
  return text.replace(/\{[^}]*\}/g, "").replace(/[[\]]/g, "");
}

/** 読む順番の漢字が、書き下し文の漢字と同じ順に出てくるか確かめる。問題が無ければ空配列 */
export function checkKakikudashi(kundoku: string, kakikudashi: string): string[] {
  const { tokens } = parse(kundoku);
  const { steps, errors } = readingOrder(tokens);
  if (errors.length) return errors;
  const reading = steps.filter((s) => !s.second).map((s) => s.ch);
  const kk = [...stripRuby(kakikudashi)].filter((ch) => HAN.test(ch) || SLOT.test(ch));
  const out: string[] = [];
  let j = 0;
  for (const ch of reading) {
    if (j < kk.length && kk[j] === ch) { j += 1; continue; }
    if (OPEN_CHARS.has(ch)) continue;
    out.push(`読む順番では「${ch}」の番ですが、書き下し文は「${kk[j] ?? "（終わり）"}」になっています（読む順：${reading.join("")}）`);
    return out;
  }
  if (j < kk.length) out.push(`書き下し文に、訓読文に無い字「${kk.slice(j).join("")}」があります`);
  return out;
}

/** 読む順番に並べた字（再読文字の2度目は括弧つき）。画面の「読む順番」表示と検査の報告に使う */
export function orderString(kundoku: string): string {
  const { tokens } = parse(kundoku);
  return readingOrder(tokens).steps.map((s) => (s.second ? `（${s.ch}）` : s.ch)).join("");
}

/** 歴史的仮名遣いになっていない疑いがある箇所を返す（警告） */
const MODERN_KANA: [RegExp, string][] = [
  [/すなわ/, "すなはち"],
  [/ゆえ/, "ゆゑ"],
  [/いわく|いわゆる/, "いはく／いはゆる"],
  [/おもえら/, "おもへらく"],
  [/こうむ/, "かうむる"],
  [/[言思問云謂笑会逢買]う(?![ゐゑ])/u, "〜ふ（言ふ・思ふ）"],
  [/しこうして/, "しかうして"],
  [/なんじ/, "なんぢ"],
  [/あたう/, "あたふ"],
];
export function kanaWarnings(text: string): string[] {
  const plain = stripRuby(text);
  return MODERN_KANA.filter(([re]) => re.test(plain)).map(([re, hint]) => `現代仮名遣いの疑い（${re.source}）→ ${hint}`);
}
