/* 書棚「常識」（文学史・思想）。docs/kanbun/設計.md 7章 Phase 7 その2
   学ぶ＝4分類の目次と年表 → 分類の画面（表・人物や書物のカード・その一節）、
   解く＝常識の四択（人物・書物の説明を選ぶ／出典・作者を選ぶ）。 */
import type { Ctx } from "../index";
import type { Joshiki, JoshikiCat, Question } from "../schema";
import { ERAS, JOSHIKI_CATS } from "../schema";
import { gateOf } from "../data";
import { isWeak, loadProgress } from "../store";
import { esc, exampleCard, topBar, type ExampleView } from "../ui";
import { dueItems, REVIEW_N } from "./review";

interface CatInfo { title: string; lead: string }

/** 4分類の見出しと説明（docs/kanbun/網羅表.md 6章の並び） */
export const JO_CATS: Record<JoshikiCat, CatInfo> = {
  shiso: { title: "思想", lead: "孔子・孟子・荀子の儒家、老子・荘子の道家、墨家・法家と、儒家の経典（五経・四書）。本文の考え方をつかむ手がかりになる。" },
  shisho: { title: "史書と説話", lead: "『史記』『漢書』『資治通鑑』『十八史略』などの歴史書と、『戦国策』『世説新語』などの説話の書。紀伝体と編年体の違いも。" },
  bunsho: { title: "文章", lead: "韓愈・柳宗元の古文運動と唐宋八大家、「出師表」「桃花源記」「岳陽楼記」など、よく読まれる名文と作者。" },
  shijin: { title: "詩人と詩集", lead: "『詩経』『楚辞』から、陶淵明、盛唐の李白・杜甫・王維、中唐の白居易、晩唐の杜牧・李商隠まで。" },
};
export const JO_CAT_LABEL: Record<string, string> = Object.fromEntries(JOSHIKI_CATS.map((k) => [k, JO_CATS[k].title]));

export function joshikiOfCat(c: Ctx, cat: string): Joshiki[] {
  return [...c.data.joshiki.values()].filter((j) => j.cat === cat);
}

/** 分類につながる設問 */
export function questionsOfJoshikiCat(c: Ctx, cat: string): Question[] {
  const ids = new Set(joshikiOfCat(c, cat).map((j) => j.id));
  return c.data.questions.filter((q) => q.refs.some((r) => ids.has(r)));
}

/** 年表：時代の古い順に、その時代の人物・書物を並べる（時代を持たない項目は並べない） */
function nenpyoHTML(c: Ctx): string {
  const all = [...c.data.joshiki.values()];
  const rows = ERAS.map((era) => {
    const xs = all.filter((j) => j.era === era);
    if (!xs.length) return "";
    return `<tr><th scope="row">${esc(era)}</th><td>${xs.map((j) => `<button type="button" class="kb-jump" data-kb-jump="${esc(j.id)}">${esc(j.name)}</button>`).join("")}</td></tr>`;
  }).join("");
  return `<table class="kb-table kb-nenpyo"><thead><tr><th scope="col">時代</th><th scope="col">人物・書物</th></tr></thead><tbody>${rows}</tbody></table>`;
}

export function joScreen(c: Ctx): string {
  const tab = c.arg === "solve" ? "solve" : "learn";
  const progress = loadProgress();
  const tabs = `<div class="kb-tabs" role="tablist">
    <button type="button" role="tab" class="kb-tab${tab === "learn" ? " is-on" : ""}" aria-selected="${tab === "learn"}" data-kb-go="jo" data-kb-arg="learn" data-kb-replace="1"><b>学ぶ</b><small>人物・書物と年表</small></button>
    <button type="button" role="tab" class="kb-tab${tab === "solve" ? " is-on" : ""}" aria-selected="${tab === "solve"}" data-kb-go="jo" data-kb-arg="solve" data-kb-replace="1"><b>解く</b><small>説明・出典・作者の四択</small></button>
  </div>`;

  const catCard = (cat: JoshikiCat, solve: boolean) => {
    const js = joshikiOfCat(c, cat);
    const done = js.filter((j) => (progress[j.id]?.seen ?? 0) > 0).length;
    const qs = questionsOfJoshikiCat(c, cat);
    const sample = js.slice(0, 5).map((j) => j.name.replace(/[『』「」]/g, "").replace(/（[^）]*）/g, "")).join("・");
    const target = solve ? `data-kb-go="quiz" data-kb-arg="jcat:${cat}"` : `data-kb-go="jo-cat" data-kb-arg="${cat}"`;
    return `<button type="button" class="kb-group" ${target}>
      <span class="kb-group-title">${esc(JO_CATS[cat].title)}</span>
      <span class="kb-group-chars kb-group-names">${esc(sample)}…</span>
      <span class="kb-group-meta">${solve ? `${qs.length}問` : `${js.length}項目`} ・ 学習済 ${done}/${js.length}</span>
    </button>`;
  };

  let body: string;
  if (tab === "learn") {
    body = `<section class="kb-sec"><h3 class="kb-sec-title">人物と書物<small>分類を選ぶと、説明・キーワード・要点と、その人物・書物の一節が並ぶ。</small></h3>
      <div class="kb-groups">${JOSHIKI_CATS.map((k) => catCard(k, false)).join("")}</div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">年表<small>時代の古い順。唐は詩の時代区分（盛唐・中唐・晩唐）で分けた。名を押すとカードへ。</small></h3>${nenpyoHTML(c)}</section>`;
  } else {
    const all = c.data.questions.filter((q) => gateOf(q) === "jo");
    const weak = all.filter((q) => isWeak(progress[q.id])).length;
    const due = dueItems("jo").length;
    const fresh = all.filter((q) => !(progress[q.id]?.seen)).length;
    const nWho = all.filter((q) => q.hideWork).length;
    body = `<section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="jo:random"><b>おまかせ10問</b><small>まだ解いていない問題と、間違えた問題から先に出します（未解答 ${fresh}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="jo:who"><b>出典・作者を当てる</b><small>出典を伏せた一節から、書物や作者を選ぶ（${nWho}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="jo:review" ${due ? "" : "disabled"}><b>今日の復習</b><small>${due ? `忘れかけた ${due} 項目（1回に ${REVIEW_N} 問まで）` : "今日の分はありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="jo:weak" ${weak ? "" : "disabled"}><b>苦手だけ</b><small>${weak ? `間違えたままの ${weak}問` : "まだありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="jo:all"><b>全問</b><small>${all.length}問を順不同で</small></button>
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">分類ごとに解く</h3><div class="kb-groups">${JOSHIKI_CATS.map((k) => catCard(k, true)).join("")}</div></section>`;
  }
  return `${topBar({ title: "書棚「常識」", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">書棚</span><h2>常識<small>文学史と思想</small></h2></header>
    <p class="kb-hint">共通テストで直接は問われませんが、本文の前書きや注に出る人物・書物を知っていると、本文を速く正しく読めます。</p>
    ${tabs}${body}`;
}

/** 分類の画面の例文カード。段の切り替えのたびに引き直す */
export function joshikiViews(c: Ctx): Map<string, ExampleView> {
  const out = new Map<string, ExampleView>();
  for (const j of joshikiOfCat(c, c.arg ?? "")) {
    for (const eid of j.exampleIds) {
      const e = c.data.examples.get(eid);
      if (!e) continue;
      const key = `${j.id}/${eid}`;
      out.set(key, { key, example: e, stage: c.stages.get(key) ?? "kundoku" });
    }
  }
  return out;
}

export function joCatScreen(c: Ctx): string {
  const cat = c.arg as JoshikiCat | undefined;
  const info = cat ? JO_CATS[cat] : undefined;
  const js = cat ? joshikiOfCat(c, cat) : [];
  if (!info || !js.length) return `${topBar({ title: "書棚「常識」", back: { label: "常識" } }, c.meta)}<p class="kb-empty">この分類は見つかりませんでした。</p>`;
  const views = joshikiViews(c);

  const table = `<table class="kb-table kb-jtable">
    <thead><tr><th scope="col">人物・書物</th><th scope="col">時代</th><th scope="col">キーワード</th></tr></thead>
    <tbody>${js.map((j) => `<tr><th scope="row" class="kb-table-kanji"><button type="button" class="kb-jump" data-kb-jump="${esc(j.id)}">${esc(j.name)}</button></th><td class="kb-table-yomi">${esc(j.era ?? "—")}</td><td>${esc(j.keywords.slice(0, 3).join("・"))}</td></tr>`).join("")}</tbody>
  </table>`;

  const cards = js.map((j) => {
    const exs = j.exampleIds.map((eid) => views.get(`${j.id}/${eid}`)).filter((x): x is ExampleView => !!x);
    return `<article class="kb-usage kb-joshiki" id="${esc(j.id)}">
      <header class="kb-usage-head"><span class="kb-usage-kanji kb-joshiki-name">${esc(j.name)}</span><span class="kb-usage-yomi">${esc(j.yomi)}</span>${j.era ? `<span class="kb-era">${esc(j.era)}</span>` : ""}<span class="kb-rank" title="頻出度">${j.rank}</span></header>
      <p class="kb-usage-gloss">${esc(j.summary)}</p>
      ${j.keywords.length ? `<p class="kb-keywords">${j.keywords.map((k) => `<span class="kb-keyword">${esc(k)}</span>`).join("")}</p>` : ""}
      ${j.points.length ? `<ul class="kb-points">${j.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}
      ${exs.map((x) => exampleCard(x, c.meta)).join("")}
    </article>`;
  }).join("");

  const qs = questionsOfJoshikiCat(c, cat!);
  return `${topBar({ title: `常識「${info.title}」`, back: { label: "常識" } }, c.meta)}
    <header class="kb-grouphead">
      <span class="kb-grouphead-kind">書棚　常識</span>
      <h2>${esc(info.title)}</h2>
      <p class="kb-grouphead-lead">${esc(info.lead)}</p>
    </header>
    ${table}
    ${cards}
    <div class="kb-actions"><button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="jcat:${esc(cat!)}">この分類を解く（${qs.length}問）</button></div>`;
}
