/* 四択の演習。一の門「語」の意味四択、二の門「字」の読み四択と、三の門「句」の書き下し四択・解釈四択、四の門「試」の総合演習。docs/kanbun/設計.md 5章「正誤の演出」
   - 出題中は傍線部を伏せる。読み・書き下しは白文（読み仮名・送り仮名・返り点を出さない）、
     解釈・意味は返り点だけを残す（共テの紙面と同じく、送り仮名・読み仮名が答えの手がかりにならないように）
   - 正解：朱印「正」。不正解：墨の「×」を出し、正答の傍線部を朱にする
   - 解説：例文の全段と、選択肢1つずつの説明
   - 本番形式（四の門の exam:…）：その場では判定せず、問題を行き来して答えを選び、最後にまとめて採点する。時間を計る。
     採点のあとは結果から1問ずつの解説（kaisetsu）を開く */
import type { Ctx, GoOptions, Screen } from "../index";
import type { Question } from "../schema";
import { markText } from "../markup";
import { kundokuHTML, rubyTextHTML } from "../render";
import { isWeak, loadMeta, loadProgress, recordAnswer, saveMeta, writeStats, type ExamLog } from "../store";
import { localDate } from "../srs";
import { gateOf, learningItemIds, type Gate } from "../data";
import { answerText, circled, esc, exampleCard, KANSHI_TYPES, sourceNote, targetText, topBar, type ExampleView } from "../ui";
import { KANSHI_FORM_NAME } from "../schema";
import { questionsOfGroup } from "./ji";
import { KU_CAT_LABEL, questionsOfCat } from "./ku";
import { GO_CAT_LABEL, questionsOfVocabCat } from "./go";
import { dueItems, reviewQuestions } from "./review";
import { clock, examable, examLimitSec, examQuestions, kaeritenQuestions, mixQuestions } from "./shi";
import { questionsOfPoem, rhymeText } from "./kanshi";
import { JO_CAT_LABEL, questionsOfJoshikiCat } from "./jo";

const RANDOM_N = 10;

/** 答え。本番形式で答えずに採点した問題は skipped（chosen は -1、不正解として数える） */
interface Answer { qid: string; chosen: number; correct: boolean; skipped?: boolean }

/** 本番形式の状態。picks は問題ごとに選んだ選択肢（元の番号。まだなら null） */
interface ExamState {
  limitSec: number;
  startedAt: number;
  endedAt: number | null;
  picks: Array<number | null>;
  /** 未解答があるのに「採点する」を押した（確かめの案内を出している） */
  confirming: boolean;
  /** 始めたときの、前回の結果（採点すると上書きするので、比べるために取っておく） */
  last: ExamLog | null;
}
/** どの門の演習か。all は書斎の苦手帳・温習（門をまたぐ）、shi は四の門「試」（門をまたぐ） */
export type QuizGate = Gate | "all" | "shi";

interface Session {
  mode: string;
  gate: QuizGate;
  title: string;
  ids: string[];
  /** 問題ごとの選択肢の並び（元の番号の並べかえ） */
  orders: number[][];
  index: number;
  answers: Answer[];
  finished: boolean;
  /** 本番形式のときだけ */
  exam?: ExamState;
}

function shuffle<T>(a: T[]): T[] {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}

/** 演習の種類（mode）から、門と出題する設問を決める。
    一の門：go:random / go:all / go:weak / go:review / go:exam / vcat:<分類>
    二の門：random / all / ji:weak / ji:review / group:<束>
    三の門：ku:random / ku:all / ku:weak / ku:review / ku:kakikudashi / ku:kaishaku / ku:exam / cat:<分類>
    四の門：shi:mix（総合演習10問）/ shi:kaeriten（返り点の四択10問）/ shi:exam（共テの設問をまとめて）/ shi:year:<年度>
            本番形式：exam:shi:mix / exam:shi:year:<年度>
            漢詩：shi:random / shi:all / shi:weak / shi:review / shi:poem:<詩>
    書棚「常識」：jo:random / jo:all / jo:weak / jo:review / jo:who（出典・作者を当てる）/ jcat:<分類>
    門をまたぐ：weak（苦手帳）・review（温習）。retry は直前の演習の間違えた問題 */
function pick(c: Ctx, mode: string, prev: Session | null): { title: string; gate: QuizGate; qs: Question[] } {
  const progress = loadProgress();
  // 本番形式：出題は元の演習と同じで、答え方と採点だけが違う
  if (mode.startsWith("exam:") && examable(mode.slice(5))) {
    const base = pick(c, mode.slice(5), prev);
    const year = /^exam:shi:year:(\d{4})$/.exec(mode)?.[1];
    return { ...base, title: `本番形式　${year ? `${year}年度 共通テスト` : "総合演習"}` };
  }
  if (mode === "retry" && prev) {
    const wrong = new Set(prev.answers.filter((a) => !a.correct).map((a) => a.qid));
    return { title: "間違えた問題をもう一度", gate: prev.gate, qs: shuffle(c.data.questions.filter((q) => wrong.has(q.id))) };
  }
  if (mode === "weak") return { title: "苦手帳", gate: "all", qs: shuffle(c.data.questions.filter((q) => isWeak(progress[q.id]))) };
  if (mode === "review") return { title: "温習", gate: "all", qs: reviewQuestions(c) };
  // 四の門は出す順に意味がある（共テの並び・問の順）ので、並べかえない
  if (mode === "shi:mix") return { title: "総合演習10問", gate: "shi", qs: mixQuestions(c) };
  if (mode === "shi:kaeriten") return { title: "返り点の四択", gate: "shi", qs: kaeritenQuestions(c) };
  if (mode === "shi:exam") return { title: "共通テストの設問", gate: "shi", qs: examQuestions(c) };
  if (mode.startsWith("shi:year:")) {
    const year = Number(mode.slice(9));
    return { title: `${year}年度 共通テスト`, gate: "shi", qs: examQuestions(c, year) };
  }

  const gate: Gate = mode.startsWith("go:") || mode.startsWith("vcat:") ? "go"
    : mode.startsWith("ku:") || mode.startsWith("cat:") ? "ku"
    : mode.startsWith("jo:") || mode.startsWith("jcat:") ? "jo"
    : mode.startsWith("shi:") ? "shi" : "ji";
  const all = c.data.questions.filter((q) => gateOf(q) === gate);
  const sub = mode.replace(/^(go|ku|ji|shi|jo):/, "");
  if (sub.startsWith("poem:")) {
    const k = c.data.kanshi.get(sub.slice(5));
    if (k) return { title: `「${k.title}」`, gate, qs: shuffle(questionsOfPoem(c, k.id)) };
  }
  if (sub === "all") return { title: "全問", gate, qs: shuffle(all) };
  if (sub === "weak") return { title: "苦手だけ", gate, qs: shuffle(all.filter((q) => isWeak(progress[q.id]))) };
  if (sub === "review") return { title: "温習", gate, qs: reviewQuestions(c, gate) };
  // 共通テストの本文で解く設問（共テの設問と、共テの本文をもとに作った設問）
  if (sub === "exam") return { title: "共通テストの本文", gate, qs: shuffle(all.filter((q) => c.data.examples.get(q.exampleId)?.source.kind === "exam")) };
  if (sub === "kakikudashi" || sub === "kaishaku") {
    return { title: sub === "kakikudashi" ? "書き下し四択" : "解釈四択", gate, qs: shuffle(all.filter((q) => q.type === sub)) };
  }
  if (sub.startsWith("group:")) {
    const g = c.data.groups.find((x) => x.id === sub.slice(6));
    if (g) return { title: `「${g.title}」の束`, gate, qs: shuffle(questionsOfGroup(c, g)) };
  }
  if (sub === "who") return { title: "出典・作者を当てる", gate, qs: shuffle(all.filter((q) => q.hideWork)) };
  if (sub.startsWith("jcat:")) {
    const cat = sub.slice(5);
    if (JO_CAT_LABEL[cat]) return { title: `常識「${JO_CAT_LABEL[cat]}」`, gate, qs: shuffle(questionsOfJoshikiCat(c, cat)) };
  }
  if (sub.startsWith("vcat:")) {
    const cat = sub.slice(5);
    if (GO_CAT_LABEL[cat]) return { title: GO_CAT_LABEL[cat], gate, qs: shuffle(questionsOfVocabCat(c, cat)) };
  }
  if (sub.startsWith("cat:")) {
    const cat = sub.slice(4);
    if (KU_CAT_LABEL[cat]) return { title: KU_CAT_LABEL[cat], gate, qs: shuffle(questionsOfCat(c, cat)) };
  }
  // おまかせ：未解答 → 苦手 → 残り の順に、それぞれの中は順不同で並べて先頭から10問
  const fresh = all.filter((q) => !progress[q.id]?.seen);
  const weak = all.filter((q) => progress[q.id]?.seen && isWeak(progress[q.id]));
  const rest = all.filter((q) => progress[q.id]?.seen && !isWeak(progress[q.id]));
  return { title: gate === "shi" ? "漢詩の問題10問" : "おまかせ10問", gate, qs: [...shuffle(fresh), ...shuffle(weak), ...shuffle(rest)].slice(0, RANDOM_N) };
}

export const quiz = {
  session: null as Session | null,

  start(c: Ctx, mode: string): void {
    const { title, gate, qs } = pick(c, mode, this.session);
    this.session = {
      mode,
      gate,
      title,
      ids: qs.map((q) => q.id),
      orders: qs.map((q) => shuffle(q.choices.map((_, i) => i))),
      index: 0,
      answers: [],
      finished: qs.length === 0,
      exam: mode.startsWith("exam:") && qs.length
        ? { limitSec: examLimitSec(mode, qs.length), startedAt: Date.now(), endedAt: null, picks: qs.map(() => null), confirming: false, last: loadMeta().examLog[mode] ?? null }
        : undefined,
    };
    c.stages.clear();
  },

  reset(): void {
    this.session = null;
  },

  current(c: Ctx): Question | null {
    const s = this.session;
    if (!s || s.finished) return null;
    return c.data.questions.find((q) => q.id === s.ids[s.index]) ?? null;
  },

  /** 今の問題の判定を出したか（本番形式は採点するまで判定しない） */
  answered(): boolean {
    const s = this.session;
    return !!s && !s.exam && s.answers.length > s.index;
  },

  answer(c: Ctx, shown: number): void {
    const s = this.session;
    const q = this.current(c);
    if (!s || !q || this.answered()) return;
    const chosen = s.orders[s.index][shown];
    if (chosen == null) return;
    // 本番形式は選んだ答えを覚えるだけ（選び直せる）。記録は採点のときに付ける
    if (s.exam) { s.exam.picks[s.index] = chosen; s.exam.confirming = false; return; }
    const correct = chosen === q.answer;
    s.answers.push({ qid: q.id, chosen, correct });
    recordAnswer([q.id, ...q.refs], correct);
    writeStats(learningItemIds());
  },

  /** 本番形式で、i 問目へ移る */
  move(c: Ctx, go: (screen: Screen, arg?: string, opts?: GoOptions) => void, i: number): void {
    const s = this.session;
    if (!s?.exam || s.finished || i < 0 || i >= s.ids.length) return;
    s.index = i;
    s.exam.confirming = false;
    c.stages.clear();
    go("quiz", s.mode, { replace: true, keep: true });
  },

  /** 本番形式の経過時間（秒）。採点したあとは、かかった時間 */
  elapsedSec(now = Date.now()): number {
    const x = this.session?.exam;
    return x ? Math.floor(((x.endedAt ?? now) - x.startedAt) / 1000) : 0;
  },

  /** 本番形式の採点。未解答があれば、force でないかぎり確かめの案内を出して false を返す。
      答えた問題だけを学習記録（温習・苦手帳）に入れる。未解答は不正解として数えるが、記録には入れない */
  grade(c: Ctx, go: (screen: Screen, arg?: string, opts?: GoOptions) => void, force = false): boolean {
    const s = this.session;
    if (!s?.exam || s.finished) return false;
    const x = s.exam;
    if (!force && x.picks.some((p) => p == null)) { x.confirming = true; return false; }
    const now = new Date();
    s.answers = s.ids.map((qid, i) => {
      const q = c.data.questions.find((y) => y.id === qid)!;
      const chosen = x.picks[i];
      if (chosen == null) return { qid, chosen: -1, correct: false, skipped: true };
      const correct = chosen === q.answer;
      recordAnswer([q.id, ...q.refs], correct, now);
      return { qid, chosen, correct };
    });
    writeStats(learningItemIds());
    x.endedAt = now.getTime();
    x.confirming = false;
    s.finished = true;
    s.index = 0;
    const log: ExamLog = { date: localDate(now), ok: s.answers.filter((a) => a.correct).length, n: s.ids.length, sec: this.elapsedSec(now.getTime()) };
    saveMeta({ examLog: { ...loadMeta().examLog, [s.mode]: log } });
    go("result", undefined, { replace: true });
    return true;
  },

  next(c: Ctx, go: (screen: Screen, arg?: string, opts?: GoOptions) => void): void {
    const s = this.session;
    if (s?.exam && !s.finished) { this.move(c, go, s.index + 1); return; }
    if (!s || !this.answered()) return;
    if (s.index + 1 < s.ids.length) {
      s.index += 1;
      c.stages.clear();
      go("quiz", s.mode, { replace: true, keep: true });
    } else {
      s.finished = true;
      go("result", undefined, { replace: true });
    }
  },

  /** 解説の例文カード（段の切り替え用）。演習の画面と、本番形式の解説の画面で使う */
  viewFor(c: Ctx, key: string): ExampleView | undefined {
    const s = this.session;
    const id = key.startsWith("q/") ? key.slice(2) : "";
    if (!s || !s.ids.includes(id)) return undefined;
    const q = c.data.questions.find((x) => x.id === id);
    if (!q || !c.data.examples.get(q.exampleId)) return undefined;
    return answeredView(c, q, key);
  },
};

/** 漢詩の設問なら、その詩（学習項目） */
function poemOf(c: Ctx, q: Question) {
  return q.refs.map((r) => c.data.kanshi.get(r)).find((k) => !!k);
}

/** 答えたあとの例文カード。傍線部（空欄）を朱にし、漢詩（句の解釈を含む）は韻字を丸で囲む */
function answeredView(c: Ctx, q: Question, key: string): ExampleView {
  const e = c.data.examples.get(q.exampleId)!;
  return {
    key, example: e, stage: c.stages.get(key) ?? "kundoku", highlight: q.target,
    bosen: KANSHI_TYPES.includes(q.type) ? undefined : q.target,
    rhyme: poemOf(c, q)?.rhyme.lines,
  };
}

/** 出題中の例文カード。傍線部を伏せる（漢詩の空欄補充は空欄に、形式の設問はそのまま。常識は出典を伏せることがある）。
    出題中は本文の字を押しても字引を開かない（答えの手がかりになるため） */
function askingView(q: Question, key: string, e: ExampleView["example"]): ExampleView {
  if (q.type === "oin" || q.type === "taiku") return { key, example: e, stage: "kundoku", blank: q.target, lookup: false };
  if (q.type === "keishiki") return { key, example: e, stage: "kundoku", lookup: false };
  if (q.type === "joshiki") return { key, example: e, stage: "kundoku", hideWork: q.hideWork, lookup: false };
  return { key, example: e, stage: "kundoku", mask: q.target, maskKeepKaeri: q.type === "kaishaku" || q.type === "imi", bosen: q.target, lookup: false };
}

/** 演習を終えたあとに戻る門（履歴が無いときの戻り先・結果画面の案内に使う） */
export const GATE_HOME: Record<QuizGate, { screen: Screen; arg?: string; label: string }> = {
  go: { screen: "go", arg: "solve", label: "語" },
  ji: { screen: "ji", arg: "solve", label: "字" },
  ku: { screen: "ku", arg: "solve", label: "句" },
  shi: { screen: "shi", label: "試" },
  jo: { screen: "jo", arg: "solve", label: "常識" },
  all: { screen: "home", label: "書斎" },
};

/** 演習の戻り先。四の門の漢詩の演習（shi:random・shi:poem:… など）は漢詩の画面へ、1首の演習はその詩の画面へ */
export function homeOf(s: { mode: string; gate: QuizGate } | null): { screen: Screen; arg?: string; label: string } {
  if (!s) return GATE_HOME.ji;
  if (s.gate === "shi" && s.mode.startsWith("shi:poem:")) return { screen: "shi-poem", arg: s.mode.slice(9), label: "詩" };
  if (s.gate === "shi" && /^shi:(random|all|weak|review)$/.test(s.mode)) return { screen: "shi-kanshi", label: "漢詩" };
  return GATE_HOME[s.gate];
}

const ASK: Record<Question["type"], string> = {
  yomi: "読み方", kakikudashi: "書き下し文", kaishaku: "解釈", imi: "ここでの意味", kaeriten: "返り点の付け方",
  oin: "押韻", taiku: "対句", keishiki: "形式と押韻", joshiki: "常識",
};

function promptOf(q: Question, kundoku: string): string {
  if (q.prompt) return q.prompt;
  const n = q.choices.length;
  if (q.type === "oin" || q.type === "taiku") {
    const t = markText(kundoku, q.target);
    return `空欄[${q.target}]に入る${t.length > 1 ? "語" : "字"}として最も適当なものを、次の①〜${circled(n - 1)}のうちから一つ選べ。`;
  }
  if (q.type === "keishiki") return `この詩の形式と押韻の説明として最も適当なものを、次の①〜${circled(n - 1)}のうちから一つ選べ。`;
  const t = markText(kundoku, q.target);
  if (q.type === "kaeriten") {
    return `傍線部(${q.target})「${t}」を「${q.reading ?? ""}」と読むとき、返り点の付け方として最も適当なものを、次の①〜${circled(n - 1)}のうちから一つ選べ。`;
  }
  return `傍線部(${q.target})「${t}」の${ASK[q.type]}として最も適当なものを、次の①〜${circled(n - 1)}のうちから一つ選べ。`;
}

export function quizScreen(c: Ctx): string {
  const s = quiz.session;
  const q = quiz.current(c);
  const back = { label: "やめる" };
  if (!s || !q) {
    return `${topBar({ title: s?.title ?? "演習", back }, c.meta)}<p class="kb-empty">出題できる問題がありません。</p>`;
  }
  if (s.exam) return examQuizScreen(c, s, q);
  const e = c.data.examples.get(q.exampleId)!;
  const done = quiz.answered();
  const ans = done ? s.answers[s.index] : null;
  const order = s.orders[s.index];

  // 出題中は傍線部を伏せ、答えたら伏せを外して正答の傍線部を朱にする
  const view: ExampleView = done ? answeredView(c, q, `q/${q.id}`) : askingView(q, `q/${q.id}`, e);

  const nextLabel = s.index + 1 < s.ids.length ? "次の問題へ" : "結果を見る";
  const judge = done && ans
    ? `${judgeHTML(q, order, ans, `<button type="button" class="kb-btn kb-primary kb-judge-next" data-kb-act="next">${nextLabel}</button>`)}
      ${explainHTML(c, q, order)}
      <div class="kb-actions"><button type="button" class="kb-btn kb-primary" data-kb-act="next">${nextLabel}</button></div>`
    : "";

  return `${topBar({ title: s.title, back }, c.meta)}
    <div class="kb-progress" aria-label="${s.index + 1}問目／全${s.ids.length}問"><span class="kb-progress-num">${s.index + 1}<small> / ${s.ids.length}</small></span><span class="kb-meter"><i style="width:${Math.round((s.index / s.ids.length) * 100)}%"></i></span></div>
    ${examTagHTML(q)}
    <p class="kb-prompt">${esc(promptOf(q, e.kundoku))}</p>
    ${exampleCard(view, c.meta, { stages: done })}
    <ol class="kb-choices">${choicesHTML(q, order, done ? ans : null)}</ol>
    ${judge}`;
}

function examTagHTML(q: Question): string {
  return q.source.kind === "exam" ? `<p class="kb-examtag">共通テスト　${esc((q.source.label ?? "").replace(/^\d+年度 大学入学共通テスト /, ""))}</p>` : "";
}

/** 選択肢のボタン。ans を渡すと答えたあとの形（正答を朱、選んだ誤答を墨で消す。押せない）。picked は本番形式で選んでいる答え */
function choicesHTML(q: Question, order: number[], ans: Answer | null, picked: number | null = null): string {
  return order.map((orig, shown) => {
    const cls = ["kb-choice"];
    if (q.type === "kaishaku" || q.type === "imi" || q.type === "keishiki" || (q.type === "joshiki" && !q.hideWork)) cls.push("kb-choice-long");
    if (q.type === "kaeriten") cls.push("kb-choice-kaeri");
    if (ans && orig === q.answer) cls.push("is-answer");
    if (ans && orig === ans.chosen && !ans.correct) cls.push("is-wrong");
    if (!ans && orig === picked) cls.push("is-picked");
    const pressed = ans ? "" : ` aria-pressed="${orig === picked}"`;
    return `<li><button type="button" class="${cls.join(" ")}" data-kb-choice="${shown}"${pressed} ${ans ? "disabled" : ""}>
      <span class="kb-choice-no">${circled(shown)}</span><span class="kb-choice-text">${choiceHTML(q, orig)}</span>
    </button></li>`;
  }).join("");
}

/** 判定の帯（朱印「正」／墨の「×」／本番形式で答えなかった問題は「未解答」） */
function judgeHTML(q: Question, order: number[], ans: Answer, tail = ""): string {
  const cls = ans.correct ? "is-ok" : "is-ng";
  const label = ans.correct ? "正解" : ans.skipped ? "未解答" : "不正解";
  return `<div class="kb-judge ${cls}" role="status">
    <span class="kb-stamp ${ans.correct ? "kb-stamp-ok" : "kb-stamp-ng"}" aria-hidden="true">${ans.correct ? "正" : ans.skipped ? "−" : "×"}</span>
    <div class="kb-judge-text"><b>${label}</b><span>正答は ${circled(order.indexOf(q.answer))}${q.type === "kaeriten" || q.type === "keishiki" || (q.type === "joshiki" && !q.hideWork) ? "" : `「${esc(q.choices[q.answer])}」`}</span></div>
    ${tail}
  </div>`;
}

/** 解説：設問の解説、選択肢1つずつの説明、つながる学習項目、出典 */
function explainHTML(c: Ctx, q: Question, order: number[]): string {
  const e = c.data.examples.get(q.exampleId)!;
  return `<section class="kb-explain">
    <h3>解説</h3>
    <p>${esc(q.explanation)}</p>
    <ol class="kb-notes">${order.map((orig, shown) => `<li class="${orig === q.answer ? "is-answer" : ""}"><span class="kb-choice-no">${circled(shown)}</span><span>${q.type === "kaeriten" ? choiceHTML(q, orig) : `<b>${esc(q.choices[orig])}</b>　`}${esc(q.choiceNotes[orig])}</span></li>`).join("")}</ol>
    ${refsHTML(c, q)}
    ${q.source.kind === "exam" ? `<p class="kb-source">設問：${esc(q.source.label ?? "")}（正解は大学入試センターの公表による。選択肢の説明は本アプリで作成）</p>` : ""}
    <p class="kb-source">${sourceNote(e)}</p>
  </section>`;
}

/** 本番形式の出題。判定は出さず、問題の一覧・前後の移動・時間・「採点する」を置く */
function examQuizScreen(c: Ctx, s: Session, q: Question): string {
  const x = s.exam!;
  const e = c.data.examples.get(q.exampleId)!;
  const n = s.ids.length;
  const blanks = x.picks.map((p, i) => (p == null ? i : -1)).filter((i) => i >= 0);
  const sec = quiz.elapsedSec();
  const map = s.ids.map((_, i) => {
    const cls = ["kb-exammap-no"];
    if (i === s.index) cls.push("is-now");
    if (x.picks[i] != null) cls.push("is-picked");
    return `<button type="button" class="${cls.join(" ")}" data-kb-exam-go="${i}" aria-label="${i + 1}問目（${x.picks[i] != null ? "解答済み" : "未解答"}）"${i === s.index ? ' aria-current="step"' : ""}>${i + 1}</button>`;
  }).join("");
  const last = s.index + 1 === n;
  const confirm = x.confirming && blanks.length
    ? `<div class="kb-examconfirm" role="alert">
        <p>未解答が ${blanks.length} 問あります（${blanks.map((i) => `${i + 1}`).join("・")}問目）。未解答は不正解として数えます。学習記録には、答えた問題だけを入れます。</p>
        <div class="kb-actions">
          <button type="button" class="kb-btn kb-primary" data-kb-act="grade-force">このまま採点する</button>
          <button type="button" class="kb-btn" data-kb-exam-go="${blanks[0]}">未解答の問題へ</button>
        </div>
      </div>`
    : "";
  return `${topBar({ title: s.title, back: { label: "やめる" } }, c.meta)}
    <div class="kb-progress kb-examhead" aria-label="${s.index + 1}問目／全${n}問">
      <span class="kb-progress-num">${s.index + 1}<small> / ${n}</small></span>
      <span class="kb-timer${sec > x.limitSec ? " is-over" : ""}" data-kb-timer role="timer" aria-label="経過時間">${clock(sec)}</span>
      <span class="kb-timer-limit">目安 ${clock(x.limitSec)}</span>
    </div>
    <nav class="kb-exammap" aria-label="問題の一覧（押すとその問題へ）">${map}</nav>
    ${examTagHTML(q)}
    <p class="kb-prompt">${esc(promptOf(q, e.kundoku))}</p>
    ${exampleCard(askingView(q, `q/${q.id}`, e), c.meta, { stages: false })}
    <ol class="kb-choices">${choicesHTML(q, s.orders[s.index], null, x.picks[s.index])}</ol>
    <div class="kb-actions kb-examnav">
      <button type="button" class="kb-btn" data-kb-act="prev"${s.index === 0 ? " disabled" : ""}>← 前の問題</button>
      ${last
        ? `<button type="button" class="kb-btn kb-primary" data-kb-act="grade">採点する</button>`
        : `<button type="button" class="kb-btn kb-primary" data-kb-act="next">次の問題 →</button>`}
    </div>
    ${last ? "" : `<div class="kb-actions"><button type="button" class="kb-btn kb-ghost" data-kb-act="grade">ここで採点する（解答済み ${n - blanks.length} / ${n}）</button></div>`}
    ${confirm}`;
}

/** 本番形式の採点のあと、1問ずつの解説。arg は何問目か（0から） */
export function kaisetsuScreen(c: Ctx): string {
  const s = quiz.session;
  const i = Number(c.arg ?? 0);
  const ans = s?.finished ? s.answers[i] : undefined;
  const q = ans ? c.data.questions.find((x) => x.id === ans.qid) : undefined;
  if (!s || !ans || !q) return `${topBar({ title: "解説", back: { label: "結果" } }, c.meta)}<p class="kb-empty">解説できる問題がありません。</p>`;
  const e = c.data.examples.get(q.exampleId)!;
  const order = s.orders[i];
  const n = s.answers.length;
  const step = (j: number, label: string) => j >= 0 && j < n
    ? `<button type="button" class="kb-btn" data-kb-go="kaisetsu" data-kb-arg="${j}" data-kb-replace="1">${label}</button>`
    : `<button type="button" class="kb-btn" disabled>${label}</button>`;
  return `${topBar({ title: `解説　${i + 1} / ${n}`, back: { label: "結果" } }, c.meta)}
    ${examTagHTML(q)}
    <p class="kb-prompt">${esc(promptOf(q, e.kundoku))}</p>
    ${exampleCard(answeredView(c, q, `q/${q.id}`), c.meta)}
    <ol class="kb-choices">${choicesHTML(q, order, ans)}</ol>
    ${judgeHTML(q, order, ans)}
    ${explainHTML(c, q, order)}
    <div class="kb-actions kb-examnav">${step(i - 1, "← 前の問題")}${step(i + 1, "次の問題 →")}</div>
    <div class="kb-actions"><button type="button" class="kb-btn kb-ghost" data-kb-act="back">結果へ戻る</button></div>`;
}

/** 選択肢の中身。返り点の四択は、返り点だけを付けた白文を横書きで描く */
function choiceHTML(q: Question, i: number): string {
  if (q.type !== "kaeriten") return esc(q.choices[i]);
  return `<span class="kb-text kb-h kb-kaeritext">${kundokuHTML(q.choices[i])}</span>`;
}

function refsHTML(c: Ctx, q: Question): string {
  const rows = q.refs.map((id) => {
    const v = c.data.vocab.get(id);
    if (v) return `<p><span class="kb-refs-kanji">${esc(v.word)}</span><b>${esc(v.yomi)}</b>　${esc(v.meanings.join("／"))}</p>`;
    const u = c.data.usages.get(id);
    if (u) return `<p><span class="kb-refs-kanji">${esc(u.kanji)}</span><b>${esc(u.yomi)}</b>　${esc(u.gloss)}</p>`;
    const k = c.data.kukei.get(id);
    if (k) return `<p><span class="kb-refs-kanji">${esc(k.name)}</span><b>${rubyTextHTML(k.kakikudashi)}</b>　${esc(k.meaning)}</p>`;
    const s = c.data.kanshi.get(id);
    const j = c.data.joshiki.get(id);
    if (j) return `<p><span class="kb-refs-kanji kb-refs-name">${esc(j.name)}</span><b>${esc(j.yomi)}${j.era ? `・${esc(j.era)}` : ""}</b>　${esc(j.summary)}<button type="button" class="kb-btn kb-ghost kb-refs-jump" data-kb-jump="${esc(j.id)}">カードを開く</button></p>`;
    if (s) return `<p><span class="kb-refs-kanji">${esc(s.title)}</span><b>${esc(s.poet)}・${KANSHI_FORM_NAME[s.form]}</b>　押韻 ${esc(rhymeText(c, s).withYomi)}（韻「${esc(s.rhyme.sound)}」）<button type="button" class="kb-btn kb-ghost kb-refs-jump" data-kb-jump="${esc(s.id)}">詩を読む</button></p>`;
    return "";
  }).filter(Boolean);
  if (!rows.length) return "";
  return `<div class="kb-refs">${rows.join("")}</div>`;
}

/** 結果画面の「もう一度」。温習は今日の分が残っていればつづきを、苦手帳は残りを、門の演習はおまかせを、四の門は総合演習を */
function againOf(s: Session): { mode: string; label: string } | null {
  if (s.gate === "shi") {
    if (s.mode.startsWith("exam:")) return { mode: s.mode, label: s.mode === "exam:shi:mix" ? "本番形式の総合演習をもう一度" : "本番形式でもう一度" };
    if (s.mode === "shi:mix") return { mode: "shi:mix", label: "総合演習をもう一度" };
    if (s.mode === "shi:kaeriten") return { mode: "shi:kaeriten", label: "返り点の四択をもう一度" };
    if (s.mode === "shi:random") return { mode: "shi:random", label: "漢詩の問題をもう一度" };
    if (s.mode !== "shi:review" && s.mode !== "shi:weak") return null;
  }
  if (s.mode === "review" || s.mode.endsWith(":review")) {
    const rest = dueItems(s.gate === "all" ? undefined : s.gate).length;
    return rest ? { mode: s.mode, label: `温習のつづき（残り ${rest} 項目）` } : null;
  }
  if (s.mode === "weak") return { mode: "weak", label: "苦手帳をもう一度" };
  if (s.gate === "all") return null;
  return { mode: s.gate === "ji" ? "random" : `${s.gate}:random`, label: "おまかせ10問をもう一度" };
}

export function resultScreen(c: Ctx): string {
  const s = quiz.session;
  if (!s) return `${topBar({ title: "結果", back: { label: "書斎" } }, c.meta)}`;
  const home = homeOf(s);
  const again = againOf(s);
  const ok = s.answers.filter((a) => a.correct).length;
  const n = s.answers.length;
  const wrong = n - ok;
  const skipped = s.answers.filter((a) => a.skipped).length;
  const rows = s.answers.map((a, i) => {
    const q = c.data.questions.find((x) => x.id === a.qid)!;
    const e = c.data.examples.get(q.exampleId)!;
    const cls = a.correct ? "is-ok" : a.skipped ? "is-ng is-skip" : "is-ng";
    const label = a.correct ? "正解" : a.skipped ? "未解答" : "不正解";
    // 本番形式は、行から1問ずつの解説を開く（演習中に解説を出していないため）
    const open = s.exam ? `<button type="button" class="kb-btn kb-ghost kb-res-open" data-kb-go="kaisetsu" data-kb-arg="${i}">解説</button>` : "";
    return `<li class="${cls}"><span class="kb-mark" aria-label="${label}">${a.correct ? "○" : a.skipped ? "−" : "×"}</span>
      <span class="kb-res-target">${esc(targetText(q, e))}</span><span class="kb-res-yomi">${esc(answerText(q))}</span><span class="kb-res-work">${esc(e.work)}　${ASK[q.type]}${a.skipped ? "　（未解答）" : ""}</span>${open}</li>`;
  }).join("");
  return `${topBar({ title: "結果", back: { label: home.label } }, c.meta)}
    <section class="kb-result">
      <p class="kb-result-title">${esc(s.title)}</p>
      <p class="kb-result-score"><b>${ok}</b><small> / ${n} 問正解</small></p>
      ${ok === n && n > 0 ? `<span class="kb-stamp kb-stamp-ok kb-stamp-big" aria-hidden="true">正</span>` : ""}
      ${s.exam ? examTimeHTML(s.exam, skipped) : ""}
    </section>
    <ol class="kb-reslist${s.exam ? " is-exam" : ""}">${rows}</ol>
    <div class="kb-actions">
      ${wrong ? `<button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="retry" data-kb-replace="1">${skipped ? "間違えた・答えなかった" : "間違えた"}${wrong}問をもう一度</button>` : ""}
      ${again ? `<button type="button" class="kb-btn${wrong ? "" : " kb-primary"}" data-kb-go="quiz" data-kb-arg="${again.mode}" data-kb-replace="1">${again.label}</button>` : ""}
      <button type="button" class="kb-btn kb-ghost" data-kb-act="back">${s.gate === "all" ? "書斎へ戻る" : home.screen === "shi-kanshi" ? "漢詩へ戻る" : home.screen === "shi-poem" ? "詩へ戻る" : s.gate === "jo" ? "常識へ戻る" : `${home.label}の門へ戻る`}</button>
    </div>`;
}

/** 本番形式の結果に添える、かかった時間と目安・前回との比べ */
function examTimeHTML(x: ExamState, skipped: number): string {
  const sec = x.endedAt != null ? Math.floor((x.endedAt - x.startedAt) / 1000) : 0;
  const over = sec - x.limitSec;
  const judge = over > 0 ? `目安を ${clock(over)} 超えました` : "目安の時間内";
  const last = x.last ? `<p class="kb-result-last">前回（${esc(x.last.date)}）${x.last.ok} / ${x.last.n} 問・${clock(x.last.sec)}</p>` : "";
  return `<p class="kb-result-time${over > 0 ? " is-over" : ""}">かかった時間 <b>${clock(sec)}</b>　目安 ${clock(x.limitSec)}（${judge}）</p>
    ${skipped ? `<p class="kb-result-last">未解答 ${skipped} 問（不正解として数えました）</p>` : ""}
    ${last}`;
}
