/* 四の門「試」の漢詩。docs/kanbun/設計.md 7章 Phase 6 その4・その7
   - 学ぶ：漢詩の決まり（形式・押韻・対句・構成）と、1首ごとの本文（韻字を丸で囲む）・押韻・対句・要点
   - 解く：押韻の空欄（oin）・対句の空欄（taiku）・形式と押韻（keishiki）・句の解釈（kaishaku）。学習項目は1首ごと（kb-s-）
   - 長い詩（長恨歌）は一節ごとに1項目（excerpt）。換韻する一節は、韻の組（rhyme.groups）ごとに押韻を示す */
import type { Ctx } from "../index";
import type { Kanshi, KanshiForm, Question } from "../schema";
import { KANSHI_FORM_NAME, KANSHI_FORMS } from "../schema";
import { gateOf } from "../data";
import { hakubun, poemLines } from "../markup";
import { isWeak, loadProgress } from "../store";
import { esc, exampleCard, topBar, type ExampleView } from "../ui";
import { dueItems, REVIEW_N } from "./review";

const NUM = "一二三四五六七八九十";
/** 句の番号（1 → 第一句） */
export function lineName(n: number): string {
  return `第${NUM[n - 1] ?? n}句`;
}

const FORM_LEAD: Record<KanshiForm, string> = {
  gozetsu: "一句五字・四句。起・承・転・結で組み立てる。",
  shichizetsu: "一句七字・四句。第一句末も押韻するのが原則。",
  goritsu: "一句五字・八句。第三・四句と第五・六句を対句にする。",
  shichiritsu: "一句七字・八句。第一句末も押韻するのが原則で、中の二聯を対句にする。",
  goko: "句数に決まりが無い古い形の詩（古体詩）。偶数句末で押韻し、途中で韻を換えることもある。",
  shichiko: "一句七字で句数に決まりが無い。長い詩は、場面の区切りで韻を換えながら進む（換韻）。長い詩は一節を載せる。",
};

/** 漢詩の決まり（学ぶ側の短い説明） */
const RULES: Array<{ name: string; text: string }> = [
  { name: "押韻", text: "偶数句の句末で韻をふむ。七言詩は第一句末もふむのが原則（五言詩でも第一句末でふむことがあり、七言詩でふまないこともある）。韻は、句末の字の音読みから頭の子音を除いた響き（深シン・心シン・金キン → イン）で見当をつける。呉音で読むとずれる字は、漢音で合うことが多い（城ジョウ → セイ、情ジョウ → セイ）。古詩では、途中で韻を換えることがある（換韻）。韻を換えた最初の句は、奇数句でも押韻する。" },
  { name: "対句", text: "並んだ二句で、同じ位置に同じ種類の語（数と数、色と色、自然の景物どうし、動詞と動詞）が来て、組み立てがそろったもの。律詩は第三・四句（頷聯）と第五・六句（頸聯）を対句にする決まりがある。空欄補充では、向き合う句の同じ位置の語が手がかりになる。" },
  { name: "構成", text: "絶句は 起（うたい起こす）・承（受けて展開する）・転（場面や視点を転じる）・結（まとめる）。律詩は二句ずつ 首聯・頷聯・頸聯・尾聯 と呼ぶ。" },
];

export function poemsOfForm(c: Ctx, form: KanshiForm): Kanshi[] {
  return [...c.data.kanshi.values()].filter((k) => k.form === form);
}

/** その詩の設問 */
export function questionsOfPoem(c: Ctx, id: string): Question[] {
  return c.data.questions.filter((q) => q.refs.includes(id));
}

/** 句末の字（句ごと）。本文の各句の白文の最後の字 */
export function lineEnds(c: Ctx, k: Kanshi): string[] {
  const e = c.data.examples.get(k.exampleId);
  if (!e) return [];
  return poemLines(e.kundoku).map((l) => {
    const w = [...hakubun(l)].filter((ch) => /\p{Script=Han}/u.test(ch));
    return w[w.length - 1] ?? "";
  });
}

/** 韻字の並び（「深」「心」…）と、音読みつきの並び（深（シン）・心（シン）…）。lines を渡すとその句だけ */
export function rhymeText(c: Ctx, k: Kanshi, lines = k.rhyme.lines): { chars: string; withYomi: string } {
  const ends = lineEnds(c, k);
  // 漢音を括弧に添えた「ジョウ（セイ）」は「ジョウ、漢音セイ」と出す
  const xs = lines.map((n) => ({ ch: ends[n - 1], yomi: k.ends[n - 1].replace(/（(.*)）/, "、漢音$1") }));
  return { chars: xs.map((x) => x.ch).join("・"), withYomi: xs.map((x) => `${x.ch}（${x.yomi}）`).join("・") };
}

/** 1〜999 の漢数字（百二十） */
function kansuji(n: number): string {
  const h = Math.floor(n / 100), t = Math.floor((n % 100) / 10), o = n % 10;
  return `${h ? `${h > 1 ? NUM[h - 1] : ""}百` : ""}${t ? `${t > 1 ? NUM[t - 1] : ""}十` : ""}${o ? NUM[o - 1] : ""}`;
}

/** 長い詩の一節なら「第九〜十六句（全百二十句）の一節」 */
export function excerptText(k: Kanshi): string {
  const x = k.excerpt;
  return x ? `第${kansuji(x.from)}〜${kansuji(x.to)}句（全${kansuji(x.total)}句）の一節` : "";
}

/** 1首の画面の本文カード。段の切り替えのたびに引き直す */
export function poemViews(c: Ctx): Map<string, ExampleView> {
  const out = new Map<string, ExampleView>();
  const k = c.data.kanshi.get(c.arg ?? "");
  const e = k && c.data.examples.get(k.exampleId);
  if (!k || !e) return out;
  const key = `poem/${k.id}`;
  out.set(key, { key, example: e, stage: c.stages.get(key) ?? "kundoku", rhyme: k.rhyme.lines });
  return out;
}

export function kanshiScreen(c: Ctx): string {
  const progress = loadProgress();
  const qs = c.data.questions.filter((q) => gateOf(q) === "shi");
  const weak = qs.filter((q) => isWeak(progress[q.id])).length;
  const fresh = qs.filter((q) => !(progress[q.id]?.seen)).length;
  const due = dueItems("shi").length;
  const rules = RULES.map((r) => `<div class="kb-kaerirule"><span class="kb-kaerirule-name">${esc(r.name)}</span><span class="kb-kaerirule-text">${esc(r.text)}</span></div>`).join("");
  const formTable = `<table class="kb-table kb-formtable">
    <thead><tr><th scope="col"></th><th scope="col">五言<small>一句五字</small></th><th scope="col">七言<small>一句七字</small></th></tr></thead>
    <tbody>
      <tr><th scope="row">絶句<small>四句</small></th><td>五言絶句</td><td>七言絶句</td></tr>
      <tr><th scope="row">律詩<small>八句</small></th><td>五言律詩</td><td>七言律詩</td></tr>
      <tr><th scope="row">古詩<small>句数は自由</small></th><td>五言古詩</td><td>七言古詩</td></tr>
    </tbody>
  </table>`;

  const sections = KANSHI_FORMS.map((form) => {
    const ks = poemsOfForm(c, form);
    if (!ks.length) return "";
    const cards = ks.map((k) => {
      const done = (progress[k.id]?.seen ?? 0) > 0;
      return `<button type="button" class="kb-group kb-poemcard" data-kb-go="shi-poem" data-kb-arg="${esc(k.id)}">
        <span class="kb-group-title">${esc(k.title)}</span>
        <span class="kb-poemcard-poet">${esc(k.poet)}</span>
        <span class="kb-group-chars">韻 ${esc(rhymeText(c, k).chars)}</span>
        <span class="kb-group-meta">${k.excerpt ? "一節 ・ " : ""}${questionsOfPoem(c, k.id).length}問${done ? " ・ 学習済" : ""}</span>
      </button>`;
    }).join("");
    return `<section class="kb-sec"><h3 class="kb-sec-title">${KANSHI_FORM_NAME[form]}<small>${esc(FORM_LEAD[form])}</small></h3><div class="kb-groups">${cards}</div></section>`;
  }).join("");

  return `${topBar({ title: "漢詩", back: { label: "試" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">四の門</span><h2>漢詩<small>形式・押韻・対句</small></h2></header>
    <section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="shi:random"><b>漢詩の問題10問</b><small>押韻の空欄・対句の空欄・形式と押韻・句の解釈。まだ解いていない問題と、間違えた問題から先に（未解答 ${fresh}問）</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="shi:review" ${due ? "" : "disabled"}><b>今日の復習</b><small>${due ? `忘れかけた ${due} 首（1回に ${REVIEW_N} 問まで）` : "今日の分はありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="shi:weak" ${weak ? "" : "disabled"}><b>苦手だけ</b><small>${weak ? `間違えたままの ${weak}問` : "まだありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="shi:all"><b>全問</b><small>${qs.length}問を順不同で</small></button>
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">漢詩の決まり<small>一句の字数と句数で形式が決まる。押韻と対句は、空欄補充の手がかりになる。</small></h3>
      ${formTable}
      <div class="kb-kaerirules">${rules}</div></section>
    ${sections}
    <p class="kb-foot">詩の原文は維基文庫と照合しました（版によって字句の違う所は、その字を空欄にしていません）。長い詩（長恨歌）は一節ずつ載せています。訓点・書き下し文・現代語訳・解説は本アプリで作成しました。音読みは現代仮名遣いで示しています。</p>`;
}

export function poemScreen(c: Ctx): string {
  const k = c.data.kanshi.get(c.arg ?? "");
  const e = k && c.data.examples.get(k.exampleId);
  if (!k || !e) return `${topBar({ title: "漢詩", back: { label: "漢詩" } }, c.meta)}<p class="kb-empty">この詩は見つかりませんでした。</p>`;
  const view = poemViews(c).get(`poem/${k.id}`)!;
  const lines = poemLines(e.kundoku).map((l) => hakubun(l));
  const rhyme = rhymeText(c, k);
  const n = lines.length;
  const chars = [...lines[0]].length;
  const rhymeRow = k.rhyme.groups
    ? k.rhyme.groups.map((g) => `${g.lines.map(lineName).join("・")}の句末　${esc(rhymeText(c, k, g.lines).withYomi)}　→ 韻は「${esc(g.sound)}」`).join("<br>")
    : `${k.rhyme.lines.map(lineName).join("・")}の句末　${esc(rhyme.withYomi)}　→ 韻は「${esc(k.rhyme.sound)}」`;
  const taiku = k.taiku.map((t) => `<li><span class="kb-taiku-lines">${lineName(t.lines[0])}「${esc(lines[t.lines[0] - 1])}」<br>${lineName(t.lines[1])}「${esc(lines[t.lines[1] - 1])}」</span><span class="kb-taiku-pairs">${esc(t.pairs)}</span></li>`).join("");
  const all = [...c.data.kanshi.values()];
  const i = all.findIndex((x) => x.id === k.id);
  const prev = all[i - 1];
  const next = all[i + 1];
  const qs = questionsOfPoem(c, k.id);

  return `${topBar({ title: `「${k.title}」`, back: { label: "漢詩" } }, c.meta)}
    <header class="kb-grouphead">
      <span class="kb-grouphead-kind">${KANSHI_FORM_NAME[k.form]}</span>
      <h2>${esc(k.title)}</h2>
      <p class="kb-grouphead-chars">${esc(k.poet)}（${esc(k.era)}）${k.excerpt ? `<br><small>${esc(excerptText(k))}</small>` : ""}</p>
    </header>
    ${exampleCard(view, c.meta)}
    <p class="kb-hint"><span class="kb-hint-hl">丸で囲んだ字</span>が韻字（押韻している句末の字）です。</p>
    <dl class="kb-poeminfo">
      <dt>形式</dt><dd>${KANSHI_FORM_NAME[k.form]}（${k.excerpt ? `全${kansuji(k.excerpt.total)}句のうち${NUM[n - 1] ?? n}句を載せる` : `${NUM[n - 1] ?? n}句`}・一句${NUM[chars - 1] ?? chars}字）</dd>
      <dt>押韻</dt><dd>${rhymeRow}${k.rhyme.note ? `<br><small>${esc(k.rhyme.note)}</small>` : ""}</dd>
      <dt>対句</dt><dd>${taiku ? `<ul class="kb-taiku">${taiku}</ul>` : "決まりとしての対句は無い"}${k.excerpt ? `<br><small>句の番号は、載せた一節の中で数えています。</small>` : ""}</dd>
    </dl>
    ${k.points.length ? `<ul class="kb-points">${k.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}
    <div class="kb-actions">
      ${qs.length ? `<button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="shi:poem:${esc(k.id)}">この詩を解く（${qs.length}問）</button>` : ""}
      ${prev ? `<button type="button" class="kb-btn kb-ghost" data-kb-go="shi-poem" data-kb-arg="${esc(prev.id)}" data-kb-replace="1">← ${esc(prev.title)}</button>` : ""}
      ${next ? `<button type="button" class="kb-btn kb-ghost" data-kb-go="shi-poem" data-kb-arg="${esc(next.id)}" data-kb-replace="1">${esc(next.title)} →</button>` : ""}
    </div>`;
}
