/* 一の門「語」。学ぶ＝分類の目次 → 語の一覧と詳細（意味・現代語とのずれ・例文）と暗記カード、
   解く＝語の意味の四択（共通テストの「ここでの意味」の設問を含む）。docs/kanbun/設計.md 5章 */
import type { Ctx } from "../index";
import type { Question, Vocab, VocabCat } from "../schema";
import { VOCAB_CATS } from "../schema";
import { gateOf } from "../data";
import { rubyTextHTML } from "../render";
import { isWeak, loadProgress } from "../store";
import { esc, exampleCard, topBar, type ExampleView } from "../ui";
import { dueItems, REVIEW_N } from "./review";

interface CatInfo { title: string; lead: string }

/** 4分類の見出しと説明（docs/kanbun/網羅表.md 3章の並び） */
export const GO_CATS: Record<VocabCat, CatInfo> = {
  jinbutsu: { title: "人物・身分", lead: "君子・小人・夫子・寡人・百姓など、人を指す語。女（なんぢ）・子・公・臣のような、会話で相手や自分を指す語も含む。" },
  zure: { title: "現代語とずれる語", lead: "大丈夫・故人・人間・走・去など、今の日本語と同じ字でも意味が違う語。共通テストでは現代語の意味が誤答に使われる。" },
  fukushi: { title: "副詞・接続の語", lead: "益・向・稍・良久・於是・雖然など、時間の流れや文と文のつながりを表す語。" },
  sonota: { title: "成語・様子の語", lead: "膾炙・知言・光陰・刎頸之交など、成り立ちごと覚える語と、莞爾・欣欣然のように様子を表す語。" },
};
export const GO_CAT_LABEL: Record<string, string> = Object.fromEntries(VOCAB_CATS.map((k) => [k, GO_CATS[k].title]));

export function vocabOfCat(c: Ctx, cat: string): Vocab[] {
  return [...c.data.vocab.values()].filter((v) => v.cat === cat);
}

/** 分類につながる設問（分類のどれかの語を refs に持つもの） */
export function questionsOfVocabCat(c: Ctx, cat: string): Question[] {
  const ids = new Set(vocabOfCat(c, cat).map((v) => v.id));
  return c.data.questions.filter((q) => q.refs.some((r) => ids.has(r)));
}

/** 共通テストの本文で問う設問（共テの設問と、共テの本文をもとに作った設問） */
function isExamText(c: Ctx, q: Question): boolean {
  return c.data.examples.get(q.exampleId)?.source.kind === "exam";
}

export function goScreen(c: Ctx): string {
  const tab = c.arg === "solve" ? "solve" : "learn";
  const progress = loadProgress();
  const tabs = `<div class="kb-tabs" role="tablist">
    <button type="button" role="tab" class="kb-tab${tab === "learn" ? " is-on" : ""}" aria-selected="${tab === "learn"}" data-kb-go="go" data-kb-arg="learn" data-kb-replace="1"><b>学ぶ</b><small>意味と例文・暗記カード</small></button>
    <button type="button" role="tab" class="kb-tab${tab === "solve" ? " is-on" : ""}" aria-selected="${tab === "solve"}" data-kb-go="go" data-kb-arg="solve" data-kb-replace="1"><b>解く</b><small>傍線部の意味の四択</small></button>
  </div>`;

  const catCard = (cat: VocabCat, solve: boolean) => {
    const vs = vocabOfCat(c, cat);
    const done = vs.filter((v) => (progress[v.id]?.seen ?? 0) > 0).length;
    const qs = questionsOfVocabCat(c, cat);
    const sample = vs.slice(0, 6).map((v) => v.word.replace(/（[^）]*）/g, "")).join("・");
    const target = solve ? `data-kb-go="quiz" data-kb-arg="vcat:${cat}"` : `data-kb-go="go-cat" data-kb-arg="${cat}"`;
    return `<button type="button" class="kb-group" ${target}>
      <span class="kb-group-title">${esc(GO_CATS[cat].title)}</span>
      <span class="kb-group-chars">${esc(sample)}…</span>
      <span class="kb-group-meta">${solve ? `${qs.length}問` : `${vs.length}語`} ・ 学習済 ${done}/${vs.length}</span>
    </button>`;
  };

  let body: string;
  if (tab === "learn") {
    body = `<section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="go-card" data-kb-arg="all"><b>暗記カード</b><small>語を見て意味を思い出し、めくって確かめる（${c.data.vocab.size}語。分類ごとのカードは各分類の画面から）</small></button>
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">重要語<small>分類を選ぶと、意味・現代語とのずれ・例文が並ぶ。</small></h3>
      <div class="kb-groups">${VOCAB_CATS.map((k) => catCard(k, false)).join("")}</div></section>`;
  } else {
    const all = c.data.questions.filter((q) => gateOf(q) === "go");
    const weak = all.filter((q) => isWeak(progress[q.id])).length;
    const due = dueItems("go").length;
    const fresh = all.filter((q) => !(progress[q.id]?.seen)).length;
    const nExam = all.filter((q) => isExamText(c, q)).length;
    body = `<section class="kb-sec"><div class="kb-starts">
      <button type="button" class="kb-start is-main" data-kb-go="quiz" data-kb-arg="go:random"><b>おまかせ10問</b><small>まだ解いていない問題と、間違えた問題から先に出します（未解答 ${fresh}問）</small></button>
      ${nExam ? `<button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="go:exam"><b>共通テストの本文で解く</b><small>共テの「ここでの意味」の設問と、共テの本文から作った設問（${nExam}問）</small></button>` : ""}
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="go:review" ${due ? "" : "disabled"}><b>今日の復習</b><small>${due ? `忘れかけた ${due} 語（1回に ${REVIEW_N} 問まで）` : "今日の分はありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="go:weak" ${weak ? "" : "disabled"}><b>苦手だけ</b><small>${weak ? `間違えたままの ${weak}問` : "まだありません"}</small></button>
      <button type="button" class="kb-start" data-kb-go="quiz" data-kb-arg="go:all"><b>全問</b><small>${all.length}問を順不同で</small></button>
    </div></section>
    <section class="kb-sec"><h3 class="kb-sec-title">分類ごとに解く</h3><div class="kb-groups">${VOCAB_CATS.map((k) => catCard(k, true)).join("")}</div></section>`;
  }
  return `${topBar({ title: "一の門「語」", back: { label: "書斎" } }, c.meta)}
    <header class="kb-gatehead"><span class="kb-gatehead-no">一の門</span><h2>語<small>漢文の重要語</small></h2></header>
    ${tabs}${body}`;
}

/** 分類の画面の例文カード。段の切り替えのたびに引き直す */
export function vocabViews(c: Ctx): Map<string, ExampleView> {
  const out = new Map<string, ExampleView>();
  for (const v of vocabOfCat(c, c.arg ?? "")) {
    for (const eid of v.exampleIds) {
      const e = c.data.examples.get(eid);
      if (!e) continue;
      const key = `${v.id}/${eid}`;
      out.set(key, { key, example: e, stage: c.stages.get(key) ?? "kundoku", highlight: "1" });
    }
  }
  return out;
}

/** 語の意味の並び（1つなら文、2つ以上なら番号つき） */
function meaningsHTML(v: Vocab): string {
  if (v.meanings.length === 1) return `<p class="kb-usage-gloss">${esc(v.meanings[0])}</p>`;
  return `<ol class="kb-meanings">${v.meanings.map((m) => `<li>${esc(m)}</li>`).join("")}</ol>`;
}

function trapHTML(v: Vocab): string {
  return v.modernTrap ? `<p class="kb-trap"><span class="kb-trap-label">現代語とのずれ</span>${esc(v.modernTrap)}</p>` : "";
}

export function goCatScreen(c: Ctx): string {
  const cat = c.arg as VocabCat | undefined;
  const info = cat ? GO_CATS[cat] : undefined;
  const vs = cat ? vocabOfCat(c, cat) : [];
  if (!info || !vs.length) return `${topBar({ title: "一の門「語」", back: { label: "語" } }, c.meta)}<p class="kb-empty">この分類は見つかりませんでした。</p>`;
  const views = vocabViews(c);

  const table = `<table class="kb-table kb-vtable">
    <thead><tr><th scope="col">語</th><th scope="col">読み</th><th scope="col">意味</th></tr></thead>
    <tbody>${vs.map((v) => `<tr><th scope="row" class="kb-table-kanji"><button type="button" class="kb-jump" data-kb-jump="${esc(v.id)}">${esc(v.word)}</button></th><td class="kb-table-yomi">${esc(v.yomi)}</td><td>${esc(v.meanings[0])}</td></tr>`).join("")}</tbody>
  </table>`;

  const cards = vs.map((v) => {
    const exs = v.exampleIds.map((eid) => views.get(`${v.id}/${eid}`)).filter((x): x is ExampleView => !!x);
    return `<article class="kb-usage kb-vocab" id="${esc(v.id)}">
      <header class="kb-usage-head"><span class="kb-usage-kanji">${esc(v.word)}</span><span class="kb-usage-yomi">${esc(v.yomi)}</span><span class="kb-rank" title="頻出度">${v.rank}</span></header>
      ${meaningsHTML(v)}
      ${trapHTML(v)}
      ${v.points.length ? `<ul class="kb-points">${v.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}
      ${exs.map((x) => exampleCard(x, c.meta)).join("")}
    </article>`;
  }).join("");

  const qs = questionsOfVocabCat(c, cat!);
  return `${topBar({ title: `語「${info.title}」`, back: { label: "語" } }, c.meta)}
    <header class="kb-grouphead">
      <span class="kb-grouphead-kind">一の門　重要語</span>
      <h2>${esc(info.title)}</h2>
      <p class="kb-grouphead-lead">${esc(info.lead)}</p>
    </header>
    <div class="kb-actions kb-actions-top"><button type="button" class="kb-btn" data-kb-go="go-card" data-kb-arg="${esc(cat!)}">暗記カードで覚える（${vs.length}語）</button></div>
    ${table}
    <p class="kb-hint">例文の<span class="kb-hint-hl">朱の部分</span>が、その語を使った所です。段のボタンで 白文 → 訓読文 → 書き下し文 → 現代語訳 を切り替えられます。</p>
    ${cards}
    <div class="kb-actions"><button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="vcat:${esc(cat!)}">この分類を解く（${qs.length}問）</button></div>`;
}

/* ---------- 暗記カード ----------
   語を見て意味を思い出し、めくって確かめる。「もう一度」の語は山の後ろへ回し、「覚えた」で次へ。
   学習記録（温習の予定）には入れない（予定は意味の四択の正誤で付ける）。 */

interface Deck {
  /** all か分類 */
  key: string;
  ids: string[];
  index: number;
  flipped: boolean;
  /** 「覚えた」の数と、「もう一度」を押した回数 */
  ok: number;
  again: number;
}

function shuffle<T>(a: T[]): T[] {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}

export const cards = {
  deck: null as Deck | null,

  start(c: Ctx, key: string): void {
    const vs = key === "all" ? [...c.data.vocab.values()] : vocabOfCat(c, key);
    this.deck = { key, ids: shuffle(vs.map((v) => v.id)), index: 0, flipped: false, ok: 0, again: 0 };
  },

  /** 画面の操作。flip＝めくる、ok＝覚えた、again＝もう一度（山の後ろへ） */
  act(action: string): void {
    const d = this.deck;
    if (!d || d.index >= d.ids.length) return;
    if (action === "flip") { d.flipped = !d.flipped; return; }
    if (!d.flipped) return;
    if (action === "again") { d.ids.push(d.ids[d.index]); d.again += 1; }
    else if (action === "ok") d.ok += 1;
    else return;
    d.index += 1;
    d.flipped = false;
  },

  reset(): void {
    this.deck = null;
  },
};

export function cardScreen(c: Ctx): string {
  const d = cards.deck;
  const key = d?.key ?? c.arg ?? "all";
  const title = key === "all" ? "暗記カード" : `暗記カード「${GO_CAT_LABEL[key] ?? ""}」`;
  const head = topBar({ title, back: { label: "語" } }, c.meta);
  if (!d || !d.ids.length) return `${head}<p class="kb-empty">カードがありません。</p>`;

  if (d.index >= d.ids.length) {
    const n = new Set(d.ids).size;
    return `${head}
    <section class="kb-result">
      <p class="kb-result-title">${esc(title)}</p>
      <p class="kb-result-score"><b>${n}</b><small> 語をひととおり見ました</small></p>
      <p class="kb-review-sub">「もう一度」に回した回数 ${d.again}</p>
    </section>
    <div class="kb-actions">
      <button type="button" class="kb-btn kb-primary" data-kb-go="quiz" data-kb-arg="${key === "all" ? "go:random" : `vcat:${esc(key)}`}" data-kb-replace="1">${key === "all" ? "おまかせ10問で確かめる" : "この分類を解いて確かめる"}</button>
      <button type="button" class="kb-btn" data-kb-go="go-card" data-kb-arg="${esc(key)}" data-kb-replace="1">カードをもう一周</button>
      <button type="button" class="kb-btn kb-ghost" data-kb-act="back">語の門へ戻る</button>
    </div>`;
  }

  const v = c.data.vocab.get(d.ids[d.index])!;
  const e = c.data.examples.get(v.exampleIds[0]);
  const back = d.flipped
    ? `<div class="kb-card-back">
        <p class="kb-card-yomi">${esc(v.yomi)}</p>
        ${meaningsHTML(v)}
        ${trapHTML(v)}
        ${e ? `<div class="kb-card-ex"><p class="kb-card-kk">${rubyTextHTML(e.kakikudashi)}</p><p class="kb-card-yaku">${esc(e.yaku)}</p><p class="kb-card-work">${esc(e.work)}</p></div>` : ""}
      </div>`
    : `<p class="kb-card-hint">意味を思い浮かべてから、めくる</p>`;
  const buttons = d.flipped
    ? `<button type="button" class="kb-btn" data-kb-act="card-again">もう一度<small>（あとでまた出す）</small></button>
       <button type="button" class="kb-btn kb-primary" data-kb-act="card-ok">覚えた</button>`
    : `<button type="button" class="kb-btn kb-primary kb-card-flipbtn" data-kb-act="card-flip">めくる</button>`;
  return `${head}
    <div class="kb-progress" aria-label="${d.index + 1}枚目／全${d.ids.length}枚"><span class="kb-progress-num">${d.index + 1}<small> / ${d.ids.length}</small></span><span class="kb-meter"><i style="width:${Math.round((d.index / d.ids.length) * 100)}%"></i></span></div>
    <section class="kb-card${d.flipped ? " is-flipped" : ""}" aria-live="polite">
      <button type="button" class="kb-card-face" data-kb-act="card-flip" aria-label="${d.flipped ? "表に戻す" : "めくる"}">
        <span class="kb-card-cat">${esc(GO_CATS[v.cat].title)}</span>
        <span class="kb-card-word">${esc(v.word)}</span>
      </button>
      ${back}
    </section>
    <div class="kb-card-actions">${buttons}</div>`;
}
